-- ============================================================
-- Gurcu3d (4/4): Günə-özəl push bildirişlərinin KA tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('602f2986-8e86-421e-ab71-94038d048ccf'::uuid, 'ადვოკატივით ლაპარაკობს 🗣️', 'უკვე სიტყვებით ცდილობს თქვენთან მოლაპარაკებას? გეუბნებათ, ცოტა ხანს კიდევ ვითამაშებ და მერე დავიძინებო? მისი მეტყველება შესანიშნავად ვითარდება, თუმცა ნუ დაგავიწყდებათ თქვენი საზღვრების დაცვა.'),
  ('6701933c-47e8-4c97-996b-a27409d87c3c', 'ფაზლი და ლოგიკა 🧩', 'ცდილობს 5-6-ნაწილიანი ფაზლების აწყობას? ის გეომეტრიასა და ლოგიკას სწავლობს. ხელს ნუ შეუშლით მის ამ განმეორებად, თუმცა შემეცნებით მოქმედებებს.'),
  ('a0d7169c-229c-430c-a926-4c31eef15e2c', 'მამის მხარდაჭერა 🫂', 'ღამით ბავშვის გაღვიძებისას აუცილებლად მორიგეობით მიხედეთ მას. ზოგჯერ სიბნელეში მხოლოდ მამის რიტმული მოფერება და სურნელი ამშვიდებს ბავშვს მყისიერად.'),
  ('55bba77e-306b-49e8-94ad-180de8387a8b', 'ლურჯი ვაშლის მოთხოვნა 🍏', 'თვალების გახელისთანავე ყვირილით გთხოვთ ლურჯ ვაშლს. ნუ დაიწყებთ იმის ახსნას, რომ ბუნებაში ასეთი რამ არ არსებობს, და ნუ ჩაუტარებთ ფიზიკა-ბიოლოგიის გაკვეთილს. უთხარით: „ლურჯ ვაშლებს ჯერ კიდევ სძინავთ, მოდი, წითელი გავაღვიძოთ“ — და მის აბსურდულ ლოგიკას ასეთივე აბსურდული, მაგრამ ეფექტური პასუხი გაეცით.'),
  ('5d5d4766-5ced-4cf7-8ea9-3acdffe118cf', 'საბნის აკვიატება 🛏️', 'აი, უკვე უნდა ჩაეძინოს, მაგრამ უცებ ტირილს იწყებს: „საბანი მარცხენა ფეხზე მეხება!“ გულში გაგეღიმოთ სამნახევარი წლის ბავშვის მიერ ძილის გადასადებად მოფიქრებულ ამ ახალ აკვიატებაზე. არაფერი უთხრათ, საბანი გაუსწორეთ და ოთახში შუქი მტკიცედ ჩააქრეთ.'),
  ('8bcf9de1-187f-451e-8f68-1235d768b6ad', 'საეჭვო სიჩუმის საფასური 💄', 'სახლში მოულოდნელად ჩამოვარდნილი 10-წუთიანი სიჩუმის შედეგი: ოთახში შედიხართ და ხედავთ, რომ მას თქვენი უსაყვარლესი ტუჩსაცხით საკუთარი სახეც მოუხატავს და სარკეც. გაბრაზება უკვე გვიანია.'),
  ('42ac5c0d-b412-4999-8839-ddf0e44a9d4b', 'მამის ჯადოსნური მკლავები ✈️', 'მთელი დღე ტარებისგან ხელები გწყდებათ, ის კი კვლავ ენერგიით სავსეა და დაძინებას ჯიუტად ეწინააღმდეგება. მამას დახმარება სთხოვეთ. როცა ის ბავშვს ჰაერში აიყვანს და თვითმფრინავობანას ეთამაშება, ოთახი სიცილით ივსება და მთელი დაგროვილი, ამოუწურავი ენერგია წამებში ქრება.'),
  ('5a50a7bc-7ff1-421e-abac-beffc69e1480', 'ბორდიურზე სიარულის გამოცდა 🧱', 'პარკისკენ მიმავალ გზაზე ჩვეულებრივად სიარულის ნაცვლად, ჯიუტად ცდილობს ბაგირზე მოსიარულესავით ბორდიურის ყველაზე ვიწრო და მაღალ კიდეს გაჰყვეს. ასე მსხვილი მოტორული უნარები და წონასწორობა ვითარდება! ხელი ჩასჭიდეთ და უსაფრთხოება დაუზღვიეთ — მიეცით საშუალება, დაიპყროს ეს პატარა, მაგრამ მისთვის ძალიან მნიშვნელოვანი მწვერვალი.'),
  ('fd37073a-86b1-4420-9d46-293b17c2e64b', 'უხილავ ძაღლთან გასეირნება 🐕', 'ოთახის შუაგულში ხელს დაბლა იწვდის, უხილავ ძაღლს ეფერება და ესაუბრება. ეს წარმოსახვის ყველაზე უმანკო ეტაპია. ჰკითხეთ: „რა ჰქვია ძაღლს?“ შემდეგ ოთახის ერთ კუთხეში წარმოსახვითი წყლის ჯამი დადგით და ამ შესანიშნავ წარმოდგენაში მეორეხარისხოვანი როლი შეასრულეთ.'),
  ('29371981-c485-4102-9d09-323cae4a8b4c', 'გარდერობის ამბოხი 🕶️', 'საუზმეზე მზის სათვალითა და ზამთრის ქუდით მოვიდა და მათ მოხსნაზე კატეგორიულ უარს ამბობს. დაივიწყეთ ესთეტიკა და ის, თუ რას იტყვის ხალხი. საკუთარი გადაწყვეტილების მიღებისა და დაცვის თავისუფლება შეუდარებლად უფრო მნიშვნელოვანი ფსიქოლოგიური საფუძველია, ვიდრე ტანსაცმლის ერთმანეთთან შეხამება.'),
  ('51cdbeb9-6ab2-41f5-bfe2-9e148aedb489', 'სიჩუმის ციფრული საზომი 🤫', 'სახლში ხმაურისგან ყურები გიწივით. როცა ბავშვი ბოლოს და ბოლოს დაიძინებს, ჩართეთ ხმის საზომი. ეკრანზე 0-10 დეციბელამდე შემცირებული ციფრული სიჩუმის ყურება დაღლილი დედის ტვინისთვის საუკეთესო ვიზუალური, დამამშვიდებელი მასაჟია.'),
  ('fca5f016-a334-4b48-86a0-e10c617f28f2', 'ჭიანჭველის მხსნელი 🐜', 'პარკში მიწაზე მყოფი ჭიანჭველის დასაჭყლეტად გადარჩენას ცდილობდა, წინ გადაეღობა და ატირდა? აღფრთოვანდით მისი უსაზღვრო თანაგრძნობითა და გულმოწყალებით.'),
  ('02c49204-da15-4fa6-aab8-953dbda0aa33', 'მე ჭკვიან ზღაპარში 🪄', 'კლასიკური წიგნების კითხვით თქვენი ხმის იოგები დაიღალა. ჩართეთ ჭკვიანი ზღაპრები. მთავარ გმირად თქვენი ბავშვი აქციეთ, ფონად კი ტყის დამამშვიდებელი ხმები შეარჩიეთ და ყოველგვარი ძალისხმევის გარეშე უჩვეულო, ჰიპნოზური ძილის სეანსი შექმენით.'),
  ('b5cdd715-cb24-4a73-93b6-d40eb1d78c2e', 'საზოგადოების ჩუმი ნუგეში 💬', 'ფიქრი, რომ ძველ, თავისუფალ და უდარდელ საკუთარ თავს ვეღარასოდეს დაიბრუნებთ, მოულოდნელად გთრგუნავთ? შეუერთდით Anacan-ის საზოგადოებას. წაიკითხეთ, რომ სხვა დედებიც გადიან ამ რთულ, თუმცა სრულიად ბუნებრივ ემოციებს, რომ ეს დედობის ერთ-ერთი ეტაპია, და ნუგეში იპოვეთ.'),
  ('dbfc71ef-a5a7-4ece-831b-f33ebb8aff4c', 'სიტყვების რემიქსი 🗣️', 'ის სიტყვებს „წყალი“ და „რძე“ აერთიანებს, სრულიად გამოგონილ სიტყვას, მაგალითად, „რძეწყალს“ ქმნის და იცინის. ის საკუთარ ლექსიკონს რემიქსად აქცევს! სიცილით აჰყევით ამ ენობრივ თამაშებში — სწორედ ასეთი ექსპერიმენტებით სწავლობს მისი ტვინი ენის საზღვრებს.'),
  ('4d3c3b0d-80ec-45f4-815f-fb2e6cc34948', 'სიყვარულის უეცარი აფეთქება 🫂', 'ბავშვი, რომელიც დილით გეუბნებოდათ „წადი“, საწოლში ჩაწოლისას კისერზე მაგრად გხვევთ ხელებს და გეუბნებათ: „მთელი სამყაროსხელა სიყვარულით მიყვარხარ“. აი, ეს არის დედობის პარადოქსი! ღრმად შეისუნთქეთ მისი თბილი სუნთქვა და მიეცით უფლება, დღის მთელ დაღლილობას უკვალოდ გაქრეს.'),
  ('50186ca0-d65c-4eb2-80df-487222e57b43', 'დედა, წადი აქედან! 💔', 'როდესაც რომელიმე სურვილს არ უსრულებთ, გიყურებთ და გეუბნებათ: „არ მინდიხარ, წადი აქედან!“ გულთან ახლოს ნუ მიიტანთ. მან ჯერ არ იცის, როგორ მართოს საკუთარი ბრაზი. პირადად ნუ მიიღებთ — უთხარით: „მე აქ ვარ, როცა დამშვიდდები, დავილაპარაკოთ“ და მიეცით სივრცე საკუთარი ემოციების გამოსახატავად.'),
  ('ee0e20bd-35e2-417c-adfc-d1000ee7da40', 'სუპერმარკეტის ადვოკატი 🛒', 'იმის ნაცვლად, რომ სუპერმარკეტში კანფეტის გამო იატაკზე გაწვეს და იფართხალოს, ვაჭრობას იწყებს: „თუ ამას მიყიდი, სახლში წვნიანს შევჭამ“. გილოცავთ, თქვენი პატარა ადვოკატი იზრდება! დავიწყებასთან საბრძოლველად კი საყიდლების სია ღია გქონდეთ, რათა მასთან კამათისას მთავარი მიზანი არ დაგავიწყდეთ.'),
  ('2ee42120-6dce-4972-a1f5-41636027a46e', 'ცუნამი აბაზანაში 🌊', 'აბაზანაში ბანაობა უკვე უბრალოდ სისუფთავე კი არა, პატარა ცუნამის მოწყობის თამაშია. აცადეთ, წყალი ირგვლივ მოაშხეფოს. წყლის ეს მისტიკური, ენერგიის შემავსებელი მაგნიტური ეფექტი მთელი დღის განმავლობაში მასში დაგროვილ ჯიუტ, ნეგატიურ ენერგიას ჩამორეცხავს და კანალიზაციაში გააყოლებს.'),
  ('3a758cd5-028f-4ac8-be02-5dda6a95b453', 'დედას სიზარმაცის უფლება აქვს 🍕', 'დღეს ყველაფერზე ყვირილი გინდათ? სახლში სრული ქაოსია? დალაგებას თავი დაანებეთ და ქურაც არ აანთოთ. გარედან პიცა ან რაც ყველაზე მარტივია, ის შეუკვეთეთ. დაივიწყეთ იდეალური დედის ილუზია — თქვენი ფსიქოლოგიური ჯანმრთელობა შინ მომზადებულ საკვებზე ბევრად ძვირფასია.'),
  ('d683b351-38a0-49ed-a8b1-b2fe98cd3d08', 'დაჟინებული სურვილი, თავად დაისხას 💧', 'დიდი დოქიდან პატარა ჭიქაში წყალი აუცილებლად თავად უნდა დაისხას. წყალი ჯერ მაგიდაზე იღვრება, იქიდან კი იატაკზე. მაგრამ შეხედეთ მის პატარა ხელებს, რომლებიც ტილოს იღებენ და დაღვრილის გაწმენდას ცდილობენ. შეცდომების დაშვებით ის პასუხისმგებლობას სწავლობს — ეს ქაოსი თავად განვითარების პროცესია.'),
  ('746ce0d9-945c-4d05-9518-1097d9f22fcd', 'პატარა მაკრატლის გაცნობა ✂️', 'ბავშვებისთვის განკუთვნილი უსაფრთხო პლასტმასის მაკრატლით ქაღალდის დაჭრას ცდილობს? ეს წვრილი მოტორიკის შესანიშნავი ვარჯიშია! აუცილებლად აღნიშნეთ ეს განვითარების ტრეკერში.'),
  ('d01a4de6-1799-4ace-b8f9-b22ea720b143', '„მე შემომხედე!“ — დაჟინებული მოთხოვნა 👀', 'როცა ტელეფონს უყურებთ ან სხვა საქმით ხართ დაკავებული, მოდის და თქვენს სახეს თავისკენ აბრუნებს? მას თქვენი სრული ყურადღება სჭირდება. დაამყარეთ თვალით კონტაქტი და აგრძნობინეთ, რომ უსმენთ.'),
  ('ee6a7a57-d3a9-4c19-bc94-5bb7b56c8f9c', 'მამის ჯერია 👨‍🍼', 'ღამით ბავშვის გაღვიძებებს მარტო ნუ გაუმკლავდებით. გააღვიძეთ თქვენი პარტნიორიც — გუნდად ყოფნა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('4e5540da-110f-46b1-a6fe-0833314d27a6', 'რა მოვამზადო? 🍲', 'დამატებითი კვების მენიუს იდეები ამოგეწურათ? ინტერნეტში ნუ დაიკარგებით — ახალი გემოები „ჯანსაღი რეცეპტების“ განყოფილებაში აღმოაჩინეთ.'),
  ('7d3efca9-83bd-4ef7-a064-007baae56a2f', 'პერსონალური ზღაპარი 🪄', '„გონიერ ზღაპრებში“ შექმენით განსაკუთრებული ამბავი, რომლის გმირიც თქვენი ბავშვია: მამაცი პატარა, რომელიც ჯადოსნური მაკრატლით სამყაროს აფერადებს.'),
  ('fa3aa9fa-1390-45bd-833a-86ce9790410b', 'დაგეხმარები! 🧹', 'როცა ტანსაცმელს კეცავთ, ცდილობს ხელიდან გამოგართვათ? ის უკვე დიდად გრძნობს თავს. მიეცით პატარა პირსახოცი და მიეცით საშუალება, დაგეხმაროთ.'),
  ('9049cae3-8dbb-4e95-8c21-0965664d904f', 'საიდუმლოს გეტყვი 🤫', 'საწოლში წევს, თვალები თითქმის ეხუჭება და უცებ ამბობს: „დედა, საიდუმლოს გეტყვი“, — და ცდილობს, ძილი გადაიფრთხოს. ძილის გადადების ხელოვნებაში უკვე ოფიციალურად დოქტორობას იცავენ. გაუღიმეთ, უთხარით: „საიდუმლოს სიზმარში მომიყვები“ და მტკიცედ ჩააქრეთ შუქი.'),
  ('a097a156-cfb7-4bbb-a187-0b6a9ba7dade', 'ორცხობილის მხოლოდ კრემი 🍪', 'მრგვალი ორცხობილების შუაგულიდან კრემი ამოლოკა, მშრალი ნაწილები კი მაგიდის კიდეზე ჩამოამწკრივა? გილოცავთ, თქვენ ოფიციალურად გაეცანით 3.5 წლის ბავშვის კვების ფილოსოფიას. „ჯანსაღ რეცეპტებში“ აღმოაჩინეთ უფრო გონივრული, თუმცა სახალისო წასახემსებლები, რომლებიც მის ყურადღებას მიიპყრობს.'),
  ('bf046ede-b62a-43aa-8a59-9305494237e5', '„შენ არ იმღერო!“ — აკრძალვა 🛑', 'ფონად ჩართულ საბავშვო სიმღერას ღიღინით აჰყევით და მან მაშინვე დაიყვირა: „შენ არ იმღერო!“ ოთახის ერთადერთი სოლისტი თავადაა, თქვენი ვოკალური მცდელობები კი მის სცენას ავიწროებს. ნუ გეწყინებათ, სცენა ამ პატარა ეგოისტს დაუთმეთ.'),
  ('6b819068-b681-48a9-82bf-6d4801827c9e', 'დედის კედელთან მზერის შეჯიბრი 🛋️', 'ოთახში ხმაურია, ბავშვი სათამაშოებს ერთმანეთს ურტყამს, თქვენ კი უბრალოდ ცარიელ კედელს მიშტერებიხართ და ფიქრებიდან გათიშულხართ (zoned out). ეს თქვენი ტვინის თავდაცვითი მექანიზმია. ნუ უსაყვედურებთ თავს ამ 5-წუთიანი გაშეშებისთვის — ის ძალების მოსაკრებად და რეალობაში დასაბრუნებლად გჭირდებათ.'),
  ('6b9b4528-1015-4f69-940f-0bb0951b3bab', 'შოკისმომგვრელი კითხვები საჯარო ადგილას 😳', 'ავტობუსში ან მაღაზიაში ხმამაღლა გკითხათ: ამ ქალს რატომ აქვს ასეთი დიდი ცხვირი? ეს სწორედ ის წამია, როცა გინდათ, მიწა გაიხსნას და შიგ ჩაიტანოთ! იმის ნაცვლად, რომ გააჩუმოთ და შეარცხვინოთ, მაშინვე გადაატანინეთ ყურადღება სხვა, ფერად საგანზე და დიპლომატიურად დააღწიეთ თავი სიტუაციას.'),
  ('8d369fcb-2b04-4658-a824-5b34c817cbfd', 'მამის ალოგიკური გამოწვევები 🎲', 'ღამით პიჟამის ჩაცმას რომ თავი აარიდოს, სახლში დარბის. მამა კი უცებ აბსურდულ თამაშს სთავაზობს: აბა, ვნახოთ, თუ შეძლებ ამ პიჟამის დახუჭული თვალებით ჩაცმას? და ბუმ! ბავშვმა ისე ჩაიცვა, ვერც კი გააცნობიერა. მამების ასეთ ალოგიკურ, მაგრამ ეფექტურ თამაშებს გვერდიდან მხოლოდ ტაში ეკუთვნის.'),
  ('5eac5298-1552-4198-9ef8-4a16006b3701', '„მე ბავშვი ვარ!“ — ნოსტალგია 🍼', 'უცებ დაიწყო ბავშვივით ხოხვა, ტირილი და თქმა: მე ბავშვი ვარ, ჩამეხუტე? გაზრდა ზოგჯერ მათაც აშინებთ და სურთ, ჩვილობის ძველ, უსაფრთხო დღეებს შეაფარონ თავი. რამდენიმე წუთით ისე ჩაიხუტეთ და მოეფერეთ, როგორც იმ ძველ დღეებში.'),
  ('bb01fed8-0d6f-4127-8a47-f959e37b46e4', 'ტალახის სუპი 🍲', 'პარკში წყალსა და მიწას ერთმანეთში ურევს, შემდეგ კი სიტყვებით — დედა, შენთვის სუპი მოვამზადე — ტალახს გიწვდით. ზიზღის გამოხატვა არ შეიძლება! წარმოსახვით ისე მიირთვით ეს სუპი, თითქოს უგემრიელესი კერძია.'),
  ('c5e8c723-3ce3-424f-8294-5aece5936ca5', 'სიჩუმის ციფრული სიამოვნება 🤫', 'სახლში ქაოსი როგორც იქნა დასრულდა და ბავშვს ჩაეძინა. ჩართეთ ხმის დონის საზომი და ეკრანზე დააკვირდით ოთახში სიჩუმის დონეს (0-10 desibel). ნულთან მიახლოებული ამ რიცხვების დანახვა დაღლილი დედის ტვინზე მსოფლიოში ყველაზე ძვირადღირებული სპა-სეანსივით მოქმედებს.'),
  ('204c6838-b697-4616-9592-52e0162c6a92', 'ნაკაწრი ბანანზე 🍌', 'ბანანის გაფცქვნისას ზედ პატარა, მილიმეტრის ზომის ნაკაწრი დაინახა და ყვირის: „ეს გაფუჭებულია!“ ბავშვების სწრაფვა ვიზუალური სრულყოფილებისკენ ზოგჯერ სიგიჟის დონეს აღწევს. ის ნაწილი დანით მოაჭერით და სიტყვებით „გადავარჩინე!“ ეს პატარა დრამა დაასრულეთ.'),
  ('49d8e195-1371-46c6-a98a-c6f38e78e098', 'კარის ჩაკეტვის მისია 🚪', 'განსაკუთრებულ სიამოვნებას ანიჭებს სახლში ყველა ოთახის კარის შიგნიდან ჩაკეტვა და თქვენი გარეთ დატოვება. პირადი სივრცის მისეული აღქმა ნამდვილ რევოლუციას ახდენს. მიიღეთ ზომები, რომ თითები კარში არ მოჰყვეს, თუმცა ძალიან ნუ შეუშლით ხელს თამაშში, რომლითაც საკუთარ ტერიტორიას აცხადებს.'),
  ('524b4634-31bf-4fa3-860b-d29e08cc3c10', 'ზღაპრის განსხვავებული ხმის ტონები 🪄', 'ამ საღამოს „ჭკვიანი ზღაპრები“ ჩართეთ, მაგრამ ტექსტი განსხვავებული ხმებით წაიკითხეთ. დათვს ბოხი ხმა მიეცით, ჩიტს კი — წვრილი და ოთახში პატარა თეატრი მოაწყვეთ. ეს ერთფეროვნებას არღვევს და ბავშვის ყურადღება მყისიერად გადააქვს ზღაპარში, იქიდან კი — ძილში.'),
  ('603225e8-0807-426b-b793-892dfeb9e281', 'ჩურჩულით აღმოჩენები სიბნელეში 🌙', 'ოთახში შუქი მთლიანად ჩააქრეთ. გვერდით მიუწექით და ძალიან ხმადაბლა, ყურში ჩასჩურჩულეთ დღის განმავლობაში მომხდარი ამბები ან ის, რაც მის ხასიათში ყველაზე მეტად მოგწონთ. ჩურჩული ყველაზე ჯადოსნური მეთოდია, რომელიც ტვინს ძილისთვის ამზადებს და გარშემო ხმაურს ავიწყებს.'),
  ('60fcf611-529f-4586-9532-af738483766f', 'ქოლგა სახლში ☂️', 'გარეთ მზე ანათებს, მას კი სახლში გაშლილი ქოლგით სიარული სურს. მისი წარმოსახვა ფიზიკურ გარემოს არ ემორჩილება. თუ სახლში თავისუფალი ადგილი გაქვთ, მიეცით საშუალება, ქოლგის ქვეშ პატარა ბანაკი მოიწყოს. ბავშვების ლოგიკას საზოგადოებრივი ნორმებით ნუ ჩაახშობთ.'),
  ('831decae-1343-4bbb-bf11-1f398cc1bc2d', '„არას“ გამოცდა სუპერმარკეტში 🛒', 'სუპერმარკეტის შუაგულში კანფეტი მოითხოვა, თქვენ „არა“ უთხარით და მან ტირილი დაიწყო. გარშემომყოფთა განმკიცხავი მზერის მიუხედავად, გადაწყვეტილება არ შეცვალეთ. თქვენ შესანიშნავი დედა ხართ! ნურაფერს დაივიწყებთ — თვალი საყიდლების სიაზე გეჭიროთ, რათა სუპერმარკეტიდან სწრაფად გამოხვიდეთ.'),
  ('1d613098-d421-410e-ae85-8cfd9552b432', 'რატომ ახსენე ჩემი სახელი უმიზეზოდ? 😤', 'თქვენ უბრალოდ უთხარით: „მოდი, საჭმელი მზადაა“, ის კი გაბრაზდა და ტირილით გკითხათ: „რატომ ახსენე ჩემი სახელი?“ ამ ასაკში ემოციები იმდენად არეულია, რომ ზოგჯერ არაფრის გამოც კი ნაწყენდებიან. ნურაფერს აუხსნით — 2 წუთის შემდეგ თვითონვე გაიქცევა საჭმელად.'),
  ('ca0366a7-8e5e-4057-8bed-6cb2f6dcfa02', 'ხელოვნური ინტელექტი და უცნაური ფობიები 🤖', 'უცებ იმ წითელი მანქანის შეეშინდა, რომლითაც ყოველთვის თამაშობდა? თუ აუხსნელი ფობიები გაშფოთებთ, დახურეთ ტრავმული ისტორიებით სავსე ინტერნეტფორუმები. Anacan AI-სგან მიიღეთ მეცნიერული და დამამშვიდებელი პასუხი 3.5 წლის ბავშვის წარმოსახვის უცნაურობების შესახებ.'),
  ('cacabcad-105f-4eff-bcae-aa81bf6e1cbd', 'ფილმის ყურება წყვილში... 🎬', 'ბავშვმა დაიძინა! როგორც იქნა, პარტნიორთან ერთად ფილმის საყურებლად დივანზე მოკალათდით, მაგრამ მე-10 წუთზე ორივეს ღრმად ჩაგეძინათ. ეს თქვენი რეალობაა. ერთმანეთზე მიყრდნობილებს რომ ჩაგეძინათ, ეს დაღლილი სცენა ნამდვილი გუნდური მუშაობის გამოხატულებაა.'),
  ('45baf1a1-9599-41ad-8361-b1f8a05e79a2', 'ნამცეცები საწოლში 🍞', 'დილით თვალებს ახელთ და ხედავთ, რომ საწოლი კრეკერის ნამცეცებითაა სავსე. როგორც ჩანს, გამთენიისას თვითონ მოუმზადებია საუზმე. ყვირილის ნაცვლად, პრობლემების დამოუკიდებლად გადაჭრის ეს უნარი განვითარების ტრეკერში სახალისო მოგონებად ჩაინიშნეთ.'),
  ('5b590891-270c-48fa-a5d7-d69f319ed48e', 'მამისგან მხრების მასაჟი 💆‍♂️', 'დღეს დიდხანს იდექით ფეხზე, ბავშვს დასდევდით და იატაკიდან სათამაშოებს აგროვებდით — წელი გტკივათ. როგორც კი ბავშვი დაიძინებს, პარტნიორს სთხოვეთ, მხრებზე 10-წუთიანი მასაჟი გაგიკეთოთ. თქვენ ოჯახის ბურჯი ხართ, ბურჯებს კი აუცილებლად სჭირდება დასვენება და ძალების აღდგენა.'),
  ('5ff3402c-285a-4d58-a123-bc33ce162448', 'მე თვითონ გავაკეთებ! 🛑', 'აუცილებლად თვითონ უნდა, რომ ფეხსაცმლის თასმები შეიკრას, მაგრამ არ გამოსდის, ბრაზდება და თქვენს დახმარებასაც აგრესიულად უარყოფს. ღრმად ჩაისუნთქეთ. მისი მომავლისთვის დაუზიანებელი თავმოყვარეობა უფრო მნიშვნელოვანია, ვიდრე დარღვეული განრიგი. დაელოდეთ.'),
  ('8d87e4f8-f5ae-4ad1-80cc-5a4fd0448346', 'ტრაგედია „მან შემომხედა!“ 👀', 'პარკში სხვა ბავშვმა უბრალოდ შეხედა და ამის გამო თქვენი ბავშვი ხმამაღლა ატირდა? ბავშვისთვის, რომელიც სოციალურ საზღვრებს ახლა ეცნობა, სხვისი მზერაც კი შეიძლება პირად სივრცეში ჩარევად აღიქმებოდეს. ჩაეხუტეთ და ყურადღება გადაატანინეთ, უთხარით: „ის უბრალოდ შენს ლამაზ მაისურს უყურებდა“.'),
  ('b272e283-3b37-4825-9917-d8f7f4f54d69', 'სიმშვიდე ჭკვიანი ზღაპრებით 🪄', 'ოთახში დარბის და საწოლში ჩაწოლაზე უარს ამბობს. ჩააქრეთ მკვეთრი განათება. ჭკვიან ზღაპრებში საინტერესო ამბავი შექმენით და წაუკითხეთ.'),
  ('ef54bc8d-fa9d-46df-a5e1-6c01e83dfefc', 'სათამაშოების მწკრივად დალაგება 🚗', 'ყველა მანქანა ოთახის ერთი ბოლოდან მეორემდე მილიმეტრული სიზუსტით დაალაგა და ერთის ადგილიდან დაძვრის უფლებასაც არავის აძლევს. ეს ვიზუალური წესრიგის მოთხოვნილებაა. შორიდან ჩუმად დააკვირდით ამ პატარა არქიტექტორის ნამუშევარს და ნუ დაურღვევთ.'),
  ('0136ed32-a803-4c48-aa0d-ab3379945e1c', 'საზოგადოებაში ჩუმ მკითხველად ყოფნა 💬', 'ძალიან დაიღალეთ და არ გსურთ, ვინმეს რამე აუხსნათ ან თქვენი დარდი გაუზიაროთ. შედით Anacan-ის საზოგადოებაში და უბრალოდ მკითხველი იყავით. იმის ნახვა, თუ როგორ უმკლავდებიან სხვა დედები იმავე აბსურდულ კრიზისებს, ყველაზე ძლიერი ჩუმი თერაპიაა.'),
  ('b9bc7eed-7b9f-4aa8-8301-118abf554ade', 'კრიზისი კოვზის არასწორი ზომის გამო 🥄', 'წვნიანი დიდი კოვზით მიეცით და კინაღამ რევოლუცია დაიწყო: „მე პატარა კოვზი მინდოდა!“ მიუხედავად იმისა, რომ საჭმელი იგივეა, მისი ლოგიკით კოვზის ფიზიკური ზომა საჭმლის გემოსაც ცვლის. ნუ შეეკამათებით, უბრალოდ გამოუცვალეთ კოვზი და ენერგია დაზოგეთ.'),
  ('c2cb9b1d-61a5-43c0-97ec-813152f9cfe1', 'აკვიატება „დამაფარე!“ 🛏️', 'აი, უკვე უნდა ჩაეძინოს, მაგრამ საბნის ბოლო გაიხსნა და ყვირის: „დამაფარე!“ მისთვის სასიცოცხლოდ მნიშვნელოვანია, რომ საბნის კიდეები აუცილებლად სწორად იყოს გასწორებული. საბანი ისე გაუსწორეთ, თითქოს დაუთოებულია, და ძილის ამ სასაცილო რიტუალებზე გულში გაგეღიმოთ.'),
  ('4aca275a-17a5-44c6-88b5-fa54de701839', 'პლასტირის სიყვარული 🩹', 'მან სხეულზე უხილავი ჭრილობა იპოვა და დაჟინებით მოითხოვს, რომ იქ პლასტირი დააკრათ. ეს ფიზიკური ტკივილი კი არა, უბრალოდ დედის ყურადღებისა და სითბოს მოთხოვნილებაა. დააკარით ის პატარა პლასტირი და აკოცეთ — დაგვიჯერეთ, თქვენი დღე გადარჩენილი იქნება.'),
  ('6549682b-784d-4e30-b184-53c2ea51b45f', 'სიჩუმის ვიზუალური სიამოვნება 🤫', 'სახლში ქაოსი როგორც იქნა დასრულდა და ბავშვმა დაიძინა. ჭურჭლის გასარეცხად ნუ გაიქცევით! ჩართეთ ხმის საზომი, დააკვირდით ოთახში გამეფებულ სრულ სიჩუმეს (0-10 დეციბელი) და 15 წუთის განმავლობაში შეიგრძენით, როგორ ისვენებს თქვენი გონება და როგორ გაჯანსაღებთ ეს ვიზუალური სიმშვიდე.'),
  ('c51feab8-8101-47a7-82b7-0a8e946ff974', 'ქვიშის არქიტექტურა 🏰', 'პარკის ქვიშის მოედანზე ისე ღრმად თხრის, თითქოს განძს ეძებს. თავიდან ფეხებამდე ტალახშია. მაგრამ ნუ შეუშლით ხელს აღმოჩენის ამ მომენტში. ამინდის შესაბამისად წინასწარ შერჩეული ტანსაცმელი, რომლის დასვრაც არ დაგენანებათ, საშუალებას მოგცემთ, ამ სანახაობას სტრესის გარეშე უყუროთ.'),
  ('95e37724-7f25-4dc6-a06e-d194ca45d333', 'საღამოს ვარჯიში — მამაზე ხტუნვა 🤸‍♂️', 'ენერგია ვერ დახარჯა და დასაძინებლად წასვლა არ სურს. მამა დივანზე დააწვინეთ და ბავშვს მის ზურგზე ხტუნვის უფლება მიეცით. მამის მიერ გამოცემული სასაცილო ხმები ოთახს სიცილით აავსებს, ზედმეტი ენერგია კი წამებში დაიხარჯება.'),
  ('9680e706-6c53-46d8-b37d-e2b2ed358ee7', 'დედის ზრუნვა საკუთარ თავზე 🥗', 'მის დასანაყრებლად 3 განსხვავებული მენიუ მოიფიქრეთ, თავად კი ისევ მშიერი დარჩით? კვების გეგმის განყოფილებიდან შეარჩიეთ არა მხოლოდ ბავშვებისთვის, არამედ დედებისთვისაც განკუთვნილი, ენერგიის მომცემი, რკინითა და კალციუმით მდიდარი სადილი, რომელიც 10 წუთში მზადდება, და იგრძენით, რომ თქვენც იმსახურებთ ზრუნვას.'),
  ('c0f71481-4d8f-40e3-87af-c4432426cfab', 'თამაში „ვინ ხარ?“ 🎭', 'დილით ძალიან სერიოზული სახით გიყურებთ და გეუბნებათ: ვინ ხარ? დედაჩემი სად არის? წარმოსახვის განვითარების მწვერვალია! აჰყევით თამაშში: მე მეზობელი დეიდა ვარ, დედაშენი მალე მოვა — უთხარით შეცვლილი ხმით და ეს შესანიშნავი თეატრალური წარმოდგენა განაგრძეთ.'),
  ('17737c7f-74cb-4797-867c-90a8c03b4bfe', 'ტუალეტის ქაღალდის ხელოვნება 🧻', 'რამდენიმე წუთის სიჩუმე... ოთახში შესვლისას კი ხედავთ, რომ ტუალეტის ქაღალდი მთლიანად გაუშლია და მთელ სახლში გაუფენია! გაბრაზების ნაცვლად, შეაგროვეთ ქაღალდები და ერთად გააკეთეთ თოვლის კაცი ან ბურთი. ქაოსს ყვირილით კი არა, შემოქმედებითად გაუმკლავდით.'),
  ('300e5d4c-57c8-45bf-bdcd-829a6024697a', 'ყურში ჩაჩურჩულებული სიყვარულის სიტყვები 💖', 'მთელი დღე ჭკუიდან გადაგიყვანათ და ყველაფერზე გეწინააღმდეგებოდათ. ახლა კი საწოლში ისეთი უმანკო სახით სძინავს... გვერდით მიუწექით და ყურში ჩასჩურჩულეთ, როგორ გიყვართ და რა კარგი საქმეები გააკეთა დღეს. ბავშვები ძილშიც კი გრძნობენ დედის სიყვარულით სავსე ხმას.'),
  ('42d87f04-8d19-4c11-b1e4-703ee34de8db', 'სარეცხი მანქანის აღმოჩენა 🧺', 'სარეცხი მანქანის წინ ზის და მბრუნავ ტანსაცმელს ისე ჩაჰყურებს, თითქოს მულტფილმს უყურებდეს. ეს სრულიად უფასო და გონების დამამშვიდებელი გასართობია. ხელს ნუ შეუშლით — თქვენც ისარგებლეთ ამ შესაძლებლობით და დაისვენეთ.'),
  ('56f07d8f-4184-4cda-b356-e566ad65a81d', 'ზღაპრიდან გაქცევის მცდელობები 🏃‍♂️', 'ზღაპრის კითხვისას ყოველ ხელსაყრელ მომენტში საწოლიდან ხტება და გარბის, ვითომ სათამაშო უნდა მოიტანოს. ძილს არ ნებდება. მოულოდნელად ძალიან დაუწიეთ ხმას და ჩურჩულით განაგრძეთ კითხვა. თქვენს გასაგონად იძულებული გახდება საწოლში დაბრუნდეს, ყურადღებით მოგისმენთ და ჩაეძინება.'),
  ('6cd2dfdf-7fcd-4bc3-bbbb-00a4d393d5f8', 'მე უკვე დიდი ვარ, ყავას დავლევ! ☕', 'თქვენი ფინჯნისკენ იწევს და მტკიცედ ამბობს: მე უკვე დიდი ვარ, მეც დავლევ ყავას. მას უბრალოდ სურს, თქვენი სამყაროს ნაწილი გახდეს. მის პატარა ფინჯანში ცოტაოდენი რძე და კაკაო ჩაასხით, უთხარით: ნახე, ეს შენი საბავშვო ყავაა და ფინჯნები ერთმანეთს მიუჭახუნეთ.'),
  ('7a51f55e-c494-489a-927c-6f2193813549', 'ამინდი და ფენებად ჩაცმის ტაქტიკა ⛅', 'გაზაფხულის მოახლოებასთან ერთად ამინდი ცვალებადია: დილით ცივა, შუადღით კი ცხელა. ამინდისა და ჩაცმის ინსტრუმენტი შეგახსენებთ, რომ ბავშვს ხახვის პრინციპით, ანუ ფენებად ჩააცვათ. პარკში, როცა დასცხება, თითო ფენა გახადეთ, რათა ბავშვიც არ გაოფლიანდეს და თქვენც ზედმეტად არ ინერვიულოთ.'),
  ('063d0e5f-8a19-45c6-b301-96c01e527e0a', 'მოპარული ცხვირის თამაში 👃', 'ეუბნებით: „ცხვირი მოგპარე!“ და ცერა თითს აჩვენებთ, მას კი ეს მართლა სჯერა და ტირილს იწყებს! 3.5 წლის ბავშვის წარმოსახვას ზოგჯერ რეალობისა და ილუზიის ერთმანეთისგან გარჩევა უჭირს. მაშინვე უთხარით: „აჰა, უკან დაგიბრუნე“, ცხვირზე აკოცეთ და ეს პატარა ტრავმა ღიმილად აქციეთ.'),
  ('31689193-e8a3-408a-bec9-cc30d1fc08c4', 'ჩუმი მზერით საუბარი პარტნიორთან 🥂', 'ბავშვმა როგორც იქნა დაიძინა. თქვენ და თქვენი პარტნიორი დივანზე გვერდიგვერდ სხედხართ და საუბრის ძალაც კი აღარ გაქვთ. უბრალოდ სიჩუმეში უყურებთ ერთმანეთს და იღიმით. ეს უხმო მზერა საუკეთესო გზაა იმის სათქმელად, რომ ამ ქაოსს შესანიშნავად უმკლავდებით.'),
  ('7834ecb1-6218-4b7b-a3ed-c138894407b9', 'ხელოვნური ინტელექტი და მოულოდნელი სიჯიუტე 🤖', 'ბავშვი, რომელიც გუშინამდე მშვიდად იყო, დღეს ყველაფერზე აგრესიულად რეაგირებს? ინტერნეტში შემაშინებელ მიზეზებს ნუ მოძებნით. ჰკითხეთ Anacan AI-ს განვითარების ამ ნახტომის (mental leap) ფსიქოლოგიური მიზეზების შესახებ და პედიატრების მიერ დამოწმებული პასუხით თქვენი შფოთვა გააქარწყლეთ.'),
  ('9dcc2901-fb6b-4d84-a478-46c76064f671', '„ეს მე ვიპოვე“ — მესაკუთრე პატარა 🔑', 'იატაკიდან ტელევიზორის პულტს ან მამას გასაღებს იღებს და ამტკიცებს: „ეს მე ვიპოვე, ჩემია!“ მისთვის პოვნა დასაკუთრებას ნიშნავს. ძალით ნუ წაართმევთ. უთხარით: „გმადლობ, რომ ჩემთვის იპოვე“, ყურადღება სხვა სათამაშოზე გადაატანინეთ და ნივთი ასე დაიბრუნეთ.'),
  ('c3b5e358-e6dc-46cb-a0bf-1d51adcfbfec', 'მინი-სპა სააბაზანოში 🛀', 'ამ საღამოს აბაზანა მხოლოდ ბავშვს კი არა, საკუთარ თავსაც მოუმზადეთ. მას შემდეგ, რაც ბავშვი დაიძინებს — თბილი წყალი, ცოტაოდენი ქაფი და სააბაზანოში ანთებული ერთი სანთელი. კარი ჩაკეტეთ და სულ რაღაც 15 წუთით დედის როლიდან გამოხვედით და კვლავ საკუთარ თავს დაუბრუნდით.'),
  ('cfb02ba9-2584-45e0-a1c3-ce6672adabe6', 'პატარა პარიკმახერის მცდელობა ✂️', 'ოთახში შესვლისას ხედავთ, რომ ბავშვს ხელში მაკრატელი უჭირავს და თოჯინას თმის შეჭრას ცდილობს. ასეთი სანახაობა ყველა დედის კოშმარია. გაბრაზების გარეშე გამოართვით მაკრატელი და ეს პარიკმახერული მცდელობა ბავშვის ფოტოსესიაზე სახალისო მოგონებად შემოინახეთ.'),
  ('175e4578-dab7-4e75-8a87-dd96baf6d2c6', 'დააბრუნე სიმღერა! 🎶', 'რადიოში გაჟღერებული სიმღერა დასრულდა, მას კი მისი თავიდან მოსმენა სურს. უხსნით, რომ ეს პირდაპირი ეთერი იყო და სიმღერა უკვე დამთავრდა. მაგრამ ის ტირის და გაიძახის: „დააბრუნე!“ ბავშვის ტვინს ჯერ არ ესმის პირდაპირი ეთერის პრინციპი. ყურადღების გადასატანად თავად დაიწყეთ ამ სიმღერის განსხვავებული, სასაცილო ხმით შესრულება.'),
  ('a0a2a59b-c696-48e8-beb8-ba5ae29c9bb7', 'ზედმეტი რამ საყიდლების სიაში 🛒', 'მაღაზიაში წასვლამდე საყიდლების სია გახსენით და დაინახეთ, რომ ბავშვი უკნიდან მოგეპარათ, ტელეფონის ეკრანზე თითის დაჭერით კი სიაში ზედიზედ გაუგებარი ასოები და შოკოლადი დაამატა. დიახ, ისინი ციფრულ სამყაროს ძალიან სწრაფად ითვისებენ!'),
  ('f9e8851b-f40e-4ed9-a246-2e1405232755', 'ჩაი სიჩუმეში ☕', 'ბავშვმა ოთახის შუაგულში სათამაშოები მწკრივად დაალაგა და თავისთვის თამაშობს. გთხოვთ, ეს ძვირფასი წამები სახლის დაგვას ნუ შეალევთ! მოკალათდით დივანზე, ყავა ან ჩაი ჯერ კიდევ ცხელი დალიეთ და 10 წუთის განმავლობაში არაფერზე იფიქროთ — უბრალოდ დატკბით ამ სიჩუმით.'),
  ('92b2cc3b-1b0f-4e45-a121-5ff8bfe1a92e', 'ძილის ტაიმერის ტაქტიკა ⏱️', 'როგორც კი დაძინების დრო დგება, უეცრად სწყურდება, ტუალეტში წასვლა უნდა ან კედელს ემშვიდობება? დააყენეთ ტაიმერი. შემოიღეთ წესი: „როგორც კი ზარი დარეკავს, ყველა იძინებს“ — ასე ამ უსასრულო დამშვიდობებასა და ოსტატურ მანიპულაციას კამათის გარეშე დააღწევთ თავს.'),
  ('9d39f5c1-6418-4ab4-8bba-64b21fccd4ac', 'ნამდვილი მხატვარი კედელს ირჩევს 🖍️', 'რამდენიმეწამიანი სიჩუმე სახიფათო აღმოჩნდა. ოთახში შესულმა დაინახეთ, რომ ბავშვმა კედელზე ფლომასტერით ხელოვნების ნიმუში შექმნა. ღრმად ჩაისუნთქეთ. მისი ნატიფი მოტორული უნარები ვითარდება, კედელი კი მაინც გაიწმინდება. აუცილებლად გადაუღეთ ამ შედევრს ფოტო, რათა მომავალში ერთად იცინოთ.'),
  ('dda9eb22-cebb-4f1b-962b-3223d17b83eb', 'Anacan საზოგადოების ძალა 💬', 'ფიქრი — „რატომ არის ჩემი ბავშვი ასეთი ჯიუტი?“ — მოსვენებას არ გაძლევთ. შეუერთდით Anacan საზოგადოებას. როდესაც სხვა დედების ოჯახებში მომხდარ მსგავს აბსურდულ კრიზისებზე წაიკითხავთ, მიხვდებით, რომ მარტო არ ხართ და სრულიად ნორმალურ გზას ადგახართ.'),
  ('1c56259d-5943-4110-9eaf-5c1870b222b1', 'დილაუთენია დამალობანა 🙈', 'თქვენ სამსახურში ან საბავშვო ბაღში გაგვიანდებათ, ის კი ფარდის უკან იმალება და გეუბნებათ: „მიპოვე!“ მიუხედავად იმისა, რომ ნერვები დაჭიმული გაქვთ, ყვირილი ამ პროცესს კიდევ უფრო გაახანგრძლივებს. უთხარით: „ნეტავ, სად არის ჩემი საყვარელი ბავშვი?“ 2 წუთით ჩაერთეთ თამაშში, იპოვეთ და სამალავიდან გამოიყვანეთ.'),
  ('7b148d61-8829-4863-ab9e-6d4a0bb51f81', 'საჭმლის ფერების მიხედვით გადარჩევა 🍅', 'თეფშზე მოთავსებულ საკვებს ფერისა და ფორმის მიხედვით არჩევს, მწვანე ნაწილებს კი განზე სწევს. გადადით კვების გეგმაში. აღმოაჩინეთ, როგორ გადააქციოთ ეს ბოსტნეული შეუმჩნეველ პიურედ და დამალოთ გემრიელ სოუსებში, რათა ამ თამაშში ჩუმად გაიმარჯვოთ.'),
  ('b42730c5-7949-4ebf-93b6-63b027cfa615', 'მამის გამოგონილი ამბები 📖', 'ამ საღამოს ოთახში თქვენი ხმა აღარ უნდა ისმოდეს. ზღაპრების წიგნი მამას მიეცით და სთხოვეთ, ამბავი განზრახ უკუღმა, სახალისოდ და აბსურდულად მოჰყვეს. თქვენ კი გვერდიდან უყურეთ, როგორ სიამოვნებს ბავშვს მისი შესწორება და როგორ გულიანად იცინის მამასთან ერთად.'),
  ('4e6a6d24-79a1-45e7-b7a8-72b6ff0e22f5', 'ბრაზის გადმოტანა განწყობის დღიურში 📝', 'ვერავინ ამჩნევს, რამდენად იღლებით სახლში? განწყობის დღიური თქვენი ყველაზე ჩუმი მესაიდუმლეა. ჩაწერეთ იქ ყველა დეტალი, რომელმაც დღეს ჭკუიდან გადაგიყვანათ, შემდეგ კი ეკრანს შეხედეთ და იგრძენით, როგორ მსუბუქდება გონება და ქრება სადარდებელი.'),
  ('5c983784-bca8-4998-adca-b16664e5be99', 'სახლში ქუდით სიარული 🧢', 'ზამთრის ქუდის სახლში ტარება სურს. დაჟინებით ითხოვს და არ იხდის. დაივიწყეთ საზოგადოებრივი ნორმები. თუ ოთახში ნორმალური ტემპერატურაა, მიეცით საშუალება, მთელი დღე ამ განსხვავებული და სახალისო იერით გაატაროს, რათა მისი შემოქმედებითობა და გადაწყვეტილების მიღების თავისუფლება არ შეზღუდოთ.'),
  ('9d6dd60c-7863-4418-b9e4-e9cffd903339', '„შენ არ მისმენ!“ — მტკივნეული ფრაზა 😠', 'როცა ტელეფონს უყურებთ ან საჭმელს ურევთ, ბავშვი მოდის, სახეს თავისკენ გაბრუნებინებთ და გეუბნებათ: „მე შემომხედე!“ ის მართალია. მას მხოლოდ თქვენი ფიზიკური სიახლოვე კი არა, თქვენი სრული ყურადღება სჭირდება. შეწყვიტეთ საქმე და მხოლოდ 3 წუთის განმავლობაში თვალებში უყურეთ და ყურადღებით მოუსმინეთ.'),
  ('45e62ed0-8906-4bfa-998b-97725faac7dc', 'პარკში გაცნობის მცდელობები 🤝', 'პარკში მისთვის უცნობ ბავშვთან მიდის და თავს აცნობს: ჩემი სახელია... სოციალური უნარები გასაოცარი სისწრაფით უვითარდება. განვითარების ტრეკერში მისი კომუნიკაციის ეს გაბედული მცდელობები პიროვნული განვითარების საამაყო მოგონებად შეინახეთ.'),
  ('6538fe5a-5021-49de-8c05-b4294e3a7259', 'ჯიუტი „არას“ პერიოდი 🛑', 'წყალი გინდა? — არა! თუმცა 5 წამის შემდეგ წყლის გამო ტირის. ეს გადაწყვეტილებების შედეგების გამოცდის პერიოდია. უარს იმაზეც კი ამბობენ, რაც სინამდვილეში სურთ. წყალი მაგიდაზე დაუდგით, ნუ დააძალებთ — შინაგან ბრძოლას რომ დაასრულებს, თავად დალევს.'),
  ('c5259254-085d-4cab-81d7-de92adaaa126', 'მარტივად დაძინება ჭკვიანი ზღაპრებით 🪄', 'კლასიკური წიგნები უკვე ზეპირად იცით. გახსენით ჭკვიანი ზღაპრები, მთავარ გმირად თქვენი ბავშვი აქციეთ, დასაპყრობ ადგილად კი მისი ოთახი აირჩიეთ და შექმენით უჩვეულო, ძალისხმევის გარეშე მოსასმენი დაძინების სესია — ამასობაში თქვენც დაისვენეთ.'),
  ('3267eb25-4eba-48a9-b86e-272c45f62299', 'ჩრდილების თეატრი ბნელ ოთახში 🐰', 'ამბობს, რომ სიბნელის ეშინია და საწოლიდან გარბის. ოთახში ყველა შუქი ჩააქრეთ, ფანარი ჩართეთ და კედელზე ხელებით ფრინველისა და ძაღლის ჩრდილები გამოსახეთ. სიბნელე, რომლისაც ეშინოდა, მისთვის რამდენიმე წამში თეატრად გადაიქცევა.'),
  ('4ac972f2-0058-41fe-9a63-593036a6aa46', 'სიმშვიდის შენარჩუნება ხმის საზომით 🤫', 'სახლში ხმაური ყურებში გიზუზუნებთ. როდესაც ბოლოს და ბოლოს დაიძინებს, გაააქტიურეთ ხმის საზომი. ეკრანზე ნულთან მიახლოებული რიცხვებისა და ციფრული სიჩუმის ყურება დაღლილი დედის ტვინისთვის საუკეთესო ვიზუალური მასაჟია.'),
  ('b4510edb-beed-40b8-b0ad-884291f78f89', '„შენ არ დაჯდე!“ — დიქტატურა 🪑', 'დივანზე დაჯდომა გსურთ, ის კი მორბის და გეუბნებათ: აქ ჩემი დათუნია დაჯდება, შენ ადექი! ცდილობს, სახლი თავად მართოს. მისი ნების მკვეთრად გატეხვის გარეშე უთხარით: დათუნია აქ დაჯდეს, მე კი მის გვერდით დავჯდები — ასე შეინარჩუნებთ წონასწორობასა და მშვიდობას ოთახში.'),
  ('a33e5975-6dcb-4e61-93db-f52a429ffcb8', 'Anacan AI: რატომ იტყუებიან ბავშვები? 🤥', '„წყალი მე არ დამიქცევია, სათამაშომ დაღვარა“, — თქვა მან. იტყუება თუ უბრალოდ ფანტაზიას იყენებს? ნუ მოძებნით ინტერნეტში შემაშინებელ პასუხებს. Anacan AI-სგან შეიტყვეთ, რომ 3.5 წლის ბავშვის ასეთი ფანტაზიები განვითარების სრულიად ნორმალური ეტაპია და დამშვიდდით.'),
  ('f03a726a-5a9c-4eda-ab04-4d6b21a432cd', 'პარტნიორთან სიცილის შეტევა 🥂', 'ბავშვმა როგორც იქნა დაიძინა. დღის განმავლობაში მომხდარ იმ აბსურდულ ამბავს, რომელმაც ჭკუიდან გადაგიყვანათ, პარტნიორს უყვებით და უცებ ორივე სიცილით იხოცებით. დიახ, ასეთი სიცილი მშობლობის ერთ-ერთი ყველაზე სასიამოვნო ჯილდოა.'),
  ('fce85c76-de6a-416c-a8d9-e7fd462bd967', 'სათამაშოების აბაზანაში წაღება 🛀', 'ბანაობა არ უნდა, მაგრამ მას შემდეგ, რაც ყველა მანქანასა და პლასტმასის დათუნიას აბაზანაში მოაგროვებს, წყალში ჩასვლას თანხმდება. ხელს ნუ შეუშლით. აბაზანაში ჩაყრილი ეს სათამაშოები საუკეთესო დამხმარეებია, რომლებიც მას წყლის დამამშვიდებელი ეფექტით ტკბობაში ეხმარება.'),
  ('383239b8-7f85-4507-9f51-cdc8a13d1e8f', 'მაკარონის სიყვარული 🍝', 'გუშინდლამდე საყვარელ ხორცზე დღეს უარს ამბობს და მთელი დღე მხოლოდ მაკარონის ჭამა სურს. მის ნებას ნუ შეებრძოლებით. ისწავლეთ, როგორ შეურიოთ ჯანსაღ რეცეპტებში მაკარონს ცილები და ბოსტნეული შეუმჩნეველი სოუსის სახით და გაიმარჯვეთ.'),
  ('6fb57a61-aa7b-441f-afc3-ed5b09208ed5', 'ცეკვა სარკის წინ 🪞', 'სარკის წინ დგება, მღერის და სხვადასხვა საცეკვაო მოძრაობას ცდის. ასე საკუთარი სხეულის რიტმსა და გარეგნობას იკვლევს! განვითარების ტრეკერში სიხარულით აღნიშნეთ მისი სხეულის გაცნობიერებისა და რიტმის შეგრძნების ეს გამოვლინება.'),
  ('86182307-b484-4518-a023-a22ef5f8216d', 'ჩურჩულით შესრულებული ძილის დუეტი 🌙', 'საწოლში იმდენად აქტიურია, რომ ვერ იძინებს. ხმის აწევის ნაცვლად, მოულოდნელად დაუწიეთ ხმას და მისი საყვარელი სიმღერის ჩურჩულით მღერა დაიწყეთ. როცა ბავშვი თქვენ მოსასმენად ყურადღებას მოიკრებს, მისი ტვინი ავტომატურად ჰიპნოზურ მდგომარეობაში გადავა და ძილის რეჟიმზე გადაერთვება.'),
  ('4cd431fe-3e79-44d3-a7ca-53965a307626', 'თმის დავარცხნა მტერია 🪮', 'სავარცხლის დანახვისთანავე ყვირილით გარბის ოთახიდან. შეწყვიტეთ ბრძოლა. ჯერ სავარცხელი მას მიეცით და მიეცით საშუალება, თქვენი ან თავისი თოჯინის თმა დავარცხნოს. როგორც კი იგრძნობს, რომ სიტუაციას თავად აკონტროლებს, შემდეგ თქვენც მოგცემთ მისი დავარცხნის უფლებას.'),
  ('7de027d7-5609-44f6-aeb7-25a62639a344', 'მხარდაჭერა Anacan-ის საზოგადოებაში 💬', 'ხანდახან მოულოდნელად გიპყრობთ და გახრჩობთ ფიქრი: „ვეღარასდროს ვიქნები ისეთი თავისუფალი, როგორიც ადრე ვიყავი“? გაუზიარეთ ეს დროებითი, თუმცა ძალიან მძიმე და ღრმა განცდა Anacan-ის საზოგადოებაში მყოფ დედებს და მიიღეთ ნუგეში და მხარდაჭერა მათგან, ვისაც იგივე გზა გაუვლია.'),
  ('f8f300ba-8e5d-4a43-a3bc-e71f82ec47f0', 'წყლის თერაპია 🌊', 'ზოგჯერ არაფერი ჭრის და ბავშვი უბრალოდ ყველაფერზე ტირის. ჩასვით თბილი წყლით სავსე აბაზანაში და ცოტაოდენი ქაფიც დაუმატეთ. წყლის ეს მისტიკური, დაძაბულობის მომხსნელი მაგნიტური ეფექტი მყისიერად მოუტანს სიმშვიდეს მთელ ოთახსა და ბავშვის ნერვულ სისტემას.'),
  ('11b4acb5-0c50-4711-bda6-86d12a2c254b', 'მამის მასაჟის დრო 💆‍♂️', 'დღეს დიდხანს იდექით ფეხზე და ბავშვის დევნისა თუ იატაკიდან სათამაშოების აკრეფისგან წელი გტკივათ. როგორც კი ბავშვი დაიძინებს, პარტნიორს სთხოვეთ, მხრებზე 10-წუთიანი მასაჟი გაგიკეთოთ. თქვენ სახლის საყრდენი ხართ, საყრდენებს კი აუცილებლად სჭირდება დასვენება და ძალების აღდგენა.'),
  ('48e0f071-5110-45a7-a007-23be77bbd305', 'უკუღმა ჩაცმული მაისურის სიამაყე 👕', 'მაისური უკუღმა ჩაიცვა და ისე ამაყად გაჩვენებთ, თითქოს მთელი სამყარო დაიპყრო. ბავშვი, რომელიც საზოგადოებაში უკუღმა ჩაცმული ტანსაცმლით გამოდის, საკუთარ გადაწყვეტილებას იცავს. ოდნავადაც ნუ ჩაერევით — უბრალოდ, მისი თავდაჯერებულობით აღფრთოვანდით.'),
  ('b20bcc48-1ecb-4706-9d32-0f8329c7cd46', 'გამოცდები სუპერმარკეტში 🛒', 'სალაროსთან მისვლისას კალათაში 3 სხვადასხვა შოკოლადი აღმოაჩინეთ, რომლებიც თქვენ არ აგირჩევიათ. ბავშვი თქვენს საზღვრებს ამოწმებს. სწრაფად იმოქმედეთ და ეს პროდუქტები უკან დააბრუნეთ. რაიმეს დავიწყების თავიდან ასაცილებლად კი თვალი მუდმივად აპში არსებულ საყიდლების სიაზე გეჭიროთ.'),
  ('229bf8d4-9bef-44e1-90de-84a850188af4', 'ცივი ყავის რეალობა ☕', 'ყავის მომზადებიდან 3 საათის შემდეგ მისი ყინულივით ცივად დალევა დედობის დაუწერელი კანონია. თუმცა დღეს გამონაკლისი დაუშვით! ბავშვი საყვარელ მულტფილმთან მარტო დატოვეთ და ყავა ცხელ-ცხელი დალიეთ. თქვენ რობოტი არ ხართ და დასვენების უფლება გაქვთ.'),
  ('78ebbc01-68e9-48f1-b518-6ad7212482ec', 'ხმის საზომის ციფრული სიჩუმე 🤫', 'როგორც იქნა, დაიძინა! სახლში გამეფებული სიჩუმე დაუჯერებელია. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელს უყურეთ — თვალნათლივ იგრძნობთ, როგორ მშვიდდება და ნელ-ნელა აღდგება თქვენი გონება.'),
  ('83129caa-97cc-414e-93e5-8bffa69fcbb9', 'მე შენი დედა ვარ! 👩‍👧', 'როლების გაცვლის თამაში დაიწყო! ის მითითებებს გაძლევთ: მოდი აქ, დაწექი საწოლში, არ იტირო. დიდი სიამოვნებით მიეცით საშუალება, ლიდერობა მოსინჯოს, თქვენ კი უხმოდ შეასრულეთ მისი ბავშვის როლი — ეს ემპათიის განვითარებას უწყობს ხელს.'),
  ('257a6a67-1139-417f-a422-373f16be4a85', 'საიდუმლო ვიტამინების ოპერაცია 🥣', 'საკვებს, რომელიც გუშინ უყვარდა, დღეს პირსაც არ აკარებს. ნუ შეებრძოლებით მის ნებას. გამოიყენეთ ჯანსაღი წასახემსებლების რეცეპტები, რომლებშიც ცილოვანი პროდუქტები განსხვავებულ, ფერად და საინტერესო ფორმას იძენს — და გამარჯვებული თქვენ დარჩით.'),
  ('e8a36b6d-250c-4114-bd67-1068cf626c68', 'ჩემი სათამაშო ავადაა 🩺', 'ის სათამაშო სტეტოსკოპით დათუნიას სერიოზულად სინჯავს და ჭრილობაზე პლასტირს აკრავს. სიმბოლური თამაშის საშუალებით ბავშვი თანაგრძნობას სწავლობს და სამყაროს აღიქვამს. თქვენც შეუერთდით თამაშს და საავადმყოფოს პაციენტის როლი მოირგეთ.'),
  ('fc4c9174-8969-47bc-b1ba-7be545e849f3', 'ოცნებები ჭკვიან ზღაპრებთან ერთად 🪄', 'კლასიკური წიგნები უკვე ზეპირად იცით. ჩართეთ ჭკვიანი ზღაპრები, მთავარ გმირად თქვენი ბავშვი აქციეთ, დასაპყრობ ადგილად კი მისი ოთახი აირჩიეთ და შექმენით უჩვეულო აუდიოძილის სეანსი, რომელიც თქვენგან არანაირ ძალისხმევას არ მოითხოვს.'),
  ('3bc4e55a-369a-4bca-8a42-e2a95a607168', 'გულახდილი ჩანაწერები განწყობის დღიურში 📝', 'ვერავინ ამჩნევს, რამდენად იღლებით სახლში? განწყობის დღიური თქვენი ყველაზე ჩუმი მესაიდუმლეა. ჩაწერეთ იქ ყველა წვრილმანი, რომელმაც დღეს ჭკუიდან გადაგიყვანათ, შემდეგ კი ეკრანს შეხედეთ და იგრძენით, როგორ გიმსუბუქდებათ გონება და ქრება დარდი.'),
  ('7da1ffab-3792-4ba0-b3b7-ce279478fa15', 'ამინდი და მოულოდნელი ცვლილებები ⛅', 'გარეთ ცა ბოლომდე მოწმენდილი არ არის, მზე ანათებს, მაგრამ ქარიც უბერავს? ამინდისა და ჩაცმულობის ხელსაწყო მაშინვე გეტყვით ქარის სიჩქარეს, რომელიც ფანჯრიდან არ ჩანს, და სწორ სამოსსაც შეგირჩევთ — ასე კართან ყოყმანში დროს აღარ დაკარგავთ და სასეირნოდ გახვალთ.'),
  ('be5cb204-e61d-452b-9a0e-bb977bd6249c', 'უმიზეზო ცრემლები ☀️', 'ქვითინით ატირდა და თქვა, მზე თვალებში მიყურებსო? ნუ ეცდებით ამაში ლოგიკის ძებნას. მისთვის ეს მართლაც დიდი გულისტკივილია — ბრაზობს, რადგან სამყაროს მართვა არ შეუძლია. უბრალოდ აღიარეთ მისი ემოცია და უთხარით: „ფარდა ჩამოვაფარე და მზე დავმალე“.'),
  ('05028726-3b26-4576-b76c-968926aa3c37', 'მარტო დარჩენის სურვილი 🚪', 'ხმაური გონებას გიბურღავთ და გინდათ, ყველაფერს უყვიროთ. ბავშვი უსაფრთხო ადგილას დატოვეთ, სააბაზანოში შედით და კარი დახურეთ. უბრალოდ 5 წუთის განმავლობაში კედელს უყურეთ და არაფერი აკეთოთ. ეს მოკლე შესვენება დედის როლში დასაბრუნებლად მოგამზადებთ.'),
  ('3d57cc08-81bc-4a6c-804c-4488f1dababe', 'შიშველი ფეხების წესი 👣', 'მას სიამოვნებს ფეხშიშველი სიარული და ხალიჩასთან, ოთახში არსებულ ქვებთან ან ცივ ფილებთან შეხება. ტერფებში არსებული ნერვული დაბოლოებების სტიმულაცია ძალიან მნიშვნელოვანია მისი წონასწორობისა და ნევროლოგიური განვითარებისთვის. თუ არ სცივა, წინდების გარეშე სიარულში ხელს ნუ შეუშლით.'),
  ('903639ea-1976-4233-a451-64887050fd95', 'მამის უცნაური ხმები 🤡', 'როცა თქვენი ხრიკები აღარ ჭრის, მამის მიერ გამოცემული ცხოველების უცნაური ხმები და სასაცილო სახეები მდგომარეობას მაშინვე შველის. საღამოს კრიზისების დროს საქმე დაუყოვნებლივ მას გადააბარეთ, თავად კი გვერდიდან მშვიდად უყურეთ და დაისვენეთ.'),
  ('4cb1e963-5e79-4f65-b536-3c251c29e851', 'დღეს მე მოვამზადებ 🧑‍🍳', 'როცა ცომს აბრტყელებთ, აუცილებლად მოაქვს სკამი, თქვენ გვერდით დგამს და პროცესში ერევა? სინამდვილეში მას დახმარება კი არა, მოვლენების ეპიცენტრში ყოფნა სურს. მიეცით ცომის პატარა გუნდა. სამზარეულო აირევა, სამაგიეროდ მისი თავდაჯერებულობა და შემოქმედებითობა საგრძნობლად გაიზრდება.'),
  ('7f5013df-f5cb-4869-9600-c6ec01184189', 'ახალი სიტყვების აღრიცხვა 📈', 'საგნებს სრულიად თავის მოგონილ, არცერთ ენაში არსებულ სახელებს არქმევს. თან დაჟინებით მოითხოვს, რომ თქვენც იგივე სიტყვები გამოიყენოთ! გახსენით განვითარების ტრეკერი და აუცილებლად შეინახეთ მისი ეს სასაცილო სიტყვები, რათა მომავალში წაიკითხოთ და ერთად იცინოთ.'),
  ('df048442-7c05-4ccf-850d-802c3f348e55', 'სიბნელესთან დამეგობრება 🌙', 'იმისთვის, რომ ბავშვს უფრო სწრაფად ჩაეძინოს, დაძინებამდე 1 საათით ადრე ოთახში ყველა დამატებითი განათება და პლანშეტის ეკრანი გამორთეთ. მელატონინი სწრაფად მხოლოდ ბნელ და ტექნოლოგიებისგან თავისუფალ გარემოში გამომუშავდება, რაც ჩაძინებას უწყობს ხელს.'),
  ('18eabc56-86a4-4978-a5a6-151a3c410b3b', 'ჩააქრეთ შუქი და სიჩუმეს მოუსმინეთ 🤫', 'როგორც იქნა, ჩაეძინა. ახლა სახლში უმცირესი ხმაურიც კი გაწუხებთ. ჩააქრეთ ზედმეტი განათება, გამორთეთ ტელევიზორი და სიბნელეში ამ იშვიათი, ტკბილი სიჩუმით დატკბით. ასე მთელი დღის დაღლილობაც კი ქრება.'),
  ('90892878-829c-442e-a1ef-747f03a0affd', 'უმიზეზო გაბუტვა 😤', 'თქვენ უბრალოდ უთხარით: „მოდი, საჭმელი მზადაა“, მან კი ხელები გადაიჯვარედინა, კედელს მიაშტერდა და გაგებუტათ. ამ ასაკში ემოციები იმდენად არეულია, რომ ზოგჯერ ბავშვები უმიზეზოდაც კი იბუტებიან. ნურაფერს აუხსნით — 2 წუთში თვითონ გაიქცევა საჭმელად.'),
  ('e85911c9-eb5a-4470-b9d6-9a1a5872b746', 'Anacan AI: ბავშვების შიშები 🤖', 'უცებ იმ წითელი მანქანის შეეშინდა, რომლითაც ყოველთვის თამაშობდა? თუ აუხსნელი ფობიები გაწუხებთ, დახურეთ ინტერნეტში არსებული შემაშფოთებელი ფორუმები. Anacan AI-სგან მიიღეთ მეცნიერულად დასაბუთებული და დამამშვიდებელი პასუხი 3.5 წლის ბავშვის წარმოსახვის უცნაურობებზე.'),
  ('037f6c5f-0014-4a61-89cc-f6268f8f792a', 'ჩურჩულის ჰიპნოზი 🌙', 'საწოლში წევს, ფეხებს ჰაერში სწევს და დაძინება საერთოდ არ სურს. ყვირილის ნაცვლად, მოულოდნელად დაუწიეთ ხმას და მხოლოდ ჩურჩულით ესაუბრეთ. როცა ბავშვი თქვენს გასაგონად ყურადღებას მოიკრებს, მისი ტვინი ავტომატურად მოეშვება და ძილის რეჟიმზე გადაერთვება.'),
  ('b0b14a33-4ccb-42a3-a0a7-0359199a066c', 'განტვირთვა Anacan-ის საზოგადოებაში 💬', 'ძალიან დაიღალეთ და არავისთან არაფრის ახსნა არ გსურთ. შედით Anacan-ის საზოგადოებაში და უბრალოდ მკითხველად დარჩით. სხვა დედების მსგავსი დაღლილობის დანახვა გაგიჩენთ განცდას, რომ მარტო არ ხართ, და ეს საუკეთესო თერაპიად იქცევა.'),
  ('b51e5eaf-9b52-4501-9631-0ad7c9e7aebd', 'კითხვების ქარიშხალი — რატომ? 🌪️', 'თევზები რატომ არ დადიან?, მზე სად წავიდა? დილაადრიან მისი გონება საათში 100 კითხვის სიჩქარით ეძებს ფილოსოფიურ პასუხებს. დაღლილობის მიუხედავად, მოკლე პასუხები გაეცით. ის სამყაროს საიდუმლოებებს თქვენი ხმის ტონით შეიცნობს.'),
  ('56c9f928-e47b-4ebf-bb44-4ec5cb4ae53f', 'ეს ჩემია! — ყველაფრის დასაკუთრება 🧸', 'სახლში ნებისმიერ შემთხვევით ნივთს გულში იხუტებს, ყვირის: ეს ჩემია! და არავის აძლევს. ის საკუთრების საზღვრებს იკვლევს. ეგოისტობაში ნუ დაადანაშაულებთ — ყურადღება სხვა თამაშზე გადაატანინეთ და ნივთი დაიბრუნეთ.'),
  ('77d341ac-ecee-44bc-a34c-b8046e7ebe38', 'დედის საკუთარი ულუფა 🥗', 'მის დასანაყრებლად 3 განსხვავებული მენიუ მოიფიქრეთ, თავად კი ისევ მშიერი დარჩით? კვების გეგმის განყოფილებიდან შეარჩიეთ არა მხოლოდ ბავშვებისთვის, არამედ დედებისთვისაც განკუთვნილი, ენერგიის მომცემი, 10 წუთში მოსამზადებელი, რკინითა და კალციუმით მდიდარი სადილი და საკუთარ თავზე ზრუნვა არ დაივიწყოთ.'),
  ('97e76dee-bae4-4d8b-bffd-646b99d0b6bc', 'წყვილის შამპანური 🥂', 'რთული დღის შემდეგ ჭიქებში ჩვეულებრივი ცხელი ჩაი ჩამოასხით. მეუღლესთან ერთად დივანზე პირისპირ დაჯექით, თქვით: დღეს იმ ქაოსსაც გადავურჩით, და ჭიქები მიუჭახუნეთ. თქვენ ამ სახლის ერთდროულად სარდლებიც ხართ და გუნდიც.'),
  ('0dc18b7e-e572-47af-8c7b-0d7785728f82', 'თავად დასხმის ჟინი 💧', 'დიდი დოქიდან პატარა ჭიქაში წყალი აუცილებლად თავად უნდა გადაასხას. წყალი ჯერ მაგიდაზე იღვრება, იქიდან კი იატაკზე. მაგრამ შეხედეთ მის პატარა ხელებს, როგორ იღებს ტილოს და ცდილობს დასვრილი ადგილის გაწმენდას. შეცდომების დაშვებით ის პასუხისმგებლობას სწავლობს — ნუ გაბრაზდებით.'),
  ('4f75092c-a7ba-4a8b-9f64-4af1718f2cab', 'ოკეანე აბაზანაში 🌊', 'აბაზანაში ბანაობა უკვე სისუფთავის პროცედურა კი არა, ტალღების შექმნის თამაშია. მიეცით საშუალება, წყალი ირგვლივ მოაშხეფოს. წყლის ეს ჯადოსნური ეფექტი მთელი დღის განმავლობაში დაგროვილ სიჯიუტესა და უარყოფით ენერგიას ჩამორეცხავს და კანალიზაციას გაატანს.'),
  ('d4d0d422-f5f6-490e-8c72-e88ef36a1315', 'საყიდლების სია — რომ არაფერი დაგავიწყდეთ 🛒', 'მაღაზიაში წასვლისას ყველაზე მნიშვნელოვანი ნივთი აუცილებლად გავიწყდებათ? საყიდლების სია აპში გელოდებათ. ჩაწერეთ იქ ყველაფერი, რაც გჭირდებათ, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას ზუსტად ის იყიდოს, რაც საჭიროა, თქვენ კი გონება ზედმეტად არ დაიტვირთოთ.'),
  ('418c1711-4059-4957-81d3-edd1c0d2c899', 'არქიტექტურა პარკში 🏰', 'პარკის ქვიშის მოედანზე ისეთ ღრმა ორმოს თხრის, თითქოს განძს ეძებს. თავიდან ფეხებამდე ტალახშია. მაგრამ აღმოჩენით ტკბობის ამ მომენტს ნუ შეაწყვეტინებთ. ამინდის შესაბამისად წინასწარ შერჩეული ტანსაცმელი, რომლის დასვრაც არ დაგენანებათ, საშუალებას მოგცემთ, ამ სანახაობას სტრესის გარეშე უყუროთ.'),
  ('4690cd10-6ebf-45be-8b49-fc76a078e4f1', 'უცნაური მეგობრობა უსულო საგნებთან 🗣️', 'პარკში ქვას ან სახლში სკამს სრული სერიოზულობით ელაპარაკება და საყვედურობს. სიმბოლური თამაშის მეშვეობით ბავშვი სამყაროს აღიქვამს და მიღებულ შთაბეჭდილებებს ამუშავებს. განვითარების ტრეკერში აუცილებლად მონიშნეთ მისი ეს განსაკუთრებული სცენარები.'),
  ('a43560ca-6c77-420e-beaa-23a6e7c51732', 'მე ჭკვიან ზღაპარში 🪄', 'ამ საღამოს ჭკვიან ზღაპარში მთავარ გმირს პირდაპირ თქვენი ბავშვის სახელი დაარქვით. მოუყევით, რომ ზღაპრის პერსონაჟმაც დაალაგა თავისი ოთახი და შემდეგ მშვიდად დაიძინა — ასე წესებს ყვირილის ნაცვლად ირიბად შეასწავლით.'),
  ('9e327ded-a5c0-48ad-901c-52606eb80762', 'განწყობის დღიური — განტვირთვის მომენტი 📝', 'აიღეთ ტელეფონი. სოციალურ ქსელებში სხვისი ცხოვრების თვალიერების ნაცვლად, გახსენით განწყობის დღიური და მომავლისთვის ჩაინიშნეთ დღევანდელი ყველაზე სასაცილო მომენტი. ეს ციფრული თერაპია თქვენც დაგამშვიდებთ.'),
  ('a7cb2140-287a-4406-a2b5-5d7c82c31a2d', 'მამიკოს ზურგზე ცხენობანა 🐴', 'ენერგია ბოლომდე ვერ დახარჯა და დაძინებას ეწინააღმდეგება. მამიკოს მოუხმეთ დასახმარებლად. როცა ის ბავშვს ზურგზე შეისვამს და ცხენივით გააჭენებს, ოთახს სიცილი აავსებს, დაგროვილი ფიზიკური დაძაბულობა და ეს უსასრულო ენერგია კი ოფლის ღვრასთან ერთად წამებში გაქრება.'),
  ('e21478c9-e278-43bf-8cfc-ce997f28ab6d', '„შემომხედე!“ პერიოდი 👀', 'დივნიდან ხტება, ერთსა და იმავე მოძრაობას ზუსტად 50-ჯერ იმეორებს და ყოველ ჯერზე გეუბნებათ: „დედა, შემომხედე!“ თვალი ტელეფონს მოსწყვიტეთ. ის თავად მოძრაობის გამო კი არ ხტება, არამედ თქვენს თვალებში მოწონების ნაპერწკლის დასანახად. დაუთმეთ მას 5 წუთი უწყვეტი ყურადღება, რომ გული იჯეროს.'),
  ('4a32ef42-8519-4a15-ae15-b2e86c604165', '0 დეციბელი ხმის საზომზე 🤫', 'როგორც იქნა, დაიძინა! სახლში ჩამოწოლილ სიჩუმეს ვერ იჯერებთ. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელს შეხედეთ. იგრძენით, როგორ ისვენებს ნელ-ნელა თქვენი გონება და როგორ გეფერებათ ეს ხილული სიჩუმე.'),
  ('5db98ad2-4a41-4a94-8924-de68639a6a28', 'თავისუფალი ცეკვა 🎶', 'პირველივე გაგონილ რიტმზე ცეკვას იწყებს — სულ ერთია, რეკლამის ხმა იქნება თუ მანქანის სიგნალი. თქვენც მასავით მხიარულად შეხედეთ ცხოვრებას! შეუერთდით ოთახში და რამდენიმე წუთით გიჟურად იცეკვეთ — მთელი სტრესი უკვალოდ გაქრება.'),
  ('8095b6da-2b93-462b-bce2-881fa1732924', 'დამკვირვებელი — განვითარებით სიამაყე 📈', 'ის უკვე ჩვილი აღარ არის! ის სრულფასოვანი ადამიანია, რომელსაც საკუთარი გადაწყვეტილებები, უცნაური კითხვები და უზარმაზარი გული აქვს. თქვენ შესანიშნავად ართმევთ თავს!'),
  ('064149bc-eacb-463c-b371-3ee4af7db167', 'ხალიჩის სასაზღვრო ხაზები 🗺️', 'მან ახალი წესი შემოიღო: ოთახიდან სამზარეულომდე მხოლოდ ხალიჩის წითელ ხაზებზე დაბიჯებით უნდა მიხვიდეთ. მსხვილი მოტორიკა და ყურადღება ერთდროულად მუშაობს. ნუ დაარღვევთ ამ ალოგიკურ წესს — თქვენც მასთან ერთად იცეკვეთ ხაზებზე და დილის ვარჯიშიც შეასრულეთ.'),
  ('2980ee34-de75-4617-8093-160c3c2da3a0', 'თეატრი ბალიშის ქვეშ 🎪', 'საწოლში დაწვა, მაგრამ თავი ბალიშის ქვეშ შეყო და თავისთვის ლაპარაკობს. ოთახი მთლიანად ჩააბნელეთ. მიეცით საშუალება, ამ ბნელ და უსაფრთხო თავშესაფარში საკუთარი სცენარები მოიფიქროს და ნელ-ნელა გადაეშვას ძილის სამყაროში — ნუ ჩაერევით.'),
  ('af38ac43-154c-4c60-9f01-51c84d74b264', 'ჯიბეში ნაპოვნი მაკარონის გამოცდა 🍝', 'სარეცხ მანქანაში ჩასადები შარვლის ჯიბეში გამხმარი მაკარონი იპოვეთ? თქვენთვის ეს ნაგავია, მისთვის კი შეიძლება გზაში მოშივების შემთხვევისთვის გადანახული საგზალი იყოს. ნუ გაკიცხავთ — დაგეგმვის უნარის ეს პირველი ნიშნები განვითარების ტრეკერში სახალისო მოგონებად ჩაინიშნეთ.'),
  ('881d0866-6df6-4dec-801b-67b99df853c5', '„წყალი გააშრე!“ — მოთხოვნა 💧', 'ჭიქაში წყლის დალევის ნაცვლად ყვირის: „ეს ძალიან სველია, გააშრე!“ კეთილი იყოს თქვენი მობრძანება 3.5 წლის ასაკის აბსურდულ სამყაროში. ახსნის მცდელობა მხოლოდ ენერგიას დაგაკარგვინებთ. უთხარით: „კარგი, სხვა მშრალ წყალს მოგიტან“ და იგივე წყალი განსხვავებული ფერის ჭიქით მიაწოდეთ.'),
  ('d2f34bfd-32c7-43f7-89fd-d8226236a390', 'მამის საიდუმლო ქრთამი 🤫', 'კბილების გახეხვა არ უნდა. მამა ჩუმად უახლოვდება და ეუბნება: „თუ კბილებს გაიხეხავ, გაჩვენებ ჯიბეში შენახულ ჯადოსნურ ქვას“. დედობის წესები ზოგჯერ მამების ამ ეშმაკურმა, თუმცა მყისიერად ეფექტურმა უჩვეულო თამაშებმა უნდა დაარღვიოს.'),
  ('f968f309-08cf-46ae-901b-44ed8420ced0', 'საზოგადოებაზე დაკვირვება აივნიდან 👀', 'აივანზე გადის, გზაზე გამვლელ ყველას ხმამაღლა ეძახის და ხელს უქნევს, პასუხს რომ ვერ იღებს კი სწყინს. სოციალური კავშირის მოთხოვნილებამ პიკს მიაღწია. ძალით ნუ შეიყვანთ ოთახში. უთხარით: „ისინი ძალიან შორს არიან და შეიძლება ვერ გაიგონეს“ — ასე მის ემპათიასაც ფრთხილად გაუფრთხილდებით.'),
  ('01eb4758-ff80-4ee6-b2d8-884207fd7862', 'წიგნის ჩუმად კითხვის სეანსი 📖', 'ამ საღამოს არავინ საუბრობს. ჩართეთ შემეცნებითი ზღაპრები და ტექსტის ხმამაღლა წაკითხვის ნაცვლად, მოწყობილობიდან მომავალი ბუნების მშვიდი ხმების ფონზე ჩუმად დაათვალიერეთ სურათები. ვიზუალური შთაბეჭდილებები მას დაღლის და თავისთავად ჩააძინებს.'),
  ('fae36977-58eb-48b1-8551-438307ad854b', 'კვერცხი არასწორად გაჭერით 🍳', 'მოხარშული კვერცხი შუაზე გაჭერით და ამას დიდი აურზაური მოჰყვა. მე მთლიანი მინდოდა! საკვების ფორმა მათთვის განსაკუთრებით მგრძნობიარე საკითხია. გაეცანით ჯანსაღ რეცეპტებს და ისწავლეთ, როგორ მიართვათ საკვები სათანადო ფორმითა და სახალისო ნაჭრებად დაჭრილი.'),
  ('fed4ec8b-badd-4ae2-b8cd-74446e67eee7', 'ბუნების პატარა დეტექტივი 🔍', 'პარკში 20 წუთის განმავლობაში გაუნძრევლად იჯდა მხოლოდ იმისთვის, რომ ჭიანჭველების ბუდეს დაკვირვებოდა. ნუ ააჩქარებთ. თუ ამინდისა და ჩაცმულობის დამხმარის მეშვეობით წინასწარ, ამინდის შესაბამისად ჩააცვით და სქელძირიანი ფეხსაცმელიც მოარგეთ, მიეცით ამ პატარა ბიოლოგს სამყაროს აღმოჩენის საშუალება.'),
  ('0601b05e-a2e4-4730-b08b-f661e0e89b2a', 'მინი-ლაბორატორია აბაზანაში 🛀', 'წყალში სხვადასხვა ფერის საპნებს ურევს და ჯადოსნურ ნაყენს ამზადებს. დიახ, აბაზანა ისვრება. სამაგიეროდ, ბავშვი გამხსნელებსა და ნივთიერებების შერევას ეცნობა. ეს სამეცნიერო კვლევა საღამოს დაღლილობას მოუხსნის და მშვიდი ძილისთვის მოამზადებს.'),
  ('15d2ba80-4fad-4f86-8e70-6261ae666ebc', 'განმარტოება კარადაში 🚪', 'სახლის შუაგულში ხმაური უეცრად შეწყდა. ბავშვი ტანსაცმლის კარადაში, სიბნელეში მარტო თამაშისას იპოვეთ. ეს დეპრესია არ არის — მას უბრალოდ ემოციური განტვირთვა სჭირდება. კარი ფრთხილად მიხურეთ და პირადი სივრცით ტკბობის საშუალება მიეცით.'),
  ('869bedae-ce51-4c50-8799-4b322d523e09', 'შეხებით გადაღლა 🔋', 'მთელი დღე ბავშვი სხეულზე გაძვრებოდათ და თმას გქაჩავდათ, ამიტომ ფიზიკურად სრულიად გამოიფიტეთ. დაუყოვნებლივ დატოვეთ ის უსაფრთხო ადგილას და სხვა ოთახში გადით. განწყობის დღიურში ჩაწერეთ „ჩემი სხეული მე აღარ მეკუთვნის“ და ასე შეიმსუბუქეთ შეხებით გადაღლის სინდრომის ფსიქოლოგიური ტვირთი.'),
  ('18c831a2-2a8d-41b4-aec0-3fc3423e4549', 'შინაგანი სიმშვიდე ხმის საზომთან ერთად 🤫', 'როგორც იქნა, დაიძინა. ყურებში ზუზუნი კი არ წყდება. აპლიკაციაში გახსენით ხმის საზომი. ეკრანზე გამოსახულ 0 დეციბელს დააკვირდით და იგრძენით, როგორ აღწევს ოთახის სიჩუმე თქვენს გონებაში და როგორ გაჯანსაღებთ.'),
  ('64255b01-33d4-405e-b645-f0ff22d8defe', 'ტელეფონის ქურდი 📱', 'ჩაის ისხამდით, როცა შენიშნეთ, რომ თქვენი ტელეფონი გამქრალია, ის კი დივნის უკან თქვენივით ამბობს: „ალო“. ბავშვი თქვენს ციფრულ ჩვევებს იკვლევს. მოწყობილობის აღებისას თამაშით უთხარით: „როგორც ჩანს, ჩემს ტელეფონსაც სურს შენთან საუბარი“ და ასე დაიბრუნეთ.'),
  ('d0533c80-d46b-4d9f-9654-8ce50e72523b', '„შენ თვითონ ჩამაცვი!“ პოლიტიკა 👖', 'ფეხებს მაღლა სწევს და ამბობს: „მე ბავშვი ვარ, შენ ჩამაცვი“. ბავშვები დამოუკიდებლობასა და სხვაზე დამოკიდებულებას შორის მერყეობენ. ძალით ნუ ჩააცმევთ. ტანსაცმელი გვერდით დაუდეთ და ეშმაკურად უთხარით: „ეს სუპერგმირის შარვალი თავის პატრონს ელოდება“.'),
  ('5d82c548-2228-430b-916c-6c21c900e5fe', 'ჩურჩულის მისტიკური ძალა 🌙', 'საწოლიდან თავის დასაღწევად ათასგვარ მიზეზს იგონებს. ხმას ბოლომდე დაუწიეთ და მხოლოდ ჩურჩულით ისაუბრეთ. თქვენ გასაგონად ბავშვი იძულებული გახდება, მთელი ყურადღება მოიკრიბოს, ეს კონცენტრაცია კი მის გონებას დააწყნარებს და დააძინებს.'),
  ('e401c834-583c-49ec-8d04-289b6b62d99b', 'ნუგეში Anacan-ის საზოგადოებაში 💬', 'გახრჩობთ განცდა, რომ ვერასოდეს იქნებით სრულყოფილი? დაივიწყეთ Instagram-ის იდეალური დედების ილუზია. შედით Anacan-ის საზოგადოებაში, წაიკითხეთ გულწრფელი აღიარებები დედებისა, რომელთა სახლებშიც სრული ქაოსია და რომელთა შვილებიც კედლებზე ხატავენ, შემდეგ კი საკუთარ თავს უთხარით: „მე სრულიად ნორმალური ვარ“.'),
  ('fb0d15e4-b6e4-45a0-af9f-62f33e8c81a6', 'დინოზავრის ლოგიკა 🦖', 'დილით არცერთ კითხვას არ პასუხობს და მხოლოდ ღრიალებს. დღეს ის T-Rex-ია. „ნეტავ T-Rex-ები ფაფას ჭამენ?“ — მოერგეთ მის მიერ გამოგონილ პერსონაჟს და დილის რიტუალი ცრემლების გარეშე დაასრულეთ.'),
  ('5a7d778f-6e03-4003-a60c-0214c0dc5a0b', 'მამის გამოგონილი გმირები 🦸‍♂️', 'ამ საღამოს წიგნში დაწერილი ზღაპრები დაივიწყეთ. მამამ მოიგონოს ფანტასტიკური ამბავი, რომლის მთავარი გმირიც თავად ბავშვი იქნება. ისეთი წინადადებები, როგორიცაა: „და მან ხმალი იშიშვლა და... კბილები გაიხეხა!“, ბავშვს გულიანად გააცინებს და ძილისთვის მოამზადებს.'),
  ('732719f9-46cf-4097-a068-781df2eeaf00', 'საკუთარი ნახატის კრიტიკა 🖍️', 'თავის შავ ჯღაბნილს გაჩვენებთ, ამბობს: „ეს თქვენ იყავით, მაგრამ ცუდად გამომივიდა“, შემდეგ კი ხევს და აგდებს. მას საკუთარი ნამუშევრის შეფასების უნარი უვითარდება! ნუ დააკნინებთ მის გრძნობებს. ხელი შეუწყვეთ განვითარებას და უთხარით: „იქნებ შემდეგ ნახატში წითელი ფერიც მოსინჯო?“'),
  ('aa506c93-122a-43f1-8742-2605113c516c', '„ეს მე ვიპოვე“ სუპერმარკეტში 🛒', 'სალაროსთან მიახლოებისას კალათაში ორცხობილების შეკვრას აღმოაჩენთ, რომელიც თქვენ არ ჩაგიდიათ. პატარამ ჩუმად ჩაატარა თავისი „სამძებრო ოპერაცია“. გახსენით საყიდლების სია და უთხარით: „ნახე, ეს ჩვენს სიაში არ არის, შემდეგ ჯერზე ჩავწეროთ“. ასე წესის დაცვას ციფრულ ავტორიტეტს მიანდობთ.'),
  ('0b6916b1-4773-417f-aed4-71c7ff7f85e9', 'ჩაის მყუდრო საღამო ორისთვის 🥂', 'რთული დღის შემდეგ ჭიქებში ჩვეულებრივი ცხელი ჩაი ჩამოასხით. მეუღლესთან ერთად დივანზე ერთმანეთის პირისპირ დაჯექით, ჭიქები მიუჭახუნეთ და თქვით: „დღევანდელ ქაოსსაც გადავურჩით — შესანიშნავი გუნდი ვართ“. თქვენ ოჯახის ურყევი საყრდენი ხართ.'),
  ('8bce8353-bf73-417b-8a15-56b41142ba18', 'ოპერაცია „დამალული ბოსტნეული“ 🥦', 'წვნიანში ბრინჯის ერთ მარცვალს ან სტაფილოს ნაჭერს აღმოაჩენს და ამბობს: „ამას არ შევჭამ“. მიმართეთ კვების გეგმას. გაიგეთ, როგორ აქციოთ ცილოვანი პროდუქტები და ბოსტნეული ფერად კექსებად და ამ პატარა ჯიუტ მზარეულს გონება აუბნიოთ.'),
  ('ef39807d-1235-46a3-9ca8-a0f70bb2fa23', 'ავეჯზე ცოცვის ოლიმპიადა 🧗‍♂️', 'დივნის კიდეზე მიძვრება და ფანჯრისკენ მიიწევს. სახლი თქვენთვის საფრთხეებით სავსე სივრცეა, მისთვის კი — სპორტული დარბაზი. ნაცვლად იმისა, რომ სიტყვებით „ფრთხილად, ჩამოვარდები!“ პანიკა გამოიწვიოთ, უთხარით: „ხელი მანდ მოკიდე“ და მოძრაობის ეს მოთხოვნილება სწორად წარმართეთ.'),
  ('000abcf3-b4c9-4928-8d58-c7a8f138f07f', 'ხელოვნური ინტელექტი და სიმშვიდე 🤖', 'ბავშვის უეცრად დაწყებულმა ბორძიკმა ან გაბრაზების შეტევებმა ინტერნეტში მძიმე დაავადებების ძებნა დაგაწყებინათ? შეჩერდით! ჰკითხეთ Anacan AI-ს, ხომ არ არის ეს 3 წლის ასაკისთვის დამახასიათებელი განვითარების ნახტომი და მიიღეთ პედიატრების მიერ დადასტურებული, დამამშვიდებელი პასუხი.'),
  ('ac974535-4db4-4ecb-aa90-d75a7dabe40a', 'ხმოვანი ეფექტები ოთახში 🪄', 'ჩართეთ ჭკვიანი ზღაპრები. ამბის კითხვისას გამოსცით კარის ჭრიალის, ქარისა და ჩურჩულის ხმები და ოთახში ხმოვანი თეატრი მოაწყვეთ. ეს უჩვეულო ხმები მის ყურადღებას მყისიერად გადაიტანს ზღაპრის სამყაროში, იქიდან კი — ღრმა ძილში.'),
  ('e9945ad4-3802-48f8-b0bf-d94527c3999b', 'ჩრდილისგან გაქცევა 👻', 'ქუჩაში სეირნობისას ბავშვი მოულოდნელად საკუთარი ჩრდილის შეეშინდა და თქვენს უკან დაიმალა. ლოგიკას ნუ ეძებთ — 3.5 წლის ბავშვის წარმოსახვა ასე მუშაობს. უთხარით: „მოდი, ჩრდილს დავახტეთ!“ და ის, რისიც ეშინია, მყისიერად სახალისო ფიზიკურ თამაშად აქციეთ.'),
  ('06d21315-e90d-4d7c-a84d-b0f3acd86dc9', 'მამისგან მხრების მასაჟი 💆‍♂️', 'დღეს დიდხანს იდექით ფეხზე — ბავშვის დევნისა და იატაკიდან სათამაშოების აკრეფისგან წელი გტკივათ. როგორც კი ბავშვი დაიძინებს, მეუღლეს სთხოვეთ, მხრებზე 10 წუთის განმავლობაში მასაჟი გაგიკეთოთ. თქვენ სახლის ძრავა ხართ, ძრავას კი აუცილებლად სჭირდება დასვენება და ძალების აღდგენა.'),
  ('3d278e8d-5fc9-46fa-ad40-bcef90b99e90', 'გითხრათ: „შენ ცუდი დედა ხარ!“? 💔', 'ეს იმიტომ გითხრათ, რომ სასურველი მანქანა არ უყიდეთ. გული გეტკინათ. თუმცა გახსოვდეთ, რომ მას ჯერ არ შეუძლია საკუთარი ემოციების სწორად გამოხატვა — სინამდვილეში იმის თქმა სურს, რომ იმედი გაუცრუვდა. უბრალოდ ჩაეხუტეთ და მისი გრძნობა მიიღეთ.'),
  ('d54e4e25-89e6-430d-b9c4-307312ee2246', 'მოდის თავისებური აღქმა 👗', 'ზამთრის წინდებზე საზაფხულო სანდლების ჩაცმა და ასე პარკში წასვლა სურს. ჯიუტობს და არ იხდის. დაივიწყეთ საზოგადოების ნორმები. შემოქმედებითი უნარის ჩასახშობად ნუ დაუშლით — მიეცით საშუალება, ეს დღე განსხვავებული და სასაცილო იერით გაატაროს. ის თავისუფლებას სწავლობს.'),
  ('9fab66ef-18f3-4cdb-8e01-0a4f9485cffe', 'მეტოქე სარკეში 🪞', 'სარკის წინ დგას, წარბებს იკრავს და გაბრაზებულ თუ უცნაურ სახეებს იღებს. ასე ამოწმებს, როგორ აისახება ემოციები მის სახეზე. ჩუმად, გვერდიდან და სიამოვნებით უყურეთ ამ პატარა თეატრის მსახიობის რეპეტიციას.'),
  ('b8be3052-4ca5-4460-8506-d2c5926555b2', 'განმარტოების საათი დედისთვის 🚪', 'ხმაური ტვინს გიბურღავთ და გინდათ, ყველაფერზე იყვიროთ. ბავშვი უსაფრთხო ადგილას დატოვეთ, საპირფარეშოში შედით და კარი დახურეთ. გახსენით განწყობის დღიური და დაუფარავად ჩაწერეთ მთელი თქვენი გამოფიტულობა. ეს ხანმოკლე თერაპია ძალების აღდგენაში დაგეხმარებათ.'),
  ('cc703a6d-3143-4136-a5f9-9d4bb2fc1aa6', 'სიბნელესთან დამეგობრება 🐰', 'იმიზეზებს, რომ სიბნელის ეშინია, და საწოლიდან გარბის. ოთახში ყველა შუქი ჩააქრეთ, ფანარი აანთეთ და ხელებით კედელზე ჩიტისა და ძაღლის ჩრდილები გამოსახეთ. სიბნელე, რომლისაც ეშინოდა, მისთვის რამდენიმე წამში თეატრად გადაიქცევა.'),
  ('217250d8-e2a0-42ca-ac61-232ced171632', 'ამინდის დაზვერვის ტაქტიკა ⛅', 'გარეთ მზეა, თუმცა ქარიც ქრის. ფანჯრიდან დანახულმა ამინდმა შეცდომაში არ შეგიყვანოთ. ამინდისა და ტანსაცმლის ფუნქცია მყისიერად გეტყვით რეალურ ტემპერატურას და ტანსაცმლის ფენების სწორ კომბინაციას, რათა კართან ყოყმანში დრო არ დაკარგოთ და სასეირნოდ ჯანმრთელობისთვის შესაფერისად ჩაცმული გახვიდეთ.'),
  ('4a193a83-4450-45ef-8b03-b9487c79d984', 'ეს ჩემი ბრალი არ არის! 🤷‍♂️', 'წყალი განზრახ დაღვარა, მაგრამ სათამაშოს დააბრალა და თქვა, მან გადმოაგდოო. ეს ტყუილი კი არა, ბავშვის ტვინის თავდაცვის მექანიზმია. ნუ შეედავებით. უთხარით, მოდი, ამ სათამაშოსაც ვასწავლოთ, როგორ უნდა დაალაგოსო, და მისი ყურადღება ასე გადაატანინეთ.'),
  ('c170e0aa-73e3-4e36-8c66-e8887556d5ab', 'ოკეანის ქარიშხალი აბაზანაში 🌊', 'აბაზანაში ბანაობა უკვე სისუფთავისთვის კი არა, პატარა ცუნამის მოსაწყობად გამართული თამაშია. მიეცით საშუალება, წყალი აქეთ-იქით მოასხას. წყლის ის მისტიკური, ენერგიის შემწოვი მაგნიტური ეფექტი მთელი დღის განმავლობაში დაგროვილ ჯიუტ, ნეგატიურ ენერგიას ჩამორეცხავს და კანალიზაციაში გაატანს.'),
  ('28383f04-88e3-44f0-b462-99283a8b08f3', 'სხეულის განგაშის ზარი 🩸', 'უმიზეზო გაღიზიანებასა და დაღლილობას ნუ დანებდებით. გადახედეთ მენსტრუაციის ტრეკერს — თქვენი სხეული სიგნალს გაძლევთ. საკუთარი თავის დადანაშაულების ნაცვლად, დაისვენეთ და „ჯანსაღი რეცეპტებიდან“ მაგნიუმით მდიდარი წასახემსებელი მიირთვით.'),
  ('4c7f9f66-bdd5-4db6-8e78-8af325982d85', 'დილის ფილოსოფია 🤔', 'რატომ არ ცვივიან ჩიტები? ხე რატომ გამწვანდა? დილაადრიან სამეცნიერო კონფერენცია გახსნილად გამოცხადდა. თუ ზუსტი ახსნა-განმარტებების გაცემით დაიღალეთ, ჰკითხეთ: „შენი აზრით, რატომ?“ — და კითხვა უკან დაუბრუნეთ. შემდეგ კი მის ჯადოსნურ, გამოგონილ პასუხებს მოუსმინეთ.'),
  ('ab1d1514-de05-4637-8009-2407cc320f46', 'ძილის ტაიმერის შეთანხმება ⏱️', 'როგორც კი დაძინების დრო მოდის, უეცრად სწყურდება, საპირფარეშოში უნდა ან კედელს ემშვიდობება. დააყენეთ ტაიმერი. შემოიღეთ წესი: „როგორც კი ზარი დარეკავს, ყველა შუქს აქრობს“ — და მოთმინებით დააღწიეთ თავი ამ დაუსრულებელ დამშვიდობებასა და ოსტატურ მანიპულაციას.'),
  ('310065f1-7769-41dc-b05f-15aba7ca4982', 'მაღაზიაში „მინდა!“ კრიზისი 🛒', 'სალაროსთან ტკბილეულის გამო ყვირის? გარშემომყოფების განმსჯელ მზერას საერთოდ ნუ მიაქცევთ ყურადღებას. მშვიდად დაამყარეთ თვალით კონტაქტი, აუხსენით წესი და პოზიცია არ დათმოთ. თუ თქვენს სიაში არ არის, არ იყიდით.'),
  ('d64359e3-bdb5-49c3-9bc4-e2e55cdc8d1e', 'თამაში „ვინ ხარ?“ 🎭', 'ძალიან სერიოზული გამომეტყველებით გიყურებთ და გეკითხებათ: „ვინ ხარ? დედაჩემი სად არის?“ ის თქვენთან ერთად მსახიობობანას თამაშობს! უთხარით: „მე მეზობელი დეიდა ვარ, დედაშენი მალე მოვა“, შეიცვალეთ ხმის ტონი და ეს შესანიშნავი თეატრალური წარმოდგენა განაგრძეთ.'),
  ('f9b49a33-7a6d-4463-b26d-b51d28283257', 'მოულოდნელი „მიყვარხარ“ 💖', 'ოთახის შუაგულში თამაშისას უეცრად შემოგხედავთ, თქვენკენ გამოიქცევა და კისერზე მოგეხვევათ. ეს ყველა უძილო ღამედ და დაღლილობად ღირს! დატკბით ამ მომენტის ღრმა და განუმეორებელი სიმშვიდით — მთელი ქაოსი მყისიერად დაგავიწყდებათ.'),
  ('3674bd2e-5c13-4e77-8d3d-732d072d4226', 'ნაგავი კი არა, ხელოვნებაა 🎨', 'ოთახის შუაგულში ქაღალდის პატარა ნაგლეჯებისა და დაჭრილი ძაფებისგან დიდი ხელოვნების ნიმუში შექმნა და გადაგდების უფლებას არ გაძლევთ. სისუფთავისადმი აკვიატება გვერდზე გადადეთ. პატივი ეცით მის მიერ შექმნილ ქაოსს — დალაგება ხვალაც მოესწრება.'),
  ('a910e33f-005d-4ed1-a228-647503e47993', 'სიჩუმის სიმშვიდე 🤫', 'როგორც იქნა, დაიძინა! სახლში ჩამოწოლილი სიჩუმე დაუჯერებელია. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელს უყურეთ. იგრძენით, როგორ ისვენებს ნელ-ნელა თქვენი გონება და როგორ გეფერებათ ეს თვალით ხილული სიჩუმე.'),
  ('f14df610-5f47-47f4-b085-7728f03a38c4', 'დაასრულეთ დაუსრულებელი წინადადებები 🗣️', 'როცა სიტყვა ავიწყდება, ხელებით განიშნებთ, წარბებს კრავს და ელოდება, როდის გამოიცნობთ. მისი ლექსიკური მარაგი იზრდება, უბრალოდ გონება ენაზე სწრაფად მუშაობს. მოთმინებით დაასრულეთ მისი წინადადება და დააკვირდით, როგორ გამოეხატება სახეზე შვება: „ჰო, ზუსტად ამის თქმა მინდოდა!“'),
  ('489e6dea-7ed3-426f-a373-fa7b11cafdff', 'მამიკოს ზურგზე ცხენობანა 🐴', 'ენერგია ბოლომდე ვერ დახარჯა და დაძინებას ეწინააღმდეგება. მამიკოს მოუხმეთ დასახმარებლად. როცა ის ბავშვს ზურგზე შემოისვამს და ცხენივით გააჭენებს, ოთახი სიცილით ივსება, დაგროვილი ფიზიკური დაძაბულობა და ეს დაუსრულებელი ენერგია კი წამებში, ოფლის ღვრასთან ერთად, ქრება.'),
  ('654f0e0a-2920-4fe5-8cf5-be2fa96fa926', 'დედის ენერგეტიკული ბარი 🥑', 'მის გამოსაკვებად მენიუ 4 სხვადასხვა ვარიანტად შეადგინეთ, მაგრამ თავად რა მიირთვით? ჯანსაღი რეცეპტებიდან შეარჩიეთ განსაკუთრებული, კალციუმით მდიდარი წასახემსებელი, რომლის მომზადებასაც 5 წუთი სჭირდება, და თუნდაც ფეხზე დგომით მიირთვით სიამოვნებით. თქვენ ამ სახლის ძრავა ხართ და დამუხტვა გჭირდებათ.'),
  ('f72407e2-133f-448d-813f-15315e00fa30', 'კატასავით გაღვიძება 🐾', 'დღეს დილით ის ადამიანი არ არის. ოთხზე დადის, ფეხებზე გეხახუნებათ და მხოლოდ „მიაუს“ თქმით გესაუბრებათ. ეს წარმოსახვის ყველაზე საყვარელი გამოვლინებაა. წესების დაწესების ნაცვლად, თქვენც გაუწოდეთ რძით სავსე წარმოსახვითი ჯამი და დატკბით ამ თამაშით.'),
  ('784cb32f-466a-4d9b-9df3-23fb3c0de764', 'მუსიკალური ჰიპნოზი 🎶', 'საღამოობით უმიზეზო „ქარიშხლები“ და ტირილის შეტევები იწყება. გამორთეთ ტელევიზორი, ჩააქრეთ მკვეთრი განათება და ოთახში ძალიან ხმადაბლა ჩართეთ კლასიკური მუსიკა. მუსიკის ღრმა სიხშირეები გარემოს ჯადოსნურად შეცვლის და ოთახში სიმშვიდეს შემოიტანს.'),
  ('791a6f93-24a4-4445-acfb-0bee156d7b20', 'საუზმე, რომელსაც ვერ გაიყოფთ 🍳', 'თავის თეფშზე დადებულს არაფრით გიწილადებთ, მაგრამ მოვა და დაჟინებით მოინდომებს თქვენი თეფშიდან კვერცხის ჭამას. ბავშვები მშობლების არჩევანს ყოველთვის სრულად ენდობიან. ნუ შეეწინააღმდეგებით — სიყვარულით უწილადეთ თქვენი ლუკმა და გაუღიმეთ.'),
  ('840bd918-95f6-4c59-bcb3-4b0f4eaea73b', 'საუბარი უსულო საგნებთან 🗣️', 'პარკში ქვას ან სახლში სკამს სრულიად სერიოზულად ელაპარაკება და ზოგჯერ კიდეც ტუქსავს. სიმბოლური თამაშის საშუალებით ის სამყაროს იაზრებს. განვითარების მონიტორინგში აუცილებლად მონიშნეთ მისი ეს განსაკუთრებული სცენარები — ეს მაღალი შემოქმედებითი უნარის ნიშანია!'),
  ('11214951-0661-40fc-a2c7-d7aedff5cf90', 'ჩანაწერი განწყობის დღიურში 📝', 'აიღეთ ტელეფონი. სოციალურ ქსელში სხვების იდეალური ცხოვრების თვალიერების ნაცვლად, გახსენით განწყობის დღიური და მომავლისთვის ჩაინიშნეთ დღევანდელი ყველაზე სასაცილო მომენტი, რომელმაც ყველაზე მეტად გაგაცინათ. იქ წერა ყველაზე სუფთა თერაპიაა.'),
  ('1219c5e2-02af-4f74-a734-ea08c3018209', '„შენ ნუ მღერი!“ — აკრძალვა 🛑', 'ფონად ჩართულ საბავშვო სიმღერას ღიღინით აჰყევით და მან მაშინვე დაიყვირა: „შენ ნუ მღერი!“ ოთახში ერთადერთი სოლისტი თვითონაა, თქვენი ვოკალური მცდელობები კი მის სცენას ავიწროებს. ნუ გეწყინებათ — სცენა ამ პატარა ეგოისტს დაუთმეთ.'),
  ('9dfdb936-66eb-43a1-b7d1-6fccd5198f88', '„მე“ ჭკვიან ზღაპარში 🪄', 'დღეს საღამოს ჭკვიან ზღაპარში მთავარ გმირს პირდაპირ თქვენი ბავშვის სახელი დაარქვით. მოუყევით, რომ ზღაპრის პერსონაჟმაც დაალაგა თავისი ოთახი და შემდეგ მშვიდად დაიძინა — ასე წესებს ყვირილის ნაცვლად არაპირდაპირ გააცნობთ.'),
  ('28d0f55b-6b15-4788-8b02-4740d679f342', 'რეჟიმი აირია? ⏱️', 'საღამოს დაძინება ძალიან ჭიანურდება? გადახედეთ ძილის ტაიმერის გრაფიკს. შესაძლოა, უკვე დროა, დღის ძილი სრულად გააუქმოთ და საღამოს დაძინების დრო გადმოწიოთ.'),
  ('2c32efa0-ce45-4ee9-9fb5-78b505fc81dc', 'მულტფილმების კრიტიკოსი 📺', 'ნანახ მულტფილმს თავისი გრამატიკით გიყვებათ და სერიოზულად გიხსნით, ვინ სად წავიდა. ყურადღებით და გაოცებული სახით მოუსმინეთ. მიეცით მის ფანტაზიას გაშლის საშუალება და აგრძნობინეთ, რომ მსოფლიოში ყველაზე ჭკვიანია.'),
  ('bc152191-c6d9-4a5e-b03a-d59aaa89994d', 'საზოგადოების ჩუმი მხარდაჭერა 💬', 'ძალიან დაიღალეთ და არ გსურთ, ვინმეს რამე აუხსნათ ან თქვენი დარდი გაუზიაროთ. შედით Anacan-ის საზოგადოებაში და უბრალოდ მკითხველად დარჩით. იმის ნახვა, თუ როგორ უმკლავდებიან სხვა დედები ასეთივე აბსურდულ კრიზისებს, ყველაზე ძლიერი უხმო ნუგეშია.'),
  ('487012f7-5a3f-49e2-9f9d-2533c14f18c9', 'საწოლიდან გაქცევა 🏃‍♂️', '„წყალი მომეცი“, „ჩემი სათამაშო იპოვე“... 3 წლის ბავშვის მიზეზები, რომ არ დაიძინოს, არ ილევა. ჩართეთ ძილის ტაიმერი, მტკიცედ დაიცავით საზღვრები და თეთრი ხმებით ოთახში მშვიდი გარემო შექმენით.'),
  ('543ac832-5997-4074-94fa-e27c0915dc20', 'პატარა მეზღაპრე 🗣️', 'უკვე აერთიანებს სიტყვებს და წარმოსახვით ამბებსა თუ ფანტასტიკურ სცენარებს იგონებს? არ გამოტოვოთ ენის განვითარების ეს საოცარი ნახტომი — მაშინვე გააკეთეთ ხმოვანი ჩანაწერი და ბავშვის ალბომში სამუდამოდ შეინახეთ.'),
  ('75d14b5e-1909-445c-9146-d6cc02f1b594', 'კალციუმის ფარი 🦴', 'სწრაფად მზარდი ძვლებისთვის კალციუმი აუცილებელია. რძეს არ სვამს? კვების კონტროლის ხელსაწყოთი აუცილებლად გამოთვალეთ, რამდენი ყველი, იოგურტი ან ბროკოლი მიიღო დღეს.'),
  ('5be6af82-89c1-4468-a900-9f899a3717f7', 'ჩემია! პერიოდი 🧸', 'სათამაშოს არავის აძლევს? ეს ეგოიზმი კი არა, განვითარების ბუნებრივი ეტაპია. ბლოგებში წაიკითხეთ, როგორ ასწავლოთ არა გაზიარება, არამედ რიგრიგობით თამაში, და მიღებული რჩევები პრაქტიკაში გამოიყენეთ.'),
  ('6c5b3273-7cbb-4026-9d69-cd0596d59019', 'დილის რევოლუცია 🛑', 'საჭმელს, რომელიც გუშინ ძალიან უყვარდა, დღეს ზიზღით უარყოფს? ეს უმადობა კი არა, უბრალოდ კონტროლის მოპოვების მცდელობაა. Anacan AI-ს გაუზიარეთ თქვენი დარდი და გაიგეთ, როგორ შეინარჩუნოთ სიმშვიდე კრიზისულ მომენტებში. ღრმად ჩაისუნთქეთ და სუფრასთან არასოდეს იომოთ.'),
  ('e85b3357-f072-4120-8d16-ffdc101f5e86', 'მამის მოედანი 👨‍👧', 'დედობა 24/7-საათიანი მორიგეობა არ არის. ჩართეთ პარტნიორი! დაე, დღეს მამამ ბავშვს პარკში დაახარჯვინოს თავისი უსასრულო ენერგია, თქვენ კი სახლში სრული სიჩუმით დატკბით.'),
  ('4b47f634-fca5-4f0e-a391-d61c2ad9b71e', 'დედის შესვენება ☕', 'ბავშვთან გაუჩერებლად საუბარი და კითხვებზე პასუხის გაცემა დამღლელია. დედებისთვის მეგობრულ ადგილებში იპოვეთ კაფე საბავშვო კუთხით, დალიეთ ცხელი ყავა, სხვა დედებს გაუზიარეთ თქვენი დარდი და ცოტა ამოისუნთქეთ.'),
  ('4e86cfa1-9302-4174-a4b5-457a860c75dd', 'მამის ზღაპრის ჯერი 📚', 'ამ საღამოს დაძინების რიტუალი მთლიანად მამას ევალება. მან წაიკითხოს ზღაპარი, თქვენ კი კარს მიღმა სრული სიჩუმით დატკბით.'),
  ('ffd19c6f-d0e4-4ed0-b594-f10907dbe2d7', 'მე თვითონ გავაკეთებ! 🛑', 'ყველაფერში ერევა და ჩაცმის პროცესს 3-ჯერ ახანგრძლივებს? არეულობას კი არა, მის მზარდ თავდაჯერებას შეხედეთ. როცა მოთმინება გეწურებათ, ბლოგებში წაიკითხეთ, როგორ გაუმკლავდეთ კრიზისებს თამაშით, და ღრმად ჩაისუნთქეთ.'),
  ('086dfc4e-9fb2-412e-ade9-cb121424e290', 'ცხელი ჩაი და სიმშვიდე 🍵', 'ტაიმერი გაჩერდა, ბავშვს ჩაეძინა. დაივიწყეთ საოჯახო საქმეები — ყველაფერს შეუძლია მოიცადოს. ჯანსაღი რეცეპტებიდან საინტერესო სასმელი მოამზადეთ და საკუთარ თავთან განმარტოებით დატკბით.'),
  ('577db9f8-8f80-4ad0-9e5c-4fd106adca75', 'დილიდანვე დამალობანა 🙈', 'სამსახურში ან საბავშვო ბაღში გაგვიანდებათ, ის კი ფარდის უკან იმალება და გეუბნებათ: „მიპოვე!“ მართალია, მოთმინებას კარგავთ, მაგრამ ყვირილი პროცესს კიდევ უფრო გააჭიანურებს. 2 წუთით აჰყევით თამაშში და თქვით: „ნეტავ, სად არის ჩემი საყვარელი ბავშვი?“ — შემდეგ კი იპოვეთ და სამალავიდან გამოიყვანეთ.'),
  ('61996b98-7da4-41e9-be9f-afe630090cfe', 'საჭმლის ფერების მიხედვით დახარისხება 🍅', 'თეფშზე მოთავსებულ საკვებს ფერისა და ფორმის მიხედვით ახარისხებს, მწვანე ნაჭრებს კი გვერდზე სწევს. შედით კვების გეგმაში. აღმოაჩინეთ, როგორ აქციოთ ბოსტნეული შეუმჩნეველ პიურედ და დამალოთ გემრიელ სოუსებში — ასე ამ თამაშში ფარულად გაიმარჯვებთ.'),
  ('01916001-64ad-41ab-8fea-1c1101a3ae1c', 'სიმშვიდის საჭიროება 🤫', 'მას როგორც იქნა ჩაეძინა! სახლში გამეფებული სიჩუმე დაუჯერებლად გეჩვენებათ. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელს უყურეთ. იგრძენით, როგორ ისვენებს ნელ-ნელა თქვენი გონება და როგორ გეფერებათ ეს ხილული სიჩუმე.'),
  ('95ce868b-b982-4c4e-baa7-7ca7cd3520b4', 'ჯიბეში აღმოჩენილი საგანძური 🪨', 'შარვლის გარეცხვისას ჯიბიდან 2 ქვა, ერთი გამხმარი ფოთოლი და მოტეხილი ტოტი ამოიღეთ? ის, რაც თქვენთვის ნაგავია, მისთვის სამყაროს აღმოჩენისას შეგროვებული ძვირფასი კოლექციაა. გადაყრის ნაცვლად, პატარა საგანძურის ყუთში მოუყარეთ თავი.'),
  ('97aa3207-a7a2-42a1-9e74-01d2388db3b1', 'კარის ჩაკეტვის მისია 🚪', 'განსაკუთრებით სიამოვნებს სახლში ყველა ოთახის კარის შიგნიდან ჩაკეტვა და თქვენი გარეთ დატოვება. პირადი სივრცის მისეული გაგება ნამდვილ რევოლუციას ახდენს. მიიღეთ ზომები, რომ თითები კარში არ მოჰყვეს, თუმცა ძალიან ნუ შეუშლით ხელს საკუთარ ტერიტორიად გამოცხადების ამ თამაშში.'),
  ('2f583ff5-e2c4-4fbb-acdc-470ccf241970', 'ტუალეტის ქაღალდის ხელოვნება 🧻', 'რამდენიმე წუთის სიჩუმე... ოთახში შესვლისას კი ხედავთ, რომ ტუალეტის ქაღალდი მთლიანად გაუშლიათ და მთელ სახლში მოუფენიათ! გაბრაზების ნაცვლად, შეაგროვეთ ქაღალდები და ერთად გააკეთეთ თოვლის კაცი ან ბურთი. ქაოსი ყვირილით კი არა, შემოქმედებითობით დაამარცხეთ.'),
  ('6ae9e7b9-b61e-4945-82bd-3ceb19652949', 'სარეცხი მანქანის აღმოჩენა 🧺', 'სარეცხი მანქანის წინ ზის და მბრუნავ ტანსაცმელს ისე ჩაჰყურებს, თითქოს მულტფილმს უყურებდეს. ეს სრულიად უფასო და გონების დამამშვიდებელი გასართობია. ხელს ნუ შეუშლით — თქვენც ისარგებლეთ შემთხვევით და დაისვენეთ, სანამ ქაოსმა მცირე შესვენება აიღო.'),
  ('c8193b18-f83a-473a-bda3-5d573d734271', 'ყურში ჩაჩურჩულებული სიყვარულის სიტყვები 💖', 'მთელი დღე ჭკუიდან გადაგიყვანათ და ყველაფერზე ჯიუტობდა. ახლა კი საწოლში ისეთი უმანკო სახით სძინავს... გვერდით მიუწექით და ყურში ჩასჩურჩულეთ, როგორ გიყვართ და რა კარგი რამ გააკეთა დღეს. ბავშვები ძილშიც კი გრძნობენ დედის სიყვარულით სავსე ხმას.'),
  ('8f4abc30-5451-459c-a1af-55ec249af8b0', '„შენ მე არ მისმენ!“ — მოულოდნელი დარტყმა 😠', 'როცა ტელეფონს უყურებთ ან საჭმელს ურევთ, მოდის, სახეს თავისკენ გაბრუნებინებთ და გეუბნებათ: „მე შემომხედე!“ ის მართალია. მას მხოლოდ თქვენი ფიზიკური ყოფნა კი არა, სრული და განუყოფელი ყურადღება სჭირდება. შეწყვიტეთ საქმე და მხოლოდ 3 წუთის განმავლობაში, თვალებში ჩახედვით, მთელი ყურადღებით მოუსმინეთ.'),
  ('9069176c-b719-421b-bb4f-85cd101945a6', 'ზღაპრისგან გაქცევის მცდელობები 🏃‍♂️', 'ზღაპრის კითხვისას ყოველ შესაძლებლობაზე საწოლიდან ხტება და გარბის, რომ სათამაშო მოიტანოს. ძილს არ ნებდება. უეცრად ძალიან დაუწიეთ ხმას და ჩურჩულით განაგრძეთ კითხვა. თქვენ გასაგონად იძულებული გახდება, საწოლში დაბრუნდეს და ყურადღებით მოგისმინოთ.'),
  ('e4d134d2-7f4f-4894-b6f3-6051d4c2f528', 'ამინდი და ფენებად ჩაცმის ტაქტიკა ⛅', 'გაზაფხულის მოახლოებასთან ერთად ამინდი ცვალებადია: დილით ცივა, შუადღით კი თბილა. ამინდისა და ჩაცმულობის ხელსაწყო შეგახსენებთ, რომ ბავშვი „ხახვის პრინციპით“, ფენებად ჩააცვათ. პარკში, როგორც კი დასცხება, თითო ფენა გახადეთ — ასე თავიდან აიცილებთ როგორც მის ოფლიანობას, ისე საკუთარ სტრესს.'),
  ('918e0a4a-7932-41e0-b1cb-29b726120c0e', 'ხელოვნური ინტელექტი და უეცარი სიჯიუტე 🤖', 'ბავშვი, რომელიც გუშინდლამდე მშვიდი იყო, დღეს ყველაფერზე აგრესიულად რეაგირებს? ინტერნეტში შემაშინებელ მიზეზებს ნუ მოძებნით. ჰკითხეთ Anacan AI-ს განვითარების ამ ნახტომის (mental leap) ფსიქოლოგიური მიზეზების შესახებ და პედიატრის მიერ დადასტურებული პასუხით სრულად დაიმშვიდეთ თავი.'),
  ('b03065aa-7764-4054-8d16-b42a880815cc', 'მოპარული ცხვირის თამაში 👃', 'ეუბნებით: ცხვირი მოგპარე! — და ცერა თითს აჩვენებთ, მას კი ეს მართლა სჯერა და ტირილს იწყებს! 3.5 წლის ბავშვის წარმოსახვა ზოგჯერ რეალობასა და ილუზიას ერთმანეთისგან ვერ არჩევს. მაშინვე უთხარით: აჰა, უკან დაგიბრუნე — აკოცეთ ცხვირზე და ეს პატარა ტრავმა ღიმილად აქციეთ.'),
  ('f9660fac-3163-450f-a18c-f1ac86faf296', 'მეუღლესთან უსიტყვო მზერით საუბარი 🥂', 'ბავშვმა ბოლოს და ბოლოს დაიძინა. თქვენ და თქვენი მეუღლე დივანზე გვერდიგვერდ სხედხართ და საუბრის თავიც კი აღარ გაქვთ. უბრალოდ ჩუმად უყურებთ ერთმანეთს და იღიმით. ეს უსიტყვო მზერა ყველაზე ლამაზი გზაა იმის სათქმელად, რომ ამ ქაოსს შესანიშნავად უმკლავდებით.'),
  ('48be6a74-039a-47b4-b2e6-38a02b369aa1', 'ეს მე ვიპოვე — მესაკუთრე პატარა 🔑', 'იატაკიდან ტელევიზორის პულტს ან მამის გასაღებს იღებს და ამტკიცებს: ეს მე ვიპოვე, ჩემია! მისთვის პოვნა დაუფლებას ნიშნავს. ძალით ნუ წაართმევთ. უთხარით: გმადლობ, რომ ჩემთვის იპოვე — შემდეგ მისი ყურადღება სხვა სათამაშოზე გადაიტანეთ და ნივთი მშვიდად დაიბრუნეთ.'),
  ('53233246-1c9c-44d8-aa89-08a12ab1932c', 'კონცერტი სამზარეულოში 🥄', 'ქვაბებსა და ხის კოვზებს იღებს და სამზარეულოს შუაგულში კონცერტს მართავს. შესაძლოა თავი აგტკივდეთ, მაგრამ ასე მისი რიტმის შეგრძნება და შემოქმედებითობა ვითარდება. მაშინვე ნუ ჩაერევით — რამდენიმე წუთით მიეცით საშუალება, ეს გიჟური ენერგია ხმის ტალღებად მთელ ოთახში გაავრცელოს.'),
  ('54609407-cfb4-47a1-8f37-28a152cd5950', 'მინი-სპა სააბაზანოში 🛀', 'ამ საღამოს აბაზანა მხოლოდ ბავშვისთვის კი არა, საკუთარი თავისთვისაც მოამზადეთ. ბავშვის დაძინების შემდეგ — თბილი წყალი, ცოტა ქაფი და სააბაზანოში ანთებული ერთადერთი სანთელი. კარი ჩაკეტეთ და სულ რაღაც 15 წუთით დედის როლიდან გამოდით, კვლავ საკუთარ თავს დაუბრუნდით — თქვენ ამას იმსახურებთ.'),
  ('370a629d-a585-41ae-ad7c-85bbfe349f3d', 'გულახდილი ჩანაწერი განწყობის დღიურში', 'აიღეთ ტელეფონი. სოციალურ ქსელში სხვების ცხოვრების თვალიერების ნაცვლად, გახსენით განწყობის დღიური და მომავლისთვის ჩაინიშნეთ ყველაზე სასაცილო რამ, რაც ბავშვმა დღეს გააკეთა. ეს ციფრული თერაპია თქვენც დაგამშვიდებთ — ეკრანს შეხედეთ და დაინახეთ, როგორ ქრება დარდები.'),
  ('8353b398-30f5-4594-98bd-74c894cfb243', 'სიმღერა უკან დააბრუნე! 🎶', 'რადიოში გაჟღერებული და უკვე დასრულებული სიმღერის თავიდან მოსმენა სურს. უხსნით, რომ ეს პირდაპირი ეთერი იყო და სიმღერა დასრულდა. მაგრამ ბავშვი ტირის და გაჰყვირის: უკან დააბრუნე! ბავშვის ტვინს პირდაპირი ეთერის ლოგიკა ჯერ არ ესმის. ყურადღების გადასატანად თავად დაიწყეთ ამ სიმღერის განსხვავებული, სასაცილო ხმით შესრულება.'),
  ('f3893094-7182-4330-982a-7ccd3eced333', 'ჩაი სიჩუმეში ☕', 'ბავშვი ოთახის შუაგულში სათამაშოებს მწკრივად აწყობს და დამოუკიდებლად თამაშობს. გთხოვთ, ამ ძვირფას წუთებს სახლის დალაგებაში ნუ დახარჯავთ! მოკალათდით დივანზე, ყავა ან ჩაი ჯერ კიდევ ცხელი დალიეთ და 10 წუთის განმავლობაში არაფერზე იფიქროთ — უბრალოდ დატკბით ამ სიჩუმით.'),
  ('52d5f808-8d3e-4769-9814-0abc72834d43', 'ძილის ტაიმერის ხრიკი ⏱️', 'როგორც კი დაძინების დრო დგება, ბავშვს უეცრად სწყურდება, ტუალეტში წასვლა უნდა ან კედელთან გამომშვიდობებას იწყებს? დააყენეთ ტაიმერი. შემოიღეთ წესი: როცა ტაიმერი დარეკავს, ყველანი ვიძინებთ. ასე ამ უსასრულო დამშვიდობებასა და ოსტატურ მანიპულაციას კამათის გარეშე დაასრულებთ.'),
  ('7cbac7ca-9f74-4319-bb84-ce56d77a4832', 'Anacan-ის საზოგადოების ძალა 💬', 'ფიქრი — რატომ არის ჩემი ბავშვი ასეთი ჯიუტი? — მოსვენებას არ გაძლევთ. შეუერთდით Anacan-ის საზოგადოებას. როდესაც სხვა დედების ოჯახებში მომხდარ მსგავს აბსურდულ კრიზისებზე წაიკითხავთ, მიხვდებით, რომ მარტო არ ხართ და სრულიად ნორმალურ გზას ადგახართ.'),
  ('c2a3c84a-3b57-4bf9-bcc3-b6512c66a43b', 'ნამდვილი მხატვარი კედელს ირჩევს 🖍️', 'რამდენიმეწამიანი სიჩუმე სახიფათო შედეგით დასრულდა. ოთახში შესულმა დაინახეთ, რომ ბავშვმა კედელზე ფლომასტერით ხელოვნების ნიმუში შექმნა. ღრმად ჩაისუნთქეთ. მისი ნატიფი მოტორიკა ვითარდება, კედელი კი მაინც გაიწმინდება. აუცილებლად გადაუღეთ ამ შედევრს ფოტო, რათა მომავალში ერთად იცინოთ.'),
  ('017dd4ef-6a6d-470c-a536-c9d8157780f2', 'მოწვევა სიბნელეში 🌙', 'საძინებელში შუქის ჩაქრობისას შფოთავს? ოთახის ერთ კუთხეში პატარა, თბილი ფერის (ნარინჯისფერი ან წითელი) ღამის სანათი დადგით. ოთახის დანარჩენი ნაწილი კი მელატონინის გამომუშავებისა და ღრმა ძილისთვის სრულ სიბნელეში უნდა დარჩეს.'),
  ('0cf9c44c-98af-4034-b557-39b1dbb9f133', 'პატარა დალაქის მცდელობა ✂️', 'ოთახში შესვლისას ხედავთ, რომ ბავშვს მაკრატელი უჭირავს და თოჯინასთვის თმის შეჭრას ცდილობს. ასეთი სცენა ყველა დედის კოშმარია. გაბრაზების გარეშე გამოართვით მაკრატელი და პატარა დალაქის ეს მცდელობა ბავშვის ფოტოსესიაში სასაცილო მოგონებად შეინახეთ.'),
  ('86c98bc5-4f00-463f-9722-124e19e389a1', 'ბუნებაში გასვლა აუცილებელია ⛅', 'ოთხ კედელს შორის მისი ენერგია აგრესიად გარდაიქმნება და ყოველ წინადადებას „არა“-თი იწყებს. ამინდისა და ჩაცმულობის მიუხედავად, სათანადოდ მოემზადეთ და აუცილებლად გაიყვანეთ გარეთ. მიწასთან შეხება მის ნერვულ სისტემას მყისიერად განტვირთავს.'),
  ('04ffb755-8100-4999-9284-739b81b180be', 'ეს ჩემია! — ყველაფრის დასაკუთრება 🧸', 'სახლში შემთხვევით შერჩეულ ნებისმიერ ნივთს გულში იხუტებს, ყვირის: „ეს ჩემია!“ და არავის აძლევს. ის საკუთრების საზღვრებს იკვლევს. ნუ დაადანაშაულებთ ეგოიზმში — ყურადღება სხვა თამაშზე გადაატანინეთ და ნივთი ისე დაიბრუნეთ.'),
  ('1f9e9c23-d051-49a3-8538-a3275546e6a3', 'ნაგავი კი არა, ხელოვნებაა 🎨', 'ოთახის შუაგულში ქაღალდის პატარა ნაგლეჯებისა და დაჭრილი ძაფებისგან დიდი ხელოვნების ნიმუში შექმნა და მისი გადაყრის უფლებას არ გაძლევთ. დროებით გვერდზე გადადეთ სისუფთავისადმი ზედმეტი მოთხოვნილება. პატივი ეცით მის მიერ შექმნილ ქაოსს — დალაგება ხვალაც მოესწრება.'),
  ('55f7cd1c-adbb-4e6a-bcc0-5847c157d42a', 'ცხენობანა მამის ზურგზე 🐴', 'ენერგია ბოლომდე ვერ დახარჯა და დაძინებას ეწინააღმდეგება. მამას დახმარება სთხოვეთ. როცა მამა ბავშვს ზურგზე შემოისვამს და ცხენობანას ეთამაშება, ოთახს ხარხარი ავსებს, დაგროვილი ფიზიკური დაძაბულობა და ეს უსასრულო ენერგია კი ოფლის ღვრასთან ერთად წამებში ქრება.'),
  ('11adcff5-957f-4e30-8ecc-96f09d1482fe', 'ზღაპრების სამყარო 🪄', 'კლასიკური ზღაპრები გვერდზე გადადეთ. გახსენით ჭკვიანი ზღაპრები. შექმენით განსაკუთრებული ზღაპარი.'),
  ('4418649d-d556-4a03-af91-b1d0242b6324', 'საზოგადოების მხარდაჭერა 💬', 'ძალიან დაიღალეთ და არც ვინმესთვის რაიმეს ახსნა გსურთ, არც გულის გადაშლა. შეგიძლიათ Anacan-ის საზოგადოებაში შეხვიდეთ და მხოლოდ მკითხველად დარჩეთ. იმის ნახვა, თუ როგორ უმკლავდებიან სხვა დედები იმავე აბსურდულ კრიზისებს, ყველაზე ძლიერი უხმო ნუგეშია.'),
  ('6e6ecb59-b07b-44ae-b10f-31d088fcccf0', 'დილის დიქტატორი საქმეს შეუდგა 👑', 'მანდ შენ არ დაჯდე, დათუნია დაჯდება! საუზმის დროს მთელ სუფრას ის მართავს. მისი ნების მკვეთრად ჩახშობის ნაცვლად უთხარით: კარგი, დათუნია მანდ დაჯდეს, მე კი აქ დავჯდები — ასე შეინარჩუნებთ წონასწორობასა და ოთახში მშვიდობას.'),
  ('1b1ca975-b7c1-4e57-9e31-3f5e83031e0f', 'დღის ძილის ამბოხი 🥱', 'დაწოლა არ სურს და ტირის? ნუ დააძალებთ. ოთახში განათება შეამცირეთ, გამოაცხადეთ წიგნის ჩუმად ფურცვლის საათი და შექმენით ახალი რუტინა, რომელიც ორივეს დაგასვენებთ — ასე თქვენც და ბავშვიც განსხვავებული გზით დაისვენებთ.'),
  ('8ca291c9-dcd2-4396-9580-b58e8c48c73a', 'სცენარი მან დაწეროს 🪄', 'კლასიკური წიგნები ორივეს მოგბეზრდათ და ოთახშიც მოსაწყენი განწყობაა. გახსენით ჭკვიანი ზღაპრები და ამ საღამოს სიუჟეტის მართვა მას მიანდეთ. ჰკითხეთ: ახლა სად წავიდეს მფრინავი მანქანა? — და მიეცით საშუალება, წარმოსახვაში ახალი სამყაროების დაპყრობით ჩაეძინოს.'),
  ('bd553ea9-8ebf-4e59-8a1a-239cd4d4cf83', 'მეტოქე სარკეში 🪞', 'სარკის წინ დგას, თავისთვის წარბებს კრავს და გაბრაზებულ, უცნაურ მიმიკებს აკეთებს. ის ამოწმებს, როგორ აისახება ემოციები მის სახეზე. უხმოდ ადევნეთ თვალი ამ მინიატიურული თეატრის მსახიობის რეპეტიციას და დატკბით სანახაობით.'),
  ('c78f6742-28ba-40d4-8884-94cee25316f0', 'კედელთან ჩურჩულით საუბარი 🤫', 'საწოლში წვება, კედლისკენ ბრუნდება და ვიღაცას ჩურჩულით თავის დარდს უზიარებს? რა საყვარელია! ჩააქრეთ შუქი, მოუსმინეთ, როგორ ერწყმის ეს ჩურჩული ძილს, და დაისვენეთ.'),
  ('ca5cea03-5260-4977-bf88-cfe3ed937e38', 'ჩხუბი არასწორი ჭიქის გამო? 🥤', 'იმის გამო, რომ წყალი ყვითელ ჭიქაში მიეცით, ოთახში ერთი ამბავი ატყდა? გულთან ახლოს ნუ მიიტანთ — ის უბრალოდ ამ დილით თქვენს საზღვრებს ამოწმებს. წყალი მაშინვე ლურჯ ჭიქაში გადაასხით, ოთახში მშვიდობა აღადგინეთ და ენერგია დღის დარჩენილი ნაწილისთვის შემოინახეთ.'),
  ('f8e8bb79-94ba-4264-b58d-e4f81f8007f5', 'მტვერსასრუტთან მტრობა 🌪️', 'სახლის დალაგებისას ტირის, ჩემს მტვერს ნუ მტვერსასრუტებო, და გზას გიღობავთ? მესაკუთრეობის გრძნობამ უკვე აბსურდულ დონეს მიაღწია. გამორთეთ მტვერსასრუტი და მტვერთან გამოსამშვიდობებელი 5-წუთიანი ცერემონია მოაწყვეთ. დაგვიჯერეთ, ასე ეს ქაოსი უფრო სწრაფად დასრულდება.'),
  ('0d30a53e-aee6-4a89-9af7-e9e0ea21f7c9', 'ტანსაცმელი ისევ აერია 🧥', 'გარეთ გადიხართ, მას კი რეზინის ჩექმებისა და მოკლემკლავიანი მაისურის ჩაცმა სურს? ნუ შეეკამათებით. გახსენით ამინდისა და ჩაცმულობის აპი და აჩვენეთ, რომ ტელეფონი ამის უფლებას არ აძლევს. წესის დაცვა ციფრულ ეკრანს გადააბარეთ, თავად კი განზე გადექით — მაისურს მშვიდად ჩაიცვამს.'),
  ('310c5e1a-58e7-49ee-a785-62a8445bbaba', 'ერთ ჭიქა ჩაიზე ოცნება ☕', 'ისე დაიღალეთ, რომ სანამ ის თამაშობდა, მალულად გაიქეცით სამზარეულოში და კარი მიხურეთ? მართალი ხართ. გახსენით განწყობის დღიური და მხოლოდ რამდენიმე სიტყვა დაწერეთ: დღეს გადავრჩი. ზოგჯერ დედას სწორედ ის 5-წუთიანი გაქცევა სჭირდება.'),
  ('a80cc41d-cd81-475f-9ddf-075470e2ad74', 'დაიჭირე ღრუბელი, ნუ გაუშვებ! ☁️', 'ფანჯრიდან იყურება და ტირის, რადგან ღრუბელი მიდის? ქარის მეცნიერულად ახსნაზე დროს ნუ დაკარგავთ. უთხარით, რომ ის სხვა ბავშვებთან მისასალმებლად წავიდა. მისი ეს უცნაური ფილოსოფია იუმორითა და პატარა გამონაგონებით ჩაანაცვლეთ და დღეც გადაარჩინეთ.'),
  ('154abe48-3205-47d2-a68c-a06bfd4856c5', 'დივანზე ჭიდაობა მამასთან 🤼‍♂️', 'დასაძინებლად რომ არ წასულიყო, გაიქცა და დაიმალა? ახლა ჯერი მამაზეა. მიეცით საშუალება, დივანზე ხუმრობით იჭიდაონ. ეს ხმაურიანი, ოფლის მომგვრელი თამაში მამასთან ერთად ბავშვის უკანასკნელ ჯიუტ ენერგიასაც შეიწოვს და ძილს ჩააბარებს.'),
  ('1d80be38-a3ec-4e4f-a266-479942a81b0f', 'ინტერნეტში იდეალური დედებით დაიღალეთ? 📵', 'როგორც კი Instagram-ს გახსნით და ყველას იდეალურ ბავშვს დაინახავთ, გულს ნუ გაიტეხთ! დახურეთ ის აპლიკაცია და Anacan-ის საზოგადოებაში შემოდით. როცა ნახავთ, რომ სხვების სახლებიც თქვენსავით თავდაყირაა, ბავშვები კი ხმაურობენ, ღრმად ჩაისუნთქეთ — მარტო არ ხართ!'),
  ('f6d7cbf6-3d15-4e2d-b2fb-3b33515a0a37', 'ამას მე მოვამზადებ! 🍳', 'კვერცხის ათქვეფა აუცილებლად თვითონ მოინდომა და ჯამის ნახევარი მაგიდაზე დაიღვარა? მიეცით საშუალება, ამაყი მზარეულის გამომეტყველებით დატკბეს. სამზარეულო მაინც გასარეცხია, მის მზარდ თავდაჯერებასა და დამოუკიდებლობას კი ნუ შეზღუდავთ.'),
  ('66d60d54-4a5d-4de0-a372-047beaa63d3c', 'მაკარონის საიდუმლო მარაგი 🍝', 'შარვლის რეცხვისას ჯიბეში გამხმარი მაკარონი იპოვეთ? ეს სიხარბე კი არა, ბავშვური დაგეგმვაა. სერიოზული სახით გადააგდეთ ნაგავში, გულში კი ამ პატარა მკვლევარსა და მარაგის შემგროვებელს გაუღიმეთ. იზრდებიან!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('d2eca751-d4a9-42ee-89e8-a1b216e785bc'::uuid, 'სიჩუმე ციფრებში 🤫', 'როგორც იქნა, დაიძინა. სახლში ისეთი სიჩუმე ჩამოწვა, რომ ყურებში წუილი გესმით? აპლიკაციაში ხმის საზომი გახსენით. წარწერა „0 დეციბელი“ თქვენი დაღლილი, ხმაურისგან გადატვირთული ტვინისთვის მსოფლიოში საუკეთესო ვიზუალური მასაჟი იქნება.'),
  ('d6eb2191-63cd-4b2d-9410-9f12b1424bea', 'მაისურის იარლიყი მჩხვლეტს! 🏷️', 'ჩაცმას არ აპირებს, რადგან ზურგზე არსებული პატარა იარლიყი ნემსივით ჩხვლეტს? 3.5 წლის ასაკში სენსორულმა მგრძნობელობამ შეიძლება ადამიანი ჭკუიდან გადაიყვანოს. კამათს ნუ დაიწყებთ — აიღეთ მაკრატელი, იარლიყი ძირში მოაჭერით და ეს მინი-კრიზისი წამებში დაასრულეთ.'),
  ('772e1eef-c912-4a17-abaa-b5296c686fe3', 'ის ქვა ჩემი იყო! 🪨', 'ტირის, რადგან პარკიდან მოტანილი ჭუჭყიანი ქვა გადააგდეთ? თურმე ის მისი საუკეთესო მეგობარი ყოფილა. სასწრაფოდ იპოვეთ სხვა მბზინავი ნივთი და უთხარით: „ნახე, ეს იმ ქვამ გამოგიგზავნა სამახსოვროდ“. ასეთი გამოგონილი ამბით ოსტატურად განმუხტეთ სიტუაცია.'),
  ('8d7ffafe-9007-449d-a1c5-50fafa6a8a92', 'ჩემი ზღაპარი, ჩემი წესები 📖', 'ზღაპრის კითხვისას სიტყვა შეგეშალათ და მაშინვე შეგისწორათ? ესე იგი, ზეპირად დაუმახსოვრებია! დახურეთ წიგნი და უთხარით: „მაშინ დღეს საღამოს შენ წამიკითხე“. მიეცით მის ფანტაზიას გასაქანი, თავად კი უბრალოდ წამოწექით და მის ხმას მოუსმინეთ.'),
  ('ba68f77d-f963-479b-bdc5-453510fe2fd8', 'სუპის დეტექტივი საქმეშია 🥕', 'კოვზი სუპში ჩაყო, ერთადერთი ხახვის ნაჭერი იპოვა და გვერდზე გადადო? იუველირის სიზუსტეა! ახლავე გადახედეთ ჯანსაღ რეცეპტებს, ისწავლეთ, როგორ დააბლენდეროთ ხვალიდან ეს ბოსტნეული და შეუმჩნევლად დამალოთ სოუსებში — ასე ფარულად გაიმარჯვებთ.'),
  ('3f320efd-46d8-4e41-85e8-a584506068f1', 'წყვილივით, ჩუმად 🥂', 'ბავშვმა დაიძინა, სახლიც დალაგებულია. თქვენს პარტნიორთან ერთად დივანზე გვერდიგვერდ ჩამოჯექით და ტელევიზორიც კი არ ჩართოთ. უბრალოდ გადახედეთ ერთმანეთს მზერით, რომელიც ამბობს: „ესეც შევძელით და გადავრჩით“. გვერწმუნეთ, სწორედ ეს არის მშობლობის ყველაზე რომანტიკული და ნამდვილი მომენტი.'),
  ('5c1ffe1c-132b-41ee-89f2-40908e4efd15', 'მაღაზიაში ატეხილი ის საშინელი „მინდა!“ 🛒', 'სალაროსთან შოკოლადის გამო ყვირის? უკან მდგომების მზერის მიუხედავად, არ დანებდეთ. გახსენით საყიდლების სია და უთხარით: „აქ არ წერია, სალარო ამას ვერ წაიკითხავს“. გარეშე ავტორიტეტი მათთვის ყოველთვის უფრო დამაჯერებელია.'),
  ('68fe0739-89b9-4724-85e1-174aecc17d9d', 'რატომ დამელაპარაკე? 😤', 'მხოლოდ „დილა მშვიდობისა“ უთხარით და ამის გამო გაბრაზდა? უმიზეზოდ გაბუტვის პერიოდი მთელი სვლით გრძელდება. ნუ ჩაეძიებით, დაისხით ჩაი და მშვიდად დალიეთ. დარწმუნებული იყავით, 2 წუთში მოვა და მუხლებზე მოგეხვევათ. მისი ემოციები ხომ ასე არეულია!'),
  ('5a73dbf6-a948-449b-bd9f-bd6acec175f3', 'ოთხზე შემდგარი ბავშვი 🐾', 'დღეს დილით საწოლიდან ბავშვივით კი არა, ძაღლივით ოთხზე ხოხვით გამოვიდა? წესების კითხვით თავს ნუ გაიღიზიანებთ. უთხარით: „ყოჩაღ, ჩემო ჭკვიანო ბობი!“ და საუზმე მიეცით. როლურ თამაშში აყოლა გაცილებით ნაკლებ ენერგიას მოითხოვს, ვიდრე გაჯიუტება.'),
  ('b5299007-402e-4c46-9a86-5fb45df938df', 'შუაღამის უეცარი ყვირილი 😭', 'ღამით თვალდახუჭულმა ტირილით გაიღვიძა და თქვენი არ ესმის? დააკვირდით მის ტირილს — ეს ღამის შიშია. ეცადეთ, არ გააღვიძოთ; უბრალოდ მის გვერდით იყავით, ხელი ჩასჭიდეთ და მოეფერეთ. თავისით დამშვიდდება და კვლავ ღრმა ძილს მიეცემა.'),
  ('cd19d080-ed21-40f3-b449-164e996aed41', 'ჩემი სხეული მე აღარ მეკუთვნის 🔋', 'მთელი დღე ფეხზე გეკვრებათ და ხელში აყვანას ითხოვს? ფიზიკურად გამოფიტული ხართ. შეხებით გადაღლას (touched out) განიცდით. დატოვეთ ოთახში თავის სათამაშოებთან და 5 წუთით სააბაზანოში შეაფარეთ თავი — უბრალოდ განმარტოებით დატკბით. ამის უფლება გაქვთ.'),
  ('3c2e2a41-c838-4dd0-b137-24862355a226', 'კარს მე გავაღებ! 🚪', 'სახლიდან გასვლისას კარი თქვენ გააღეთ და ატირდა, უკან დაგაბრუნათ, რომ კარი დაეკეტა და თვითონ გაეღო? კონტროლის განცდა ამ ასაკში ერთ-ერთი უმნიშვნელოვანესი ფსიქოლოგიური მოთხოვნილებაა. დაე, ამაზე 1 წუთი დაკარგოთ, სამაგიეროდ ქუჩაში 30-წუთიან კრიზისს აიცილებთ თავიდან და მის თავდაჯერებულობასაც განამტკიცებთ.'),
  ('93ebf06c-8a17-42ec-bbd4-671ae644ffaa', 'წარღვნა აბაზანაში 🌊', 'ბანაობა მხოლოდ საბაბია, სინამდვილეში კი აბაზანაში ოკეანე მოაწყო და ტალღებით თამაშობს? აცადეთ თამაში. წყლის ხმაური და შხეფები მის უსასრულო, ჯიუტ ენერგიას თან გაიყოლებს. საღამოს ყოველგვარი წინააღმდეგობის გარეშე დაწვება დასაძინებლად.'),
  ('ed5a44fd-8133-4d4a-859e-893fc179d90d', 'AI-ის პასუხი უცნაურ კითხვებზე 🤖', 'კითხვაზე „დედა, ღამით ჩემი ჩრდილი სად მიდის?“ პასუხი ვერ მოიფიქრეთ? ნურაფერს გამოიგონებთ. გახსენით Anacan AI და მიიღეთ 3.5 წლის ბავშვისთვის შესაფერისი, ზღაპრული, საყვარელი და მეცნიერული პასუხი, შემდეგ კი წაუკითხეთ. თავი დიდ ფილოსოფოსად და ყოვლისმცოდნე დედად იგრძენით.'),
  ('14c25fd3-e3ee-49fb-8520-527d8c11b191', 'უკუღმა ჩაცმული სიამაყე 👕', 'პერანგი უკუღმა ჩაიცვა და გადაჭრით არ გაძლევთ გასწორების უფლებას? მისი საქმეა! მის თვალებში ჩამდგარი თავდაჯერება, რომელიც ამბობს „მე შევძელი“, სწორად ჩაცმაზე უფრო მნიშვნელოვანია. დაე, მთელი დღე ასე ამაყად იაროს — ეს მისი არჩევანია.'),
  ('4ffcb0aa-a9e4-48df-8c7b-2bcf41163980', 'ჩურჩულით დაძინება 🤫', 'საწოლიდან დგება, ოთახში დარბის და დაძინება არ უნდა? ნუ უყვირებთ. უცებ ძალიან ხმადაბლა, ჩურჩულით დაიწყეთ საუბარი. თქვენი ნათქვამის გასაგებად ყურადღების ისე დაძაბვა მოუწევს, რომ ტვინი დაიღლება და ავტომატურად ძილის რეჟიმზე გადაერთვება. სცადეთ!'),
  ('5dd3ffc3-a306-476f-91ee-6cb8332ca500', 'იდეალური სიჩუმის წამი 🛋️', 'პაზლებით ისე გართულად თამაშობს, რომ სახლში მოულოდნელად სიჩუმე ჩამოვარდა? ეჭვიანად ნუ იყურებით — მაშინვე დაისხით ყავა. ეს იშვიათი და ძვირფასი წუთები დალაგებასა და სარეცხს კი არა, სულის მოსვენებას დაუთმეთ. თქვენ რობოტი არ ხართ.'),
  ('3481c7e9-17f1-45e8-b5ca-16ba68fd1628', 'მინი-ლაბორატორია აბაზანაში 🛀', 'წყალში სხვადასხვა ფერის საპნებს ურევს და ჯადოსნურ ელექსირს ამზადებს. აბაზანა ისვრება, დიახ. მაგრამ ამ დროს ის გამხსნელებსა და ნივთიერებების შერევას ეცნობა. ეს სამეცნიერო კვლევა საღამოს დაღლილობის მოსახსნელად და მშვიდი ძილისთვის მოსამზადებლად საუკეთესო საშუალებაა.'),
  ('628064ef-a8e4-4e1f-b2f9-27acab4d05cf', 'შეხებისგან გადაღლის რევოლუცია 🔋', 'მთელი დღე თქვენს სხეულზე მცოცავი და თმის მომქაჩავი ბავშვისგან ფიზიკურად გადაიღალეთ. დაუყოვნებლივ დატოვეთ უსაფრთხო ადგილას და სხვა ოთახში გადით. განწყობის დღიურში ჩაწერეთ „ჩემი სხეული მე აღარ მეკუთვნის“ და ასე შეიმსუბუქეთ შეხებით გადაღლის სინდრომის ფსიქოლოგიური ტვირთი.'),
  ('6dfd2aa0-4f21-483a-bbab-d26de61eb620', 'საზოგადოებისგან განმარტოება კარადაში 🚪', 'სახლის შუაგულში ხმაური შეწყდა. ბავშვი ტანსაცმლის კარადაში, სიბნელეში მარტო თამაშისას იპოვეთ. ეს დეპრესია არ არის — უბრალოდ ემოციური გადატვირთვის წამია. კარი ფრთხილად მოხურეთ და პირადი სივრცის ეს ფუფუნება შეუნარჩუნეთ.'),
  ('8d6625c2-a9b5-42f5-804d-da69978a47f8', 'ტელეფონის ქურდი 📱', 'ჩაის რომ ისხამთ, აღმოაჩენთ, რომ თქვენი ტელეფონი გაუჩინარდა, დივნის უკნიდან კი ისიც თქვენსავით ამბობს „ალო“. ბავშვი თქვენს ციფრულ ჩვევებს სწავლობს.'),
  ('e750fc50-e44a-47b8-b631-5ac89b90275d', '„შენ თვითონ ჩაიცვი!“ პოლიტიკა 👖', 'ფეხებს მაღლა სწევს და ამბობს: „მე პატარა ვარ, შენ ჩამაცვი“. ბავშვები დამოუკიდებლობასა და თქვენზე დამოკიდებულებას შორის მერყეობენ. ძალით ნუ ჩააცმევთ. ტანსაცმელი გვერდით დაუდეთ და ეშმაკურად უთხარით: „ეს სუპერგმირის შარვალი თავის პატრონს ელოდება“.'),
  ('fa66784d-c126-46e1-ac35-502bd4ad5f50', 'შინაგანი სიმშვიდე ხმის საზომით 🤫', 'ბოლოს და ბოლოს დაიძინა. ყურებში კი ისევ გიწუით. აპში გახსენით „ხმის საზომი“. ეკრანზე გამოსახულ წარწერას „0 დეციბელი“ უყურეთ და ვიზუალურად დარწმუნდით, როგორ აღწევს ოთახის სიჩუმე თქვენს გონებაში და როგორ გაჯანსაღებთ.'),
  ('61c7ca48-5a19-4998-8086-07edd1d4d938', 'ნუგეში Anacan-ის საზოგადოებაში 💬', 'გახრჩობთ განცდა, რომ ვერასდროს იქნებით სრულყოფილი? დაივიწყეთ ინსტაგრამელი დედების მიერ შექმნილი ილუზია. შედით Anacan-ის საზოგადოებაში, წაიკითხეთ გულწრფელი აღიარებები დედებისა, რომელთა სახლებშიც სრული ქაოსია და რომელთა შვილებიც კედლებზე ხატავენ, შემდეგ კი საკუთარ თავს უთხარით: „მე სრულიად ნორმალური ვარ“.'),
  ('7a600dc5-32dc-4b11-81f6-fb429bfb7588', 'ჩურჩულის მისტიკური ძალა 🌙', 'საწოლიდან თავის დასაღწევად ათასგვარ მიზეზს იგონებს. ხმას ბოლომდე დაუწიეთ და მხოლოდ ჩურჩულით ელაპარაკეთ. თქვენი გაგებისთვის იძულებული გახდება, მთელი ყურადღება ფიზიკურად მოიკრიბოს, ეს კონცენტრაცია კი მის ტვინს დააჰიპნოზებს და დააძინებს.'),
  ('fbad87dc-8f76-4644-9e49-49107be8118b', 'დინოზავრის ლოგიკა 🦖', 'დილით არცერთ კითხვას არ პასუხობს და მხოლოდ ღრიალებს. დღეს ის T-Rex-ია. „ნეტავ T-Rex-ები ფაფას ჭამენ?“ — მოერგეთ მის მიერ გამოგონილ პერსონაჟს და დილის რიტუალი ცრემლების გარეშე დაასრულეთ.'),
  ('401f5436-2de1-44e1-911f-f31af21dfae8', 'მამის გამოგონილი გმირები 🦸‍♂️', 'ამ საღამოს წიგნის ზღაპრები დაივიწყეთ. მამამ მოყვეს გამოგონილი, ფანტასტიკური ამბავი, რომლის მთავარი გმირიც თავად ბავშვია. ისეთი წინადადებები, როგორიცაა „და მან ხმალი იშიშვლა და... კბილების გახეხვა დაიწყო!“, ბავშვს გულიანად გააცინებს და ძილისთვის მოამზადებს.'),
  ('cc1183e6-40b5-4a08-b574-b47668387f44', 'საკუთარი ნახატის გაკრიტიკება 🖍️', 'თავის შავ ჯღაბნილს გაჩვენებთ, გეუბნებათ: „ეს თქვენ იყავით, მაგრამ ცუდად გამომივიდა“ და ხევს. მას საკუთარი ნამუშევრის გაკრიტიკების უნარი უვითარდება! ნუ გააუფასურებთ მის გრძნობებს. ხელი შეუწყვეთ მის განვითარებას და უთხარით: „იქნებ შემდეგ ნახატში წითელი ფერიც მოსინჯო?“'),
  ('faf3013a-4d98-4178-82f0-b76954e80a74', '„ეს მე ვიპოვე“ მაღაზიაში 🛒', 'სალაროსთან მისვლისას კალათაში აღმოაჩენთ ორცხობილების შეკვრას, რომელიც თქვენ არ ჩაგიდიათ. ბავშვს ამასობაში ჩუმად „დაზვერვა“ ჩაუტარებია. გახსენით საყიდლების სია და უთხარით: „ნახე, ეს ჩვენს სიაში არ არის, შემდეგ ჯერზე ჩავწეროთ“. ასე წესის დაცვას ციფრულ ავტორიტეტს მიანდობთ.'),
  ('064802a6-44a3-418a-af04-e8b21366e4d7', 'ავეჯზე ცოცვის ოლიმპიადა 🧗‍♂️', 'ბავშვი დივნის კიდიდან ფანჯრისკენ მიცოცავს. თქვენთვის სახლი საფრთხეებითაა სავსე, მისთვის კი სპორტული დარბაზია. პანიკის შექმნის ნაცვლად სიტყვებით „ფრთხილად, ჩამოვარდები!“, უთხარით: „ხელი იქ მოკიდე“ და მოძრაობის ეს მოთხოვნილება სწორი მიმართულებით წარმართეთ.'),
  ('1c07d667-ff98-498d-8a14-c5dc48ceda8c', 'ოპერაცია „დამალული ბოსტნეული“ 🥦', 'ბავშვი წვნიანში ბრინჯის ერთადერთ მარცვალს ან სტაფილოს ნაჭერსაც კი პოულობს და ამბობს: „ამას არ შევჭამ“. გაეცანით კვების გეგმას. ისწავლეთ, როგორ მისცეთ ცილებსა და ბოსტნეულს ფერადი კექსების ფორმა და ამ პატარა ჯიუტ მზარეულს გონება ეშმაკურად აურიეთ.'),
  ('7ce3cc61-1a21-499e-a7c2-d24e3693336c', 'ჩაი წყვილისთვის 🥂', 'რთული დღის შემდეგ ჭიქებში ჩვეულებრივი ცხელი ჩაი ჩამოასხით. პარტნიორთან ერთად დივანზე პირისპირ დაჯექით, ჭიქები მიუჭახუნეთ და თქვით: „დღეს იმ ქაოსსაც გადავურჩით — შესანიშნავი გუნდი ვართ“. თქვენ თქვენი ოჯახის ურყევი საყრდენი ხართ.'),
  ('1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2', 'ჩრდილის შიში 👻', 'ქუჩაში სეირნობისას უცებ საკუთარი ჩრდილის შეეშინდა და თქვენს ზურგს უკან დაიმალა. ლოგიკას ნუ ეძებთ — 3.5 წლის ბავშვის წარმოსახვა ასე მუშაობს. უთხარით: „მოდი, ჩრდილს ზემოდან დავახტეთ!“ და ის, რისიც ეშინია, მყისიერად ფიზიკურ თამაშად აქციეთ.'),
  ('9cee1c64-59c7-411a-9cc4-1d823dfe8c01', 'ხელოვნური ინტელექტი და სიმშვიდე 🤖', 'ბავშვის მოულოდნელად დაწყებულმა ენაბორძიკმა ან ბრაზის შეტევებმა ინტერნეტში მძიმე დაავადებების ძებნა დაგაწყებინათ? შეჩერდით! ჰკითხეთ Anacan AI-ს, ხომ არ არის ეს 3 წლის ასაკისთვის დამახასიათებელი განვითარების ნახტომი და მიიღეთ პედიატრების მიერ დადასტურებული, დამამშვიდებელი პასუხი.'),
  ('d8c70945-12ad-4739-98a0-3d98184c5d44', 'ხმოვანი ეფექტები ოთახში 🪄', 'ჩართეთ ჭკვიანი ზღაპრები. ამბის კითხვისას კარის ჭრიალის, ქარისა და ჩურჩულის ხმები გამოსცეთ და ოთახში ხმოვანი თეატრი მოაწყვეთ. ეს უჩვეულო ხმოვანი ტალღები მის ყურადღებას მყისიერად გადაიტანს ზღაპრის სამყაროში, იქიდან კი — ღრმა ძილში.'),
  ('a4d74500-c7bc-4a1a-a200-c6bae74eb5ce', 'პურის შუაგული ჩემია! 🍞', 'პურის ნაჭრიდან მხოლოდ შუაგულს ჭამს და ქერქს თქვენ გაწვდით? ქერქის გამო ნუ შეეკამათებით. ხვალიდან პური ცხოველების ფორმის მეტალის ორცხობილის საჭრელებით გამოჭერით. ასეთი დიზაინი კვებასთან დაკავშირებულ ამ პრობლემას მყისიერად მოაგვარებს.'),
  ('e1513af5-17e8-478e-acc0-67084e546889', 'უბრალოდ შეისუნთქეთ მისი სურნელი 🫂', 'დღეს მართლა გაგაგიჟათ და მთელი ენერგია გამოგაცალათ? მაგრამ საწოლში ისეთი უმანკო სძინავს... ჩააქრეთ შუქი, ზღაპარს ნუ წაუკითხავთ. მის გვერდით დაწექით, ღრმად შეისუნთქეთ ბავშვის ეს სუფთა სურნელი და მადლიერი იყავით ამ დღისთვისაც.'),
  ('f1d4800f-e749-493d-9ba5-56a7cf6edfa0', '„სახლიდან გასვლა არ მინდა“ ⛅', 'ოთხ კედელში ყოფნა გახრჩობთ, ის კი დივანზე ტირის და გარეთ გასვლა არ უნდა? გახსენით ამინდისა და ტანსაცმლის განყოფილება, შეარჩიეთ სწორი კომბინაცია და, თუნდაც ძალისხმევა დაგჭირდეთ, პარკში წაიყვანეთ. როგორც კი სახეზე სუფთა ჰაერი მოხვდება, მთელი აგრესია მაშინვე გაუქრება. თქვენი გვჯერა!'),
  ('3a198cfb-0f8d-4bb9-b96b-0ead690adcbf', 'საკვების არშეხების კანონი 🚫', 'საუზმეზე პომიდორი კიტრს შეეხო და რევოლუცია დაიწყო? კეთილი იყოს თქვენი მობრძანება 3.5 წლის ბავშვის ოფიციალურ კვების ფილოსოფიაში. ლოგიკას ნუ ეძებთ — ჯანსაღ რეცეპტებში ისწავლეთ, როგორ დაყოთ თეფში სახალისო და ერთმანეთისგან იზოლირებულ ზონებად და ეს აბსურდული კრიზისი მშვიდობიანად მოაგვაროთ.'),
  ('9f8b4dfd-dfd3-4045-969a-2d6b122add47', 'დიპლომატიური მოლაპარაკება ძილის წინ 🤝', 'საწოლში ჩაწოლის თავიდან ასაცილებლად თქვენთან ოფიციალურ მოლაპარაკებას იწყებს: ორ ყლუპ წყალს დავლევ, ერთხელ ჩამეხუტე და მერე დავიძინებ. ამ ოსტატურ მანიპულაციაზე გაიღიმეთ. მიიღეთ მისი პირობა, მტკიცედ ჩააქრეთ შუქი და შეთანხმება დაუყოვნებლივ გააფორმეთ.'),
  ('d547337a-f6dc-44bb-a0b7-19904928148b', 'იატაკი ლავაა 🌋', 'იატაკი ლავაა, დივანზე ადი! წარმოსახვამ სახლი ჯუნგლებად აქცია. ცოტა ხნით გვერდზე გადადეთ თქვენი საქმეები და თუნდაც 2 წუთით თქვენც გაექეცით ლავას, რათა მის სამყაროში შეაბიჯოთ. ზოგჯერ ბავშვის წესების დაცვა სტრესისგან გათავისუფლების საუკეთესო საშუალებაა.'),
  ('6c7ca9b4-c80b-4cd6-bdd7-ff280ab39cba', 'ნაგვის ურნაში დამალული საიდუმლოებები 🗑️', 'მაღაზიაში ნაყიდ სათამაშოს კი არა, მის შესაფუთ ბუშტუკებიან პარკს ჩახუტებია და მთელი დღე იმით თამაშობს? ბავშვის ტვინს მზა სცენარები არ უყვარს — მას თავისუფლება მოსწონს. განვითარების ტრეკერში სიამაყით ჩაინიშნეთ მისი უჩვეულო შემოქმედებითობის ეს მომენტები.'),
  ('7fe2513f-2da9-40be-8ba2-3f77c91758aa', 'საღამოს მშვიდი წუთები 🛀', 'მთელი დღე „რატომებისგან“ თავი გასკდომაზე გაქვთ. ჩასვით ბავშვი თბილი წყლით სავსე აბაზანაში და ცოტა ქაფიც დაუმატეთ. თავად კი გვერდით დაჯექით და უბრალოდ წყლის ხმაზე კონცენტრირდით. წყლის ეს მაგიური ეფექტი ბავშვის სიჯიუტესაც გააქრობს და თქვენს ნერვებსაც დაამშვიდებს.'),
  ('e5f2539f-4aa6-4c0d-ad49-b97d6f90a867', 'შენ მე არ მისმენ! 😤', '„მომისმინე!“ — ამბობს და ხელებით თქვენს სახეს თავისკენ აბრუნებს. მას მხოლოდ თქვენი ფიზიკური ყოფნა არ სჭირდება — სურს, რომ თქვენი ყურადღების 100% მას ეკუთვნოდეს. სულ რაღაც 3 წუთით გადადეთ ტელეფონი ან საქმე, რომელსაც აკეთებთ, თვალებში შეხედეთ და ყურადღებით მოუსმინეთ. ეს თავიდან აგაცილებთ წუწუნს, რომელიც შესაძლოა საათობით გაგრძელდეს.'),
  ('0da92da6-227b-4bc4-8733-939d83f883ad', 'შუაღამის ფილოსოფია 🦉', 'როგორც კი საწოლში წვება, ისეთ ღრმა კითხვებს სვამს, როგორიცაა: „დედა, ღრუბლები რატომ არ ცვივა?“ მისი მიზანი მეცნიერების შესწავლა კი არა, თქვენთან საუბარი და დაძინების გადადებაა. მოკლე, გამოგონილი პასუხი გაეცით, მაგალითად: „იმიტომ, რომ მაღლა სძინავთ“, შემდეგ კი „ჭკვიანი ზღაპრების“ ნაზი მელოდია ჩართეთ და ძილისთვის საჭირო სიმშვიდე მტკიცედ დაამყარეთ.'),
  ('1b4bdd7d-042a-4be6-a59f-82892d67ff8d', 'ის უხერხული კითხვა მაღაზიაში 😳', 'სალაროს რიგში დგომისას ხმამაღლა გკითხათ: „ამ დეიდას ასეთი თმა რატომ აქვს?“ ნუ შეარცხვენთ და ნუ გააჩუმებთ — მისი ყურადღება მაშინვე აპში არსებულ „საყიდლების სიაზე“ გადაიტანეთ: „მოდი, ვნახოთ, ვაშლი ვიყიდეთ თუ არა?“ — ასე სიტუაციიდან დიპლომატიურად გამოძვრებით.'),
  ('62a75f9a-ac96-44d5-9f0d-ddc0ab3d545e', 'ის მაისური რატომ გარეცხეთ?! 👕', 'სახლში გლოვა გამოცხადდა, რადგან მისი საყვარელი, უკვე ფერგადასული მაისური სარეცხ მანქანაში ჩადეთ? ბავშვების მიჯაჭვულობა ნივთებისადმი ზოგჯერ ყოველგვარ ლოგიკას სცდება. ნუ შეეკამათებით — მაშინვე გახსენით „ბავშვის ფოტოსესია“, ასეთ გაბრაზებულ მდგომარეობაში ფოტო გადაუღეთ და ყველაფერი სიცილად აქციეთ. ხრიკი — „მოდი, ვნახოთ, ეკრანზე როგორი გაბრაზებული ჩანხარ“ — ყურადღებას მყისიერად გადაატანინებს. სცადეთ!'),
  ('4e937fd6-67f9-496a-b0c5-be8bf0840c6d', 'ჩააქრეთ შუქი — ჩრდილების თეატრი იწყება 🐰', 'სიბნელის ეშინია და დერეფანში მარტო გასვლა არ სურს? ოთახში შუქი მთლიანად ჩააქრეთ და პატარა ფანარი აანთეთ. ხელებით კედელზე ძაღლისა და ფრინველის ჩრდილები გამოსახეთ და სიბნელე მისთვის საშიში ადგილიდან სათამაშო სივრცედ აქციეთ. მისი დაძინება მხოლოდ დროის საკითხი იქნება.'),
  ('6d8c96e4-6f09-4805-a4a8-4acf034ab6c9', 'თქვენც გჭირდებათ offline რეჟიმი ☕', 'თავის სათამაშოებში ისეა გართული, რომ სახლში მოულოდნელად სრული სიჩუმე ჩამოწვა? გთხოვთ, ეს წამები სახლის დაგვას ან ტანსაცმლის დაკეცვას ნუ შესწირავთ! დივანზე წამოწექით, „განწყობის დღიურში“ უბრალოდ „5-წუთიანი სიმშვიდე“ ჩაწერეთ და ყავა ცხელ-ცხელი მიირთვით. თქვენც ხომ ამ ოჯახის წევრი ხართ.'),
  ('f30558ce-2e74-4368-ad59-ff72d43fefc7', 'მე არ დამიღვრია, დათუნიამ დაღვარა! 🧸', 'წყალი განზრახ დაღვარა და ყველაფერი თავის სათამაშოს დააბრალა? ის არ იტყუება — უბრალოდ 3.5 წლის ასაკისთვის დამახასიათებელი თავდაცვის მექანიზმი აღმოაჩინა. ნუ შეეკამათებით. უთხარით: „მაშინ მოდი, დათუნიას ვასწავლოთ, როგორ უნდა გაწმინდოს“ და ტილო ხელში მიეცით. ასე პასუხისმგებლობასაც ისწავლის და მისი ეგოც არ შეილახება.'),
  ('1633765a-e691-4a02-b657-169e03223f3f', 'დედის საკვები მარაგი 🥗', 'მის დასანაყრებლად მრავალფეროვან მენიუს იგონებთ, თავად კი ისევ ფეხზე დამდგარი მშრალ წასახემსებელს ჭამთ? ჯანსაღ რეცეპტებში არა მხოლოდ ბავშვებისთვის, არამედ დედებისთვისაც შეარჩიეთ ენერგიის მომცემი, რკინითა და კალციუმით მდიდარი სადილი, რომელიც 10 წუთში მზადდება — იზრუნეთ საკუთარ თავზეც.'),
  ('2d30d5d5-9abc-4c5e-847a-462fa693fbda', 'თამაში „ჩემი სათამაშო ავადაა“ 🩺', 'იღებს სათამაშო სტეთოსკოპს, სერიოზულად სინჯავს დათუნიას და ჭრილობაზე პლასტირს აკრავს. სიმბოლური თამაშით ბავშვი თანაგრძნობასა და მზრუნველობას იაზრებს. თქვენც დაწექით და საავადმყოფოში პაციენტის როლი მოირგეთ — მიეცით საშუალება, 5 წუთის განმავლობაში ჩუმად გაგსინჯოთ.'),
  ('37ed4aaf-5c8b-418c-8274-802f79f0bf41', 'მარტივი დაძინება ჭკვიანი ზღაპრებით 🪄', 'კლასიკური წიგნები უკვე ზეპირად იცით. გახსენით ჭკვიანი ზღაპრები, მთავარ გმირად თქვენი ბავშვი აქციეთ, დასაპყრობ ადგილად კი მისი ოთახი — ასე უჩვეულო და ძალისხმევის არმომთხოვნი ძილისპირული სეანსი შექმენით.'),
  ('72e4a373-da8e-4cf7-b36b-25d3d3a13b6e', 'უბრალოდ ჩაეხუტეთ 🫂', 'არც თამაშია საჭირო, არც წიგნი და არც ზღაპარი. ამ საღამოს უბრალოდ გულში ჩაიკარით, ღრმად შეისუნთქეთ მისი მშვენიერი სურნელი და სიბნელეში ჩასჩურჩულეთ, რამდენად ძვირფასია თქვენთვის და როგორ ძლიერ გიყვართ.'),
  ('8d0e8d79-2ed2-4d47-9d71-055f26b53574', 'უსულო საგნებთან საუბარი 🗣️', 'პარკში ქვას ან სახლში სკამს სრულიად სერიოზულად ელაპარაკება და საყვედურობს. სიმბოლური თამაშით ბავშვი მის გარშემო არსებულ სამყაროს იაზრებს.'),
  ('b3a793f1-dd90-4ef7-9ff1-f7ee9746e0d9', 'დილის დამალობანა 🙈', 'სამსახურში ან საბავშვო ბაღში გაგვიანდებათ, ის კი ფარდის უკან იმალება და გეუბნებათ: „მიპოვე!“ მართალია, ნერვები დაჭიმული გაქვთ, მაგრამ ყვირილი პროცესს კიდევ უფრო გაახანგრძლივებს. სიტყვებით „ნეტავ, სად არის ჩემი საყვარელი პატარა?“ 2 წუთით აჰყევით თამაშში, იპოვეთ და იქიდან გამოიყვანეთ.'),
  ('9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e', 'ფიზიკის კანონებთან მებრძოლი სიჯიუტე 💧', 'წყალი მაგიდაზე დაღვარა და ახლა ტირილით ითხოვს, რომ ის ისევ ჭიქაში ჩაასხათ! დიახ, ამ ოთახში ლოგიკას ადგილი არ აქვს — აქ მხოლოდ გამოუსწორებელი შეცდომით გამოწვეული იმედგაცრუებაა. ახსნას ნუ ეცდებით. მიეცით ხელში ტილო, უთხარით: „მოდი, ეს წყალი გავაქროთ“ და ყველაფერი თამაშად აქციეთ.'),
  ('aff11dbf-a5df-4f87-ba8b-797021b1bfe4', 'დედის ოფლაინ თავშესაფარი 🚪', 'ხმაურისგან ყურები გიწუით. ბავშვი უსაფრთხო ადგილას დატოვეთ (ან მამას ჩააბარეთ), სააბაზანოში შედით და კარი დაკეტეთ. უბრალოდ 5 წუთი უყურეთ კედელს, არაფერი აკეთოთ, ტელეფონიც კი არ ჩართოთ. ეს ხანმოკლე სიჩუმე ყველაზე ძლიერი საშუალებაა, რომელიც დედის როლში დაბრუნებაში დაგეხმარებათ.'),
  ('f965edcf-2124-46c3-82a9-e8d418ee755a', 'მამას ფრენის რეჟიმი ✈️', 'ბავშვმა სახლში ენერგია ვერ დახარჯა და დაძინება არ სურს. მამას დივანზე მოუხმეთ. როცა ის ბავშვს ჰაერში აიყვანს და თვითმფრინავივით „გააფრენს“, ოთახში გაჟღერებული სიცილი დაგროვილ ფიზიკურ დაძაბულობას წამებში გააქრობს. ახლა ჯერი მამაზეა.'),
  ('535821ef-9689-4454-87b8-1d43fe500b62', 'ახალი ენის გამოგონება 🗣️', 'ემოციებს საგნებს მიაწერს და სრულიად გამოგონილ, პოეტურ წინადადებებს ქმნის, მაგალითად: „ჩემი სათამაშო მოიწყინა“ ან „ცამ იტირა“. მისი ლექსიკა და ემოციური ინტელექტი ელვის სისწრაფით ვითარდება. დაუყოვნებლივ ჩართეთ ბავშვის ფოტოსესიის ვიდეორეჟიმი და ეს საყვარელი ფილოსოფია სამუდამოდ შეინახეთ.'),
  ('baf0af3c-984e-45f1-a68f-93e13e9f1cef', 'სამზარეულოს ლიდერი საქმეშია 🧑‍🍳', 'როცა კექსს ამზადებთ, აუცილებლად მოინდომებს გვერდით სკამზე დადგომას და ფქვილის თავად ჩაყრას. თუ ნებას დართავთ, სამზარეულოში ქაოსი დატრიალდება. მიეცით ცარიელი ჯამი, წყალი და ცოტაოდენი ფქვილი და უთხარით: „შენი კექსის ცომი თავად მოზილე“. ქაოსი მაინც იქნება, მაგრამ მისი ეგო სრულად დაკმაყოფილდება.'),
  ('cba9ff3e-e38f-40b7-b48d-13e030f8993a', '„შენ თვითონ ჭამე!“ — ამბოხი 🥣', 'მიუხედავად იმისა, რომ დამოუკიდებლად ჭამა შეუძლია, ჯიუტად ითხოვს, თქვენ აჭამოთ, შემდეგ კი კოვზს ხელს ჰკრავს და ტირის. ეს წინააღმდეგობების პერიოდია. ნურც მისთვის ლუკმების ჩადებას ეცდებით და ნურც იმის შეგეშინდებათ, რომ მშიერი დარჩება. დაუდეთ თეფში წინ, უთხარით: „როცა მოგშივდება, შეჭამ“ და მაგიდიდან ადექით. თავად შეჭამს.'),
  ('5672be3d-87ec-469d-a4b7-fca0b00ec9ac', 'პარკის პოლიტიკა 🤝', 'სასრიალოზე სხვა ბავშვს ხელს ჰკრავს, რომ თავად ჩამოსრიალდეს? გაზიარება მისთვის ჯერ კიდევ რთული და ბოლომდე გაუგებარი ცნებაა. შერცხვენის ან დასჯის ნაცვლად, უბრალოდ შეახსენეთ წესი და უთხარით: ახლა მისი ჯერია.'),
  ('7b9a42e6-44aa-4528-9036-fbb93f662348', 'მზე რატომ მიყურებს?! ☀️', 'დილით თვალის გახელისთანავე ამბობს: მზე რატომ მიყურებს პირდაპირ თვალებში? — და ხმამაღლა ტირის? ნუ ეცდებით ლოგიკის ძიებასა და ბუნებრივი მოვლენების ახსნას — ის უბრალოდ ბრაზობს, რადგან სამყაროს ვერ აკონტროლებს. ჩამოაფარეთ ფარდა, უთხარით: მზე შენთვის დავმალე — და ეს აბსურდული პრობლემა წამებში მოაგვარეთ.'),
  ('bf33243a-24ca-4b24-a11a-d703c038cdcf', 'ჩემს მანქანას ჯერ არ სძინავს! 🚗', 'დაძინების თავიდან ასაცილებლად ჯიუტად ამბობს: ჩემს მანქანას არ ეძინება? ბავშვები ხშირად საკუთარ უძილობასა და წინააღმდეგობას სათამაშოებს მიაწერენ. ნუ შეეკამათებით — გახსენით ჭკვიანი ზღაპრები და შექმენით ზღაპარი მანქანებზე. როგორც კი მანქანა დაიძინებს, ბავშვიც ავტომატურად დახუჭავს თვალებს. სცადეთ და თავად ნახავთ!'),
  ('5c063277-1aff-4166-9dbe-d6ab5866cdbd', 'პურს ქერქი მოაჭერით! 🍞', 'ტოსტის მხოლოდ რბილ ნაწილს ჭამს და კიდეებზე კატეგორიულ უარს ამბობს? ამ ასაკს თავისი განსაკუთრებული ვიზუალური ესთეტიკა აქვს. ისწავლეთ პურის საყვარელი ცხოველების ფორმებად დაჭრა. ასეთი დიზაინი ამ კამათს მყისიერად დაასრულებს.'),
  ('a42141c6-7a93-4719-be36-e495b333ffee', 'ჩუმად მზერის სიამოვნება 🥂', 'ბავშვმა დაიძინა, სახლი დალაგებულია. პარტნიორთან ერთად დივანზე გვერდიგვერდ დაჯექით და ტელევიზორიც კი არ ჩართოთ. უბრალოდ შეხედეთ ერთმანეთს მზერით, რომელიც ამბობს: დღესაც გადავრჩით. დამიჯერეთ, გადაღლილი მშობლობის ყველაზე რომანტიკული და ნამდვილი მომენტი სწორედ ეს არის.'),
  ('fbd48b54-2407-4752-a5b5-4e335233ace4', 'უხილავი ლაქის ტრაგედია 👕', 'პერანგზე მხოლოდ მიკროსკოპით შესამჩნევი ლაქა იპოვა და ჩაცმაზე უარი თქვა? სველი ხელსახოცით ვითომ მოაშორეთ ლაქა და უთხარით: ჯადოსნურად გავაქრე. ბავშვის გონებას დედის ჯადოქრობის ყოველთვის სჯერა — სცადეთ და თავად ნახავთ.'),
  ('081fe93d-51fc-4e73-b956-ea2d06dcec72', 'წყალი სხვა ჭიქით მიეცით! 🥤', 'იმიტომ, რომ წყალი ყვითელ ჭიქაში მიეცით, ოთახში ერთი ამბავი ატყდა? ზედმეტად ნუ ჩაუღრმავდებით — ის უბრალოდ თქვენს საზღვრებს ამოწმებს. მაშინვე გადაასხით წყალი მისთვის სასურველ ჭიქაში, ოთახში მშვიდობა აღადგინეთ და ენერგია დღის დარჩენილი ნაწილისთვის შემოინახეთ.'),
  ('12e39cd9-ad30-497d-8902-0c8e0d1a5c56', 'პარკიდან წამოსვლის შეჯიბრების ტაქტიკა 🌳', 'პარკიდან წამოსვლის დროა და ტირილის შეტევა დაიწყო? ძალით წამოყვანა არ გაჭრის. უთხარით: „ვნახოთ, მანქანამდე პინგვინივით ვინ უფრო სწრაფად მივა?“ — და მისი ყურადღება მაშინვე სახალისო შეჯიბრებაზე გადაიტანეთ. მას აუცილებლად მოუნდება გამარჯვება.'),
  ('ec5e51b0-e017-4226-9363-9dfff1dce391', 'დივანზე ჭიდაობა მამასთან 🤼‍♂️', 'დაძინებას რომ თავი აარიდოს, გაიქცა და დაიმალა? ახლა მამას გადაეცით ეს საქმე. მიეცით საშუალება, დივანზე თამაშით იჭიდაონ. ეს ხმაურიანი, ოფლის მომგვრელი თამაში ბავშვს დარჩენილ ჯიუტ ენერგიასაც დაახარჯინებს და ძილს ადვილად მიაბარებს.'),
  ('01fb525b-af8a-41d4-8fd1-724d4fd01667', 'მუსიკალური ჰიპნოზის ეფექტი 🎶', 'სცადეთ, საღამოობით უმიზეზოდ ატეხილი ქარიშხალი მშვიდი კლასიკური მუსიკით ჩააცხროთ. გამორთეთ ტელევიზორი. ხშირად ეს მარტივი ხრიკი დაბალი სიხშირის ხმაურს ფარავს და ოთახში თითქოს სასწაულებრივ სიმშვიდეს ამყარებს.'),
  ('d8b40eb7-3665-4514-839c-874f3d30ec40', 'მისივე მოგონილი გამოთქმები 🗣️', 'ისეთ უცნაურ წინადადებებს ამბობს, როგორიცაა „ცამ იტირა“ ან „მანქანა გაიბუტა“. მისი ლექსიკა ქარიშხალივით იზრდება და ის სიტყვებით თამაშობს. გახსენით განვითარების ტრეკერი და ეს ტკბილი, პოეტური სიბრძნე არქივში შეინახეთ — წლების შემდეგ წაიკითხავთ და ბევრს იცინებთ.'),
  ('f96cc98d-a4e0-44e3-9617-a284b205c20e', 'ეკრანთან გატარებული დროის გამო სინდისის ქენჯნა 📺', 'დღეს ბევრი საქმე გქონდათ და ბავშვმა დიდხანს უყურა ტელევიზორს? სინდისის ქენჯნა გაწუხებთ? ყოველი დღე იდეალური ვერ იქნება. ზოგჯერ ეკრანი ყველაზე უწყინარი ძიძაა, რომელიც დიდი ქაოსისგან გვიხსნის. თავს ნუ დაიდანაშაულებთ.'),
  ('246edaf3-5d30-44d2-bda4-13ec5fbf5f36', 'ჩრდილების თეატრი ბნელ ოთახში 🐰', 'სიბნელის ეშინია და დასაძინებლად არ მიდის? ოთახში შუქი მთლიანად ჩააქრეთ და პატარა ფანარი აანთეთ. ხელებით კედელზე ძაღლისა და ჩიტების ჩრდილები გამოსახეთ. მისთვის საშიში სიბნელე სათამაშო სივრცედ აქციეთ და დაძინებასაც აღარაფერი დააკლდება.'),
  ('d3b4180b-5723-4f72-a6c8-b4229f2e876c', 'დინოზავრები ფაფას არ ჭამენ! 🦖', 'დილით არცერთ კითხვაზე არ პასუხობს და მხოლოდ ღრიალებს? დღეს ის T-Rex-ია. ჰკითხეთ: „ნეტავ T-Rex-ები საუზმობენ?“ აჰყევით მის გამოგონილ პერსონაჟს და სუფრასთან ცრემლების გარეშე დასვით.'),
  ('e089800c-6f76-4909-bafd-021551368a5f', 'დღეს ძალა აღარ შემრჩა 🛑', 'ყველაფერი ერთდროულად დაგატყდათ თავს და ხმას აუწიეთ. ახლა კი სინდისი გაწუხებთ. თქვენ რობოტი არ ხართ. გახსენით განწყობის დღიური და დაწერეთ: „დღეს მართლა ძალიან დავიღალე“. ყალბი ღიმილის იძულებით მორგებაზე მეტად სწორედ ეს გულწრფელი აღიარება დაგეხმარებათ.'),
  ('a8aeb934-2767-4365-a584-e2b99fc16215', 'თამაში „ვინ ხარ?“ 🎭', 'დილით ისე შემოგხედათ, თითქოს უცხო იყავით, და გკითხათ: „ვინ ხარ? დედაჩემი სად არის?“ ეს ახალი როლური თამაშია. უთხარით: „მე მეზობელი დეიდა ვარ, დედაშენი მალე მოვა“. დაე, დილიდან ოთახი სიცილმა აავსოს — ეს გაჯიუტებასთან ბრძოლაზე გაცილებით ნაკლებ ენერგიას წაგართმევთ.'),
  ('cf7b3532-560e-4c59-af5f-4a64a8510605', 'დაძინება ზღაპრის წაკითხვის გარეშე 🪄', 'დღეს საღამოს ზღაპრის წასაკითხად ძალა აღარ გაქვთ? ჩართეთ ჭკვიანი ზღაპრები. ფონად მხოლოდ მოჩურჩულე ტყისა და ქარის ხმები დატოვეთ. სიბნელეში ბუნების ხმებს მოუსმინეთ და ხმაურისგან ორივემ დაისვენეთ. თვალებიც მაშინვე დაისვენებს.'),
  ('f8301d61-e90d-4d1c-b4e2-7f1feb3be70d', 'სარეცხ მანქანაში დავიწყებული განძი 🍝', 'შარვლის რეცხვისას ჯიბეში გამხმარი მაკარონი ან ქვა აღმოაჩინეთ? ეს სიხარბე კი არა, ბავშვური კვლევაა. სერიოზული სახით გადააგდეთ ნაგავში, მაგრამ გულში ამ პატარა მარაგის შემგროვებელს გაუღიმეთ. განვითარების ტრეკერში ეს ამბავი სახალისო მომენტად ჩაინიშნეთ.'),
  ('3f11dc71-3a89-4499-8bac-19038f6fdeb4', 'უცნაური შიშების დასაწყისი 🤖', 'უცებ აბაზანაში წყლის ჩასადინებელი ხვრელის შეეშინდა? ინტერნეტში დაავადებების ძებნას ნუ დაიწყებთ. ჰკითხეთ Anacan AI-ს და გაიგეთ, რომ ეს ამ ასაკისთვის დამახასიათებელი წარმოსახვით გამოწვეული სრულიად ნორმალური და დროებითი ფობიაა — და პანიკაც ჩაცხრება.'),
  ('51e9982e-8a0e-4e2c-9ee7-749ec67f6283', 'მე თვითონ შევჭამ! 🥣', 'მიუხედავად იმისა, რომ დამოუკიდებლად ჭამა შეუძლია, დაჟინებით ითხოვს, თქვენ აჭამოთ, კოვზს რომ უწვდით კი ხელს ჰკრავს და ტირის. თვითონაც არ იცის, რა უნდა. დაუდეთ თეფში წინ, უთხარით: „როცა მოგშივდება, შეჭამ“ და სუფრიდან ადექით. როცა მოშივდება, თვითონ შეჭამს.'),
  ('cc8c59da-7b2e-4da4-87ec-e11a59ea5011', 'ცოტა დრო საკუთარ თავსაც დაუთმეთ 💆‍♂️', 'ბავშვის დაძინების შემდეგ პარტნიორს სთხოვეთ, მხრებზე 10-წუთიანი მასაჟი გაგიკეთოთ. მთელი დღის სირბილისგან კისერი დაგეჭიმათ. თქვენ უბრალოდ ერთ ჭერქვეშ მცხოვრები მშობლები კი არა, ერთმანეთის უახლოესი ემოციური მხარდამჭერებიც ხართ.'),
  ('68be8da2-a2bd-442f-bb8b-f854ddbaa84b', 'Instagram-ის დედები და რეალობა 📱', 'Instagram-ის გახსნისთანავე სხვების იდეალური ბავშვების დანახვამ გული ნუ დაგწყვიტოთ! დახურეთ ეს აპი და შედით Anacan-ის საზოგადოებაში. როცა დაინახავთ, რომ სხვების სახლებშიც ისეთივე ქაოსია, როგორიც თქვენსაში, ბავშვები კი ისევე ხმაურობენ, თქვით: „მე სრულიად ნორმალური ვარ!“'),
  ('9d186c69-6a80-405e-9b2f-01d72d720233', 'ზარის დარეკვისთანავე ვიძინებთ ⏱️', 'დაძინების დრო სულ უფრო იწელება. წყალი, ტუალეტი, კედელთან დამშვიდობება... დააყენეთ ტელეფონის ტაიმერი. შემოიღეთ წესი: ზარის ხმაზე ყველა აქრობს შუქს. ამ ხმას რომ გაიგონებს, ყოველგვარი პროტესტის გარეშე ჩაწვება საწოლში.'),
  ('e4247830-a48b-4a17-9555-7ca391f03a7d', 'ოთხზე დამდგარი ბავშვი 🐾', 'დღეს დილით საწოლიდან ბავშვივით კი არა, ძაღლივით ოთხზე გამოხოხდა? წესების კითხვით თავს ნუ გაიღიზიანებთ. უთხარით: „ყოჩაღ, ჩემო ჭკვიანო ბობი“ და საუზმე მიეცით. როლურ თამაშში აყოლა გაცილებით ნაკლებ ენერგიას მოითხოვს, ვიდრე გაჯიუტება.'),
  ('051e4221-4f19-4e4b-a097-d797006e0813', 'იდეალური სიჩუმის წამი 🛋️', 'პაზლებით ისეა გართული, რომ სახლში უცებ სიჩუმემ დაისადგურა? ნურაფერს დაეჭვდებით, მაშინვე დაისხით ფინჯანი ყავა. ეს იშვიათი, ოქროს წუთები დალაგებასა და ტანსაცმელს კი არა, სულის მოთქმასა და ჭერის ყურებას დაუთმეთ. თქვენ რობოტი არ ხართ.'),
  ('87efef38-8bd8-470c-82a9-956ee26f1fa2', 'მაისურის იარლიყი მჩხვლეტს! 🏷️', 'არ ჩაიცვამს, რადგან ზურგზე ის პატარა იარლიყი ნემსივით ჩხვლეტს? ამ ასაკში სენსორულმა მგრძნობელობამ შეიძლება ჭკუიდან გადაგიყვანოთ. კამათს ნუ დაიწყებთ — აიღეთ მაკრატელი, ძირში მოაჭერით და ეს მინი-კრიზისი წამებში მოაგვარეთ.'),
  ('d321475d-a2ef-4c95-8a95-ccdb6522c470', 'ჩურჩულით ჩაძინება 🤫', 'საწოლიდან დგება, ოთახში დარბის და დაძინება არ უნდა? ნუ დაუყვირებთ. უცებ ძალიან ჩუმად, ჩურჩულით დაიწყეთ საუბარი. თქვენს გასაგებად ყურადღების ისე მოკრება მოუწევს, რომ ტვინი დაიღლება და ავტომატურად ძილის რეჟიმზე გადავა. სცადეთ!'),
  ('7e80987d-061d-4fcd-8171-45d84324b66e', '„ჩემმა სათამაშომ დააქცია!“ — ტყუილი 🤷‍♂️', 'წყალი განზრახ დაღვარა, მაგრამ თითით მანქანისკენ მიუთითა და თქვა: „მან გადმოაგდო“? ეს ტყუილი კი არა, თავდაცვის მექანიზმია. უთხარით: „მოდი, მანქანასაც ვასწავლოთ, როგორ უნდა დაალაგოს“ — და ოსტატურად გადაატანინეთ ყურადღება.'),
  ('a3c5807d-b2c4-4369-a70a-3e8219c1c3ef', 'სიჩუმე ციფრებში 🤫', 'როგორც იქნა, დაიძინა. სახლში ისეთი სიჩუმე ჩამოწვა, რომ ყურებში ზუზუნი გესმით? აპში ხმის საზომი გახსენით. წარწერა „0 დეციბელი“ თქვენი ხმაურით გადაღლილი და გაბრუებული ტვინისთვის მსოფლიოში საუკეთესო ვიზუალური მასაჟი იქნება.'),
  ('c034d9ff-ba06-4346-b3af-4ee27df0fc64', 'ოპერაცია „უხილავი ბოსტნეული“ 🥦', 'წვნიანში სტაფილოს ერთადერთი ნაჭერი იპოვა და თქვა: „ამას არ შევჭამ“? ნაცნობი სიტუაციაა! ბოსტნეული პიურედ აქციეთ და სოუსებში შეურიეთ — ვნახოთ, ახლა როგორ იპოვის! აჯობეთ მის კულინარიულ გამჭრიახობას.'),
  ('3b221a5a-9106-4d1d-8e8e-3de653008273', 'ჩემი სხეული მე აღარ მეკუთვნის 🔋', 'მთელი დღე ფეხზე გეკვრებათ და ჩახუტებას ითხოვს? ფიზიკურად გამოფიტული ხართ. შეხებით გამოწვეულ გადაღლას განიცდით. დატოვეთ ოთახში თავის სათამაშოებთან და 5 წუთით სააბაზანოში შეიკეტეთ. უბრალოდ შეიგრძენით ეს განმარტოება.'),
  ('633ad245-30eb-4956-9f39-7177c312745a', 'უეცარი ყვირილი შუაღამისას 😭', 'ღამით თვალდახუჭული, ტირილით გაიღვიძა და თქვენი ხმა არ ესმის? დააკვირდით მის ტირილს — ეს ღამის ტერორია. ნუ ეცდებით მის გაღვიძებას, უბრალოდ გვერდით დარჩით, ხელი ჩაჰკიდეთ და მოეფერეთ. თავისით დამშვიდდება და კვლავ ღრმა ძილში ჩაიძირება.'),
  ('8febb55a-81bd-4c4c-969e-a2b64ee79f90', 'პატარა დამხმარის ქაოსი სამზარეულოში 🧑‍🍳', 'ცომის გაბრტყელებისას სკამი მოიტანა და დაჟინებით მოითხოვა, რომ ფქვილი თავად დაეყარა? თუ არ მისცემთ უფლებას, ატირდება. მიეცით პატარა პლასტმასის ჯამი და ცოტაოდენი ფქვილი. სამზარეულო აირევა, მაგრამ მისი სერიოზული შეფ-მზარეულის გამომეტყველება ამ დალაგებად ნამდვილად ღირს.'),
  ('026f55a4-9f0c-4ac0-9b08-0a6b14b79c2b', 'კარს მე გავაღებ! 🚪', 'სახლიდან გასვლისას კარი თქვენ გააღეთ, მან კი ტირილით დაგაკეტვინათ და შემდეგ თავად გააღო? ამ ასაკში კონტროლის შეგრძნება ყველაზე მნიშვნელოვანი ფსიქოლოგიური მოთხოვნილებაა. სჯობს ახლა 1 წუთი დაკარგოთ, ვიდრე ქუჩაში 30-წუთიანი კრიზისი გადაიტანოთ.'),
  ('9e3821dd-5beb-4da8-ba9b-4369b4836b0a', 'მაღაზიის შუაგულში გაშეშება 🛒', 'მაღაზიის შუაგულში გაჩერებულხართ და გიფიქრიათ: „რის საყიდლად მოვედი?“ დედის გონება მართლაც უამრავი რამითაა გადატვირთული. აპში „საყიდლების სიის“ გახსნა და ამ ციფრული მეხსიერების ნდობა ყოველთვის დაგიხსნით ასეთი ქაოსისგან.'),
  ('c3a12f76-8197-4f4b-b339-db8bd083cf0a', 'წყალდიდობა აბაზანაში 🌊', 'ბანაობა მხოლოდ საბაბია, სინამდვილეში კი აბაზანაში ოკეანე მოაწყო და ტალღებით თამაშობს? აცადეთ თამაში. წყლის ხმაური და შხეფები მასში დაგროვილ დაუსრულებელ, ჯიუტ ენერგიას ჩამორეცხავს. საღამოს ყოველგვარი წინააღმდეგობის გარეშე დაწვება საწოლში.'),
  ('006ab58d-d1e7-4e1c-a78e-139ada266050', 'უკუღმა ჩაცმული სიამაყე 👕', 'პერანგი უკუღმა ჩაიცვა და არაფრით გაძლევთ გასწორების უფლებას? მისი ნებაა! მის თვალებში დანახული თავდაჯერება, რომელიც ამბობს „მე შევძელი“, სწორად ჩაცმაზე უფრო მნიშვნელოვანია. მიეცით საშუალება, მთელი დღე ასე ამაყად იაროს — ეს მისი თავისუფალი არჩევანია.'),
  ('a6797020-6e00-4e51-85e1-ce4c1dc47785', 'როცა თქვენი სიტყვა აღარ ჭრის, მამა ერთვება 🤡', 'თქვენს ნათქვამს აღარ აქცევს ყურადღებას და ჯიუტობს? მამა მოვიდა, უცნაური ცხოველების ხმები გამოსცა და სასაცილო სახეები მიიღო, ბავშვმა კი მაშინვე სიცილი დაიწყო? ზოგჯერ კაცების ეს ალოგიკური იუმორი მართლაც იხსნის ოჯახურ სიტუაციას. უბრალოდ გვერდიდან უყურეთ.'),
  ('bf79338f-3f38-4811-b226-50574547225b', 'AI-ის პასუხი უცნაურ კითხვებზე 🤖', 'კითხვაზე „დედა, ღამით ჩემი ჩრდილი სად მიდის?“ პასუხი ვერ მოიფიქრეთ? ნურაფერს შეთხზავთ. გახსენით Anacan AI, მიიღეთ ამ ასაკისთვის შესაფერისი, ზღაპრული და მარტივი სამეცნიერო პასუხი და ბავშვს წაუკითხეთ. თავს დიდ ფილოსოფოსად იგრძნობთ.'),
  ('50a90b1b-61b0-4de1-8146-038e23b46eb9', 'ჩემში დაგროვილი ბრაზის დაწერა 📝', 'ვერავინ ამჩნევს, რამდენად იღლებით სახლში, და ეს გაბრაზებთ? გახსენით განწყობის დღიური. დაწერეთ იქ ყველაფერი, რამაც დღეს ჭკუიდან გადაგიყვანათ. ყალბი ღიმილის ნაცვლად, ემოციის მიღება და მისი სიტყვებით გადმოცემა ბევრად მეტად დაგეხმარებათ.'),
  ('86283ea0-922f-4b91-8fed-55bf6231330d', 'ხანგრძლივი საუბრები უსულო საგნებთან 🗣️', 'პარკში ქვას ან სახლში სკამს სრული სერიოზულობით რაღაცებს უყვება? თამაშის მეშვეობით ის წესებსა და სამყაროს შეიცნობს.'),
  ('b3273f0d-ec07-48f9-82e7-89e57daaf623', 'ამ საღამოს უბრალოდ ჩავეხუტოთ 🫂', 'არც თამაშია საჭირო და არც ხმაურიანი წიგნი. ამ საღამოს უბრალოდ გულში ჩაიკარით, ღრმად შეისუნთქეთ მისი სუფთა, ბავშვური სურნელი და სიბნელეში ჩასჩურჩულეთ, რამდენად ძვირფასია თქვენთვის. ეს ორივესთვის საკმარისი იქნება.'),
  ('113aa528-0657-4840-905d-63eec2aa048b', 'მე ვიცი, თქვენც გასწავლით ☝️', 'მოდის და ისეთი სერიოზული და ჭკვიანური გამომეტყველებით გიხსნით იმას, რაც უკვე იცით? ასე საკუთარ გონებრივ შესაძლებლობებს ამოწმებს. სიცილი რომ შეიკავოთ, ტუჩზე იკბინეთ, ძალიან სერიოზულად მოუსმინეთ და უთხარით: „მართლა? დიდი მადლობა“.'),
  ('70129896-2f43-4370-bbff-f84bbbb58845', 'როცა მამა ზღაპარს არასწორად ჰყვება 📖', 'ამ საღამოს ზღაპრის მოყოლის ჯერი თქვენი არ არის. ზღაპრების წიგნი მამას მიეცით. მან კი ამბავი განზრახ უკუღმა, სასაცილოდ და აბსურდულად მოჰყვეს. თქვენ გვერდიდან სიამოვნებით უყურეთ, როგორ ერთობა ბავშვი მამის შესწორებით და როგორ კისკისებს.'),
  ('e8ee7ad3-2e99-4bdc-96ae-5bf9e81fcc4a', 'დალაგებას თავი დაანებეთ, სათამაშოები დარჩეს 🎨', 'ოთახის შუაგულში სხვადასხვა ნაჭრისგან დიდი შედევრი შექმნა და მისი ალაგების უფლებას არ გაძლევთ? სისუფთავით შეპყრობილობა გვერდზე გადადეთ. მის შექმნილ ქაოსს ხელი არ ახლოთ — დალაგება ხვალამდეც მოიცდის. სახლი მუზეუმი არ არის.'),
  ('4501063e-24e5-4f32-a723-396adeab0d2a', 'მულტფილმის ამბავს გიყვებათ 📺', 'ნანახ მულტფილმს სრულიად განსხვავებული ლოგიკით გიყვებათ და სერიოზულად გიხსნით, ვინ სად წავიდა? ყურადღებით მოუსმინეთ, თითქოს მისი ყოველი სიტყვის გჯერათ. მიეცით საშუალება, თავი მსოფლიოში ყველაზე ჭკვიანად და ძლიერად იგრძნოს.'),
  ('68a8ce66-c86f-4596-b8d3-b0d44f55a37d', 'მაღაზიაში გაგონილი ის საშინელი „მინდა“ 🛒', 'სალაროს წინ შოკოლადის გამო ყვირის? თქვენს უკან მდგომების მზერის მიუხედავად, არ დანებდეთ. გახსენით საყიდლების სია და უთხარით: „აქ არ წერია, სალარო ამას არ გაატარებს“. გარე ავტორიტეტი მათთვის ყოველთვის უფრო დამაჯერებელია.'),
  ('7a348b09-00b7-46e1-8565-808daca1314c', 'წყლით მთელი დაღლილობის ჩამორეცხვა 🛀', 'ზოგჯერ არაფერი ჭრის და ბავშვი უბრალოდ ყველაფერზე ტირის. ჩასვით თბილი წყლით სავსე აბაზანაში. წყლის მისტიკური, დაძაბულობის მომხსნელი ძალა მყისიერად მოუტანს დიდ სიმშვიდეს როგორც მთელ ოთახს, ისე მის ნერვულ სისტემას. სცადეთ და თავად დარწმუნდებით.'),
  ('1d8c6250-cd7d-4c49-8588-80172d7ce7fd', 'ამინდს ფანჯრიდან ნუ გამოიცნობთ ⛅', 'გარეთ მზეა, მაგრამ ქარიც ქრის? თუ ამინდისა და ჩაცმულობის ხელსაწყო გირჩევთ, ბავშვს რამდენიმე ფენა ჩააცვათ, ენდეთ მას. კართან ყოყმანსა და წუწუნს სჯობს, შესაფერისი სამოსი შეარჩიოთ და მშვიდად გახვიდეთ გარეთ.'),
  ('78e7980c-5a72-49e5-bf40-4486d421427a', 'თავის საჭმელს არ მოგცემთ 🍳', 'თავისი თეფშიდან არაფერს გაძლევთ, მაგრამ დაჟინებით ითხოვს თქვენი თეფშიდან ჭამას? ბავშვები ყოველთვის ბოლომდე ენდობიან მშობლების არჩევანს. ნუ შეეწინააღმდეგებით, სიყვარულით გაუწოდეთ ლუკმა და ამ სასაცილო ეგოიზმზე უბრალოდ გაიღიმეთ.'),
  ('bdc2de1f-725b-4742-942a-3e8bf91a38f3', 'ჩემი ზღაპარი, ჩემი წესები 📖', 'ზღაპრის კითხვისას სიტყვა შეგეშალათ და მაშინვე შეგისწორათ? ესე იგი, უკვე ზეპირად იცის! დახურეთ წიგნი და უთხარით: „მაშინ ამ საღამოს შენ წამიკითხე“. მიეცით მის ფანტაზიას მუშაობის საშუალება, თქვენ კი უბრალოდ წამოწექით და მის ტკბილ ხმას მოუსმინეთ.'),
  ('02c28ca2-9054-4fe0-ba4f-902da3aebfad', 'კოშკის აშენება და შემდეგ დანგრევა 🧱', 'დიდი მონდომებით აშენებს კუბებისგან კოშკს, შემდეგ კი სიცილით, ერთი დარტყმით ანგრევს? თქვენ შეიძლება დაგენანოთ მისი შრომა, მაგრამ ამ დროს ის ფიზიკასა და მიზეზ-შედეგობრივ კავშირებს სწავლობს. ეს ნანგრევები მის ტვინში წარმოქმნილი ახალი კავშირებია, ამიტომ ნუ გაბრაზდებით.'),
  ('380dd8d0-d6f8-457c-b025-9b12f69938f2', 'სად არის ჩემი სადილი? 🥗', 'ბავშვს ბოსტნეულით სავსე განსაკუთრებულ თეფშს უმზადებთ, თავად კი პურს კენკავთ? შეჩერდით! კვების გეგმაში დედებისთვის განკუთვნილი მარტივი, 5 წუთში მოსამზადებელი სალათი მოამზადეთ და ნუ დაგავიწყდებათ, ბოლოს და ბოლოს, ამ სახლის მთავარი ძრავაც (საკუთარი თავიც) დამუხტოთ. თქვენ მნიშვნელოვანი ხართ.'),
  ('44db284c-e980-4095-8376-f1dcb5c24c8a', 'ჩააქრეთ შუქები, რომ ძილი მოვიდეს 🌙', 'დაძინებამდე 1 საათით ადრე ოთახში ყველა მკვეთრი სინათლე და ტელევიზორი გამორთეთ. ოთახის დაბნელებასთან ერთად ბავშვი ავტომატურად დაიწყებს მთქნარებას. ასე შეუმჩნევლად და ბუნებრივად გაააქტიურეთ მელატონინი (ძილის ჰორმონი) და საქმე გაიმარტივეთ.'),
  ('63fa1eaa-e73f-4258-a342-669de7f7f892', 'იატაკზე დაცვენილი მიზიდულობის ძალა 🍝', 'საჭმელს განზრახ იატაკზე აგდებს და შემდეგ თვალს აყოლებს? ნუ უყვირებთ — სინამდვილეში თქვენს გაღიზიანებას კი არ ცდილობს, არამედ მიზიდულობის ძალას ამოწმებს. მშვიდად აიღეთ თეფში მის წინიდან, ჭკუის დარიგებას კი მერეც მოასწრებთ.'),
  ('6e8cabf6-04bc-4e0f-a26d-cdeb494389a5', 'ბეტმენი დამიძახე! 🦇', 'დილით გაიღვიძა, საკუთარ სახელზე უარი თქვა და მოითხოვს, სხვა სახელით მიმართოთ? აჰყევით! 5 წუთით უთხარით: „ინებე, ბეტმენ, ფაფა ჭამე“ და ოთახში დაძაბულობა სახალისო სცენად აქციეთ.'),
  ('b81a0aff-ac53-43cf-bdca-b8bf4192300e', 'პიჟამის რეზინის პრობლემა 👖', 'ყვირის, რომ პიჟამა უჭერს, თუმცა სინამდვილეში ტანზე ძლივს უჩერდება? ეს სენსორული მგრძნობელობის გამოვლინებაა. უთხარით: „მოიცადე, ჯადოსნურ შელოცვას წავიკითხავ და გაფართოვდება“, შემდეგ კი ვითომ პიჟამა გაწელეთ. ის ამას დაიჯერებს!'),
  ('070422be-d317-4a23-a559-6432c6ae63ed', 'თვალებს თუ დავხუჭავ, გავქრები 👀', 'ცდილობს, თვალები არ დაახამხამოს და ცრემლებამდე უძლებს? ბავშვის გონება ზოგჯერ აუხსნელ შიშებს იგონებს. უთხარით: „აი, მე დავხუჭე თვალები და ისევ აქ ვარ“ და ეს უჩვეულო შიში თამაშად აქციეთ.'),
  ('652ec194-fa0e-4ca8-ab49-626452c474ad', 'არ შემეხო, მცხელა 🛑', 'მოულოდნელად უარი თქვა თქვენთან ჩახუტებაზე? ნუ გეწყინებათ! ის საკუთარ პირად საზღვრებს ამოწმებს და სწავლობს, რომ მისი სხეული მხოლოდ მას ეკუთვნის. ეს დამოუკიდებლობის ნიშანია — გვერდიდან ამაყად უყურეთ.'),
  ('c7f18643-0c26-48a6-bc85-4480566ce781', 'ძილი სავარძლის ქვეშ 🛋️', 'საწოლზე უარი თქვა, სავარძლის ქვეშ მოიკუნტა და დაიძინა? ძალით ნუ გამოიყვანთ და ნუ გააღვიძებთ. მიეცით საშუალება, განსხვავებულ და დაცულ ადგილას ძილით დატკბეს, თქვენ კი დაისვენეთ.'),
  ('1fe87964-746d-4cf2-a7f3-21730045a9ae', 'რატომ არის ფაფა ცხელი? 🥣', 'თუ ცხელი არ იქნება, არ შეჭამს, ახლა კი იმის გამო ტირის, რომ ცხელია? გამოუვალი მდგომარეობაა! ფაფაში განზრახ ჩააგდეთ ფერადი ყინულის კუბიკი — წამებში მიიპყრობს მის ყურადღებას და დაამშვიდებს.'),
  ('8d0f8dc1-b43d-411f-a7dc-2e0b87cf4d93', 'კარს მიღმა ტირილი 🚪', 'კარს კეტავს, ოთახში მარტო ტირის და თქვენთან ყოფნა არ სურს? ნუ ეცდებით ძალით ჩახუტებას. ზოგჯერ ბავშვებსაც სურთ, საკუთარ ემოციებთან მარტო დარჩნენ — მიეცით დრო და სივრცე.'),
  ('f52f2ceb-159e-4eff-95c6-70eae6ed7217', 'წიგნში დახატულ მგელზე გაბრაზება 🐺', 'წიგნში დახატულ მგელს მუშტებს ურტყამს და საყვედურობს? შესანიშნავი წარმოსახვა აქვს! რეალობის დამახინჯების გარეშე უთხარით: „შენ დამიცავი, ძალიან მამაცი ხარ“ — ასე მის თავდაჯერებულობასაც გააძლიერებთ.'),
  ('3c299611-0f24-405d-b774-857cf09c273e', 'წინდებს თქვენ ნუ ჩამაცმევთ! 🧦', 'ყველაფერს, რასაც თქვენ აკეთებთ, მტკიცედ უარყოფს? შესანიშნავია! ტანსაცმელი დივანზე დადეთ და შეჯიბრება დაიწყეთ: „ვინ ჩაიცვამს პირველი?“ რამდენიმე წამში თავად ჩაიცვამს.'),
  ('3d738e03-bc77-4be0-b44b-95ecf5e6cdb0', 'ფილოსოფია მაგიდის ქვეშ 🤔', 'მაგიდის ქვეშ ძვრება და იქიდან გამოგონილ ამბებს გიყვებათ? მიეცით პატარა ფილოსოფოსს საშუალება, თავის წარმოსახვით სამყაროში დარჩეს, თქვენ კი ეს დრო დასასვენებლად გამოიყენეთ.'),
  ('b5d5bf11-5ce6-464a-892e-f00915b62103', 'საბანი ხმაურობს 🛌', 'თურმე საბნის შრიალის გამო ვერ იძინებს! უცნაური მიზეზების მოფიქრება პიკს აღწევს. მსუბუქი პლედი გადააფარეთ — როცა დაინახავს, რომ ყველაფრის გამოსავალი გაქვთ, დანებდება.'),
  ('553ac831-9d91-4727-b2a6-83bd86e98633', 'ბალიში სწორად არ დევს! 🛏️', 'ტირის, რომ ბალიში მილიმეტრული სიზუსტით გაუსწოროთ? ეს სრულყოფილების ძიებაა. დაემორჩილეთ წესებს, ბალიში ისე გაასწორეთ, თითქოს სახაზავით გაზომეთ, და შუქი მტკიცედ გამორთეთ.'),
  ('895f4c44-bb71-4d9f-917c-8dc75b779cc8', 'სახლში გამეფებული სიჩუმის პანიკა 🚪', 'სახლში მოულოდნელად მეტისმეტად ჩამიჩუმდა? ძებნას დაიწყებთ და მას კარს უკან მეოცნებე მდგომარეობაში იპოვით. ნუ შეშინდებით — ხმაურს გაერიდა და განტვირთვას ცდილობს. მიეცით ამისთვის დრო.'),
  ('fceb9d37-669a-42ac-ae17-36b46f1fa546', 'გატეხილი კრეკერის დარდი 🍪', 'კრეკერი ორად გაიყო და ამის გამო ქვეყანა დაიქცა? უკან ვეღარ შეაწებებთ. უთხარით: „ნახე, ახლა ორი გახდა — ერთი მე, ერთი შენ“, და საქმეში მათემატიკა და გაზიარება ჩართეთ.'),
  ('7871e777-44f4-425d-a10e-dda0547ccfc1', 'ნაყინი სიზმარში დარჩა 🍦', 'სიზმარში ნაყინს ჭამდა და გაბრაზდა, რადგან გააღვიძეთ? სიზმარი და რეალობა ერთმანეთში აერია. გაბრაზებულ პატარას ჩაეხუტეთ და გაუღიმეთ — რეალობაში დაბრუნებას 2 წუთი დასჭირდება.'),
  ('94d22bcb-5e09-49a0-bea6-432b56a92308', 'წყლის ბოთლის ფერი 🚰', 'ღამით წყალი უნდა, მაგრამ წითელი ჭიქით არა? შუაღამისას ნუ დაიწყებთ ლოგიკის ძებნას და ჭკუის სწავლებას. დაუყოვნებლივ გამოუცვალეთ ჭიქა, ენერგია კი დილისა და სიმშვიდისთვის შეინახეთ.'),
  ('c160b0b4-c39a-4e5d-bbc5-111f29e33385', '„ფეხსაცმელში ქვა მაქვს“ ფსიქოზი 👟', 'ფეხსაცმელს 10-ჯერ გახდევინებთ და გამოწმებინებთ, ქვა კი არსადაა! ნაცნობი სცენარია? მოაჩვენეთ, თითქოს პატარა შავი მარცვალი იპოვეთ, უთხარით: „აი, ვიპოვე, გადავრჩით!“ და სეირნობა განაგრძეთ.'),
  ('56bcf6ad-42a4-41b4-a775-ca5dbc61f766', 'აბაზანაში ბანაობის პროტესტი 🛀', 'წყალში ჩასვლა არ უნდა? ჩაუყარეთ სხვადასხვა ფერის ჭურჭელი და პლასტმასის სამზარეულოს ნივთებიც კი. წყალი უცებ საშიში ადგილიდან გასართობ ცენტრად გადაიქცევა.'),
  ('7f7bb774-fd67-46a5-93fe-c0a784ba9885', 'მე მამა ვარ 👔', 'დილით მამის დიდი ფეხსაცმელი ჩაიცვა და სამსახურში წასვლა უნდა? ნუ აჩქარდებით! კარამდე გააცილეთ — როგორც კი ლიფტს დაინახავს, სიცილით უკან დაბრუნდება.'),
  ('dbd02f3e-2d56-4baa-bc3c-93886c747027', '0 დეციბელის სიყვარული 🤫', 'როგორც იქნა, დაიძინა! აპში გახსენით ხმის საზომი და უყურეთ, როგორ ეშვება მაჩვენებელი ეკრანის ყველაზე დაბალ ნიშნულამდე — სრულ სიჩუმემდე. ეს ხილული სიმშვიდე თქვენს დაღლილ ტვინზე ნამდვილი სპასავით იმოქმედებს.'),
  ('1c6686dd-4008-4750-acaf-4155c3330cdd', 'ხემ ფოთოლი ჩამოაგდო 🍂', 'ძირს დაცვენილი ფოთლის გამო ხეზე გაბრაზდა და საყვედურობს? ბუნებასთან ისეთი წრფელი და სასაცილო კავშირი აქვს!'),
  ('806ceb98-90c4-4de6-a42b-37c72e8d03ae', 'ჩემი ჩრდილი ჩემზე წინ მიდის 👻', 'ქუჩაში ტირის, რადგან მისი ჩრდილი მასზე წინ არის? ხელში აიყვანეთ და უთხარით: „ნახე, ჩრდილები გაერთიანდნენ“. ფიზიკის ახსნის ნაცვლად, უბრალოდ უსაფრთხოების განცდა მიეცით.'),
  ('a0789257-db81-493e-9643-abeb1d193c59', 'მამის უცნაური ხუმრობები 🤡', 'ნუ გაბრაზდებით, თუ ძილის წინ მამამ გააცინა და გამოაფხიზლა. ეს მხიარული სიცილი ბავშვს დღის განმავლობაში დაგროვილ სტრესს სრულად მოუხსნის — აცადეთ, ცოტა იხმაურონ.'),
  ('0879e029-e767-44f9-917b-506cde86d1a1', 'კვერცხმა არ იტიროს 🍳', 'კვერცხის გატეხვისას შეეცოდა და აღარ ჭამს? მისი ემპათია უსაზღვროა. სიტუაცია საყვარელი გამონაგონით გადაარჩინეთ — მაგალითად, უთხარით, რომ ახლა კვერცხი მის კუნთებში იცხოვრებს.'),
  ('7338df78-5f1a-4db5-ae07-ccfc779e153a', 'ჩურჩულით თამაში 🤫', 'დაძინება არ უნდა და გარბის? უცებ დაუწიეთ ხმას და ძალიან ჩუმად იჩურჩულეთ. თქვენს გასაგონად ყურადღებით მოსმენა მოუწევს, მისი ტვინი დაიღლება და 5 წუთში ძილს დანებდება.'),
  ('b9a9483f-7511-4f19-847b-4d0786991104', 'სხეულის ძახილი 🩸', 'უმიზეზო გაღიზიანებასა და დაღლილობას ნუ დანებდებით. გადახედეთ მენსტრუაციის ტრეკერს — თქვენი სხეული სიგნალს გაძლევთ. საკუთარი თავის დადანაშაულების ნაცვლად, დაისვენეთ და ჯანსაღი რეცეპტებიდან მაგნიუმით მდიდარი წასახემსებელი მიირთვით.'),
  ('1bf9463f-7457-4983-af0a-2e62627ce701', 'მხოლოდ წითელი საკვები 🍅', 'დღეს ახირებების დღეა! მხოლოდ წითელი საკვები უნდა? გადახედეთ კვების გეგმას, დღეს წითელი პომიდორი და მარწყვი მიეცით და ამ უცნაური სურვილის ასრულების საშუალება მიეცით — ნუ შეეწინააღმდეგებით.'),
  ('73d3b07e-eaa0-4423-b3b3-a6fb8656c01c', 'ჩემი სათამაშო ავად გახდა 🩺', 'დათუნია საავადმყოფოში მოათავსა? თქვენც ავად გახდით! წამოწექით დივანზე და მიეცით საშუალება, 10 წუთის განმავლობაში ვითომ გაგსინჯოთ — ამ საბაბით თქვენი ზურგიც დაისვენებს.'),
  ('ea408c5e-c419-4258-9053-eba96cea541e', 'ჩემთან დაწექი 🫂', 'დაჟინებით გთხოვთ, მის გვერდით დაიძინოთ? ერთი დღით დაარღვიეთ წესები და თქვენც მასთან ერთად დაიძინეთ, თან მისი სურნელი ღრმად შეისუნთქეთ. ეს ორივესთვის სიყვარულის თერაპიაა.'),
  ('7d8bddb7-9260-4872-8287-e9bfde4a91d7', 'ხელოვნურო ინტელექტო, დამეხმარე 🤖', 'ბავშვის დაუსრულებელმა ფილოსოფიურმა კითხვებმა დაგღალათ? მისწერეთ Anacan AI-ს და ის თქვენ ნაცვლად დაუყოვნებლივ მოამზადებს 4 წლის ბავშვისთვის ყველაზე მეცნიერულ, მოთმინებით სავსე და საყვარელ პასუხებს.'),
  ('9135dd5f-177c-4a9d-97a6-1658abd0da9a', 'სარკეში საკუთარი თავი ვერ ვიცანი 🪞', 'სარკეში იყურება, სახის გამომეტყველებას იცვლის და საკუთარ თავზე ბრაზდება? მისი თვითშეგნება და ემოციები ყალიბდება. ჩუმად, გვერდიდან ადევნეთ თვალი მის ამ პატარა წარმოდგენას.'),
  ('a579865a-399f-44c5-a9b0-e44cc032ce14', 'ზღაპრის გმირი მე ვარ! 🪄', 'ჭკვიან ზღაპრებში მთავარი გმირის სახელი პირდაპირ თქვენი ბავშვის სახელით ჩაანაცვლეთ. როდესაც მოისმენს, როგორ იძინებს გმირი სწრაფად და დამჯერად, თავადაც მოინდომებს იმავეს გაკეთებას.'),
  ('2d3b049d-536d-441d-a015-9e7326fee52e', 'სუპერმარკეტის შუაგულში ნუ გაშეშდებით 🛒', 'სუპერმარკეტში შეხვედით და დაგავიწყდათ, რისი ყიდვა გინდოდათ? თუ საყიდლების სიას ციფრულად არ შეინახავთ, იმ ქაოსში ყველაფერი დაგავიწყდებათ. ყოველთვის ენდეთ თქვენს ციფრულ მეხსიერებას.'),
  ('47345c36-90d7-4e89-b816-0332dc1932ef', 'ღამით ვარსკვლავების დათვლა 🌟', 'საძინებლის ჭერს უყურებს და წარმოსახვით ვარსკვლავებს ითვლის? აცადეთ, დაითვალოს. სანამ იმ გამოგონილი ვარსკვლავების რაოდენობა 10-ს მიაღწევს, უკვე ჩათვლემს და ღრმა ძილში გადავა.'),
  ('924a98d3-0af0-4add-81f0-0d94e1af83c6', 'ხელები ფეხებად მექცა 🤸‍♂️', 'ხელებზე სიარულს ცდილობს და ეცემა? შემოქმედებითი მოტორული განვითარება სრული სისწრაფით მიმდინარეობს! სახლში უსაფრთხო ადგილას პატარა დაბრკოლებების ბილიკი მოუწყვეთ, რათა ენერგია დახარჯოს.'),
  ('50f1584c-32c1-44e9-9ef5-89a70a2afc5e', 'მამის ჩუმი შემოსვლა 👨‍🍼', 'ზუსტად მაშინ, როცა ზღაპრის კითხვით ძალაგამოცლილი ხართ, მამა ოთახში ჩუმად შემოდის, ბავშვს ეფერება და განიშნებთ, რომ დაისვენოთ. ეს მშობლობის ყველაზე გუნდური მომენტია.'),
  ('6694bf7a-8c8c-47c1-8991-2a84701c94f1', 'ბანანი სწორად არ გაფცქვენით 🍌', 'საბაბების მეფე! ნამდვილი ალიაქოთი ატყდა, რადგან ბანანი თქვენ გაფცქვენით. მიეცით ახალი ბანანი და აცადეთ, ისე გაფცქვნას, როგორც თავად სურს, თუნდაც შუაზე გადატეხოს — მთავარია, მის დამოუკიდებლობას არაფერი დაემუქროს.'),
  ('9aaf0e76-e78b-442f-afe1-7bb02c660da6', 'პროტესტი: ძალიან ცხელა 🧥', 'ქურთუკს შუა ქუჩაში იხდის და აგდებს, თქვენ კი გეშინიათ, რომ შესცივდება? ნუ შეეწინააღმდეგებით — როცა მართლა შესცივდება, თავად მოვა და მოგთხოვთ. აცადეთ, შედეგი საკუთარ თავზე გამოსცადოს.'),
  ('02ff52cb-13af-47d3-83d9-4e3e21f04d45', 'მე სკამი ვარ 🪑', 'თავს ნივთად წარმოგიდგენთ და გაუნძრევლად დგას? ვითომ მართლა სკამია, ზემოდან სათამაშო დაუდეთ და უთხარით: რა კარგი სკამია. ეს უცნაური როლი ძალიან მოეწონება და მშვიდად დარჩება.'),
  ('50fd969e-9bd4-4e5e-8927-9b3b9067a4be', 'რას მეუბნება საზოგადოება? 💬', 'ფიქრობთ, რომ ყველაფერს არასწორად აკეთებთ? შედით Anacan-ის საზოგადოებაში, წაიკითხეთ სხვა დედების ცელქი და თავნება ბავშვების ისტორიები, ღრმად ჩაისუნთქეთ და მადლიერი იყავით, რომ თქვენი შვილი ასეთია!'),
  ('8d85cb27-805f-4ca6-a6a0-16122a07af20', 'ოთახი სრულად დააბნელეთ 🌙', 'დერეფნიდან შემოპარული სინათლის გამო ვერ იძინებს? სრულყოფილ სიბნელეს ეძებს. კარი მჭიდროდ დახურეთ, ოთახი სრულად დააბნელეთ და აცადეთ მელატონინს, თავისი ბუნებრივი საქმე გააკეთოს და ბავშვი დააძინოს.'),
  ('6a3af8d6-9d3b-434e-ad40-18c53a8e8dfd', 'უხილავი ლაქის დარდი 👕', 'შარვალზე ლაქას ეძებს, მაგრამ იქ არაფერი არ არის? ისევ ეს ვიზუალური აკვიატებები. ვითომ სველი ხელსახოცით გაწმინდეთ და უთხარით, რომ ლაქა გაქრა. ბავშვის ტვინი ილუზიას ძალიან სწრაფად იჯერებს.'),
  ('7da643f9-a304-476b-9165-6028a945c141', 'თქვენ მოშორებით დაჯექით 🛑', 'ითხოვს, რომ მის საწოლთან ახლოს კი არა, მოშორებით, კართან დაჯდეთ? ნუ გეწყინებათ! ეს დამოუკიდებლობისკენ გადადგმული მისი დიდი ნაბიჯია და გულში უნდა გაგიხარდეთ.'),
  ('b72ecf4d-fe3f-4f6b-a417-a52c3a7a15ba', 'ფანჯარასთან მყოფი ჩიტი ჩემია 🐦', 'ეზოში მყოფი ჩიტის სახლში მოყვანა უნდა და ტირის? ბუნებისადმი სიყვარული მასში ნაპირებს გადასცდა. მოუყევით, რომ ჩიტს სახლში დედა ელოდება — ეს პატარა გამონაგონი კრიზისს მყისიერად სიმშვიდით შეცვლის.'),
  ('544fb1ce-862b-49f6-8e2e-6b2192929ac3', 'ღამის შიშები იწყება 👻', 'საწოლის ქვეშ დამალული ურჩხულის ეშინია? ცარიელი სპრეის ბოთლი წყლით შეავსეთ და ოთახში შეასხურეთ, თითქოს ეს ურჩხულების გასაქრობი ჯადოსნური საშუალებაა. შიში წამებში გაქრება.'),
  ('b51cc09c-00f6-4b63-945d-9cfceecedfb2', 'კბილები თითმა გამიხეხოს 🪥', 'კბილის ჯაგრისზე უარს ამბობს და აუცილებლად თითით უნდა კბილების გახეხვა? ნუ შეეწინააღმდეგებით — ამის გაკეთება სუფთა თითითაც შეიძლება, რომელზეც ცოტაოდენი კბილის პასტაა წასმული. ნუ გაართულებთ ამ ამბავს.'),
  ('e403fe31-012f-4f6b-80cb-45dd719c9f06', 'ფარულად მირთმეული შოკოლადის სიამოვნება 🍫', 'სანამ ბავშვი ტელევიზორს უყურებს, სამზარეულოში მისგან მალულად შოკოლადს მიირთმევთ? შეგერგოთ! ამდენი კრიზისის გასაძლებად ეს თქვენი ყველაზე ბუნებრივი ენერგიის წყაროა — თავს ნუ დაიდანაშაულებთ.'),
  ('2d98107a-3331-4f7f-8930-8f762e325d02', 'უკუღმა ჩაცმული მაისურის თავისუფლება 👕', 'მაისური უკუღმა ჩაიცვა და ამაყად დადის? ნუ გაუსწორებთ! მისი თავდაჯერება იმდენად მაღალია, რომ უბრალოდ გვერდიდან უყურეთ და იამაყეთ ამ თავისუფალი სულის მქონე მომავალი ლიდერით.'),
  ('c5aa519b-baae-498e-a13b-bdf83115f0c9', 'ჩუმი მზერით საუბარი 🥂', 'ბავშვს ჩაეძინა, თქვენ და თქვენი პარტნიორი კი დივანზე სხედხართ და უხმოდ უყურებთ ერთმანეთს. არაფერს ამბობთ. სინამდვილეში ეს სიჩუმე ყველაზე რომანტიკული გზაა იმის სათქმელად, რომ ამასაც გაუმკლავდით.'),
  ('eaade7fe-4846-47fa-9bc5-4c49360a0a4a', 'ქარმა მიბიძგა 💨', 'გარეთ ქარზე გაბრაზდა და მისთვის დარტყმა უნდა? ამინდისა და ჩაცმის ხელსაწყო წინასწარ რომ შეგემოწმებინათ, შეიძლება სახლიდან არც კი გასულიყავით. ახლა უბრალოდ გაიცინეთ ამ კომედიაზე და სახლისკენ გაიქეცით.'),
  ('77606aaa-e2aa-442d-992d-f4dce779d9e5', 'ხელოვნება იატაკზე 🎨', 'ოთახის შუაგულში მშრალი მაკარონით ნახატი შექმნა და ამაყად გიყურებთ? დალაგება დაივიწყეთ და გაუღიმეთ.'),
  ('92c59586-e756-4176-87f0-6ee0836bd1f7', 'მამის ძილის მომგვრელი ზღაპარი 📖', 'ხმა დაგეღალათ და ზღაპრის წაკითხვა აღარ გინდათ? ჯერი მამას დაუთმეთ. მისი განსხვავებული, ბოხი ხმა და მის მიერ მოგონილი აბსურდული დეტალები ბავშვს უფრო სწრაფად მოჰგვრის ძილს.'),
  ('dc97d51e-f4af-4633-84e4-fbe0fbe9e15a', 'თმა მტკენს 🪮', 'თმის დავარცხნა სიკვდილის ტოლფასია? სპრეით ოდნავ დაუსველეთ, მისი ყურადღება კი სარკეში თქვენ მიერ გაკეთებულ სასაცილო სახეებზე გადაიტანეთ. როგორც კი ყურადღება გაეფანტება, სწრაფად დავარცხნეთ.'),
  ('1752e8bc-24e4-4f1b-97e5-c557a4522bda', 'სად გაქრა ცა? ☁️', 'ნისლიან ამინდში მისმა მოულოდნელმა ფილოსოფიურმა კითხვამ დაგაბნიათ? უთხარით, რომ ღრუბლებმა ცას საბანი გადააფარეს, რათა არ შესცივდეს — მისი გონება ჯერ არ არის მზად მეცნიერული ახსნისთვის, მას უბრალოდ ზღაპარი სურს.'),
  ('2d5bfd88-008f-4b96-a72a-390cdfe7c90d', 'მაღაზიაში სირბილი 🛒', 'სალაროსთან მოულოდნელად გარბის და თაროებს უკან იმალება? საყიდლების სია ტელეფონში შეინახეთ, რათა ასეთ პანიკურ მომენტებში არ დაგავიწყდეთ, რა არ გიყიდიათ, და შინ ხელცარიელი არ დაბრუნდეთ.'),
  ('5c94e9c6-00cb-4c58-b265-f248e6c3e544', 'ჩურჩულის თამაში 🤫', 'ყვირილით დარბის და დაძინება არ სურს? უცებ ხმა ძალიან დაუწიეთ და ჩურჩულით დაიწყეთ საუბარი. თქვენს გასაგონად ყურადღებას მოიკრებს და ძილიც მოერევა.'),
  ('22c6ff37-5069-489b-9d49-2a97d14d2e2e', 'იდეალური დედა არ ვარ 🛑', 'დღეს ყველაფერი აირია და იყვირეთ? თავს ნუ გაიკიცხავთ. განწყობის დღიურში უბრალოდ ჩაწერეთ: დღეს ცუდი დღე მქონდა, მაგრამ კარგი დედა ვარ და ხვალ ისევ ვეცდები.'),
  ('39a82edc-fce3-4cb5-8ef7-be6b2f9a1122', 'ზღაპარი წვიმის ხმით 🌧️', 'ხმა აღარ გაქვთ და ზღაპრის წაკითხვის ძალაც არ გყოფნით? „ჭკვიან ზღაპრებში“ ფონად მხოლოდ წვიმისა და ტყის ხმები ჩართეთ. ბუნების ამ სიმშვიდეს ზოგჯერ საუკეთესო ზღაპარზეც უფრო სწრაფად მოაქვს ძილი.'),
  ('69d7d720-ce5e-441e-ac6e-b3151e6557c4', 'ხელს ნუ მომკიდებ! 🚶‍♂️', 'გზაში ხელს გიშვებთ და დამოუკიდებლად სიარული სურს? თუ უსაფრთხო ადგილას ხართ, მიეცით საშუალება, საკუთარი დამოუკიდებლობა მოსინჯოს, თქვენ კი უბრალოდ ორი ნაბიჯის მოშორებით მიჰყევით და სიამაყით უყურეთ.'),
  ('1b495b8d-2c5f-47f5-aeda-e199006766ac', 'ჩემი სხეული მე აღარ მეკუთვნის 🔋', 'მთელი დღე თქვენზე ცოცვისგან სხეული დაგიბუჟდათ? 5 წუთით ბავშვი ოთახში მარტო დატოვეთ, უბრალოდ კარი დახურეთ, თვალები დახუჭეთ და ღრმად ჩაისუნთქეთ. ძალების აღდგენა გჭირდებათ.'),
  ('81591bb3-d8f2-475d-b7fc-1bd47693b91f', 'ბავშვს ნუ მეძახი! 😤', 'გეუბნებათ, რომ უკვე დიდია და ოთახში საკუთარ წესებს გიწესებთ? ის ცდილობს დაამტკიცოს, რომ უკვე გაიზარდა. მიმართეთ როგორც დიდს — „კარგი, ახალგაზრდა ქალბატონო/ბატონო“ — და მისი პატივისცემა დაიმსახურეთ.'),
  ('a65f1e7a-ca07-4462-bac0-1293b0e5896c', 'ჩემი ციფრული თერაპია 🤫', 'ყველას სძინავს, მაგრამ თქვენს გონებაში ჯერ კიდევ ხმაურია? ჩართეთ ხმის დონის საზომი. სცადეთ — ეკრანზე „0 დეციბელის“ დანახვა შეიძლება ფსიქოლოგთან სეანსზე მეტადაც კი დაგამშვიდოთ.'),
  ('25ef7ba4-1698-4dbc-9412-9bb568472d80', 'სათამაშოების დაძინება 🧸', 'თავად არ იძინებს, მაგრამ სათამაშოებს სათითაოდ აწვენს და საბანს აფარებს? სინამდვილეში, ეს როლური თამაში მას ნელ-ნელა და ფსიქოლოგიურად საკუთარი ძილისთვის ამზადებს — ნუ ჩაერევით.'),
  ('7626d265-88f4-40f1-a79c-e9d0f1238d73', 'კარი თქვენ რატომ გააღეთ? 🚪', 'ტირის, რადგან კარი თქვენ გააღეთ, ისევ გაკეტინებთ და თავად უნდა გააღოს? დაუთმეთ ეს 1 წუთი და მშვიდობიანად აიცილეთ თავიდან სახლში მოსალოდნელი 20-წუთიანი აჯანყება და ყვირილი.'),
  ('a5284401-af40-43a4-aa11-663792a88d21', 'მხოლოდ მწვანე! 🥦', 'თეფშზე მხოლოდ მწვანე საკვებს ეძებს? გადახედეთ კვების გეგმას, ისწავლეთ, როგორ მოამზადოთ მწვანილისგან საყვარელი ფორმის მწვანე ბოსტნეულის ბურთულები და დააკმაყოფილეთ ეს უცნაური აკვიატება.'),
  ('27e63f29-b167-40b2-aa6b-8ed0d0329ca3', 'პურის ქერქები მტერია 🍞', 'შუაგულს ჭამს, ქერქებს კი მტკიცედ გვერდზე დებს? ნუ შეებრძოლებით ქერქებს. პური ცხოველების ფორმის საჭრელებით გამოჭერით, უქერქო ფიგურები შექმენით და მიეცით საშუალება, ამ კულინარიული დიზაინით დატკბეს.'),
  ('7c97a838-1745-4335-a86c-2bf011bb9f3b', 'სახლიდან გასვლა არ უნდა ⛅', 'ოთხ კედელში ყოფნა გახრჩობთ, ის კი ტირის და გარეთ გასვლა არ უნდა? ენდეთ ამინდისა და ჩაცმულობის ხელსაწყოს და მაინც გაიყვანეთ გარეთ. სუფთა ჰაერს როგორც კი ჩაისუნთქავს, სახლში დაგროვილი მთელი აგრესია წამებში გაუქრება.'),
  ('f3fa598e-4bec-4396-a5cb-220c0c856d23', 'პიჟამით ჭიდაობა მამასთან 🤼‍♂️', 'დაძინება არ უნდა? მამამ ვითომ ჭიდაობაში კედელთან დაამარცხოს. ოფლთან ერთად დარჩენილ ენერგიასაც მთლიანად დახარჯავს და საწოლისკენ სირბილით გაეშურება.'),
  ('2ab3a16c-8538-4df6-b8df-c031bc53d6c7', 'საზოგადოებისგან ძალის მიღება 💬', 'როცა მოთმინება გეწურებათ, Anacan-ის საზოგადოებას შეუერთდით. როცა დაინახავთ, რომ იქ მყოფი დედებიც ზუსტად ასეთივე ქაოსს უმკლავდებიან, დიდ შვებას იგრძნობთ და მიხვდებით, რომ მარტო არ ხართ.'),
  ('5a8f1d52-e3d3-4c7e-b491-d2552a236831', 'ესეც შევძელით! 🚀', 'სახლს სძინავს. მომდევნო თვის ახალი ქაოსისთვის მზად ხართ — ამ საქმის ნამდვილი ოსტატი ხართ. ჩააქრეთ შუქი და მადლობა გადაუხადეთ საკუთარ თავს ყველა იმ პატარა სასწაულისთვის, რომელიც დღეს შექმენით.'),
  ('83732257-57c8-43f0-99f6-cb1c1583874a', 'ეს ჩრდილი ჩემია 👻', 'საკუთარი ჩრდილი დაისაკუთრა, ელაპარაკება და მითითებებსაც აძლევს? მის წარმოსახვას საზღვრები არ აქვს.'),
  ('37af8066-a97d-4233-891d-9eb3a99e296b', 'საიდუმლო შეტევა სიაზე 🛒', 'მაღაზიაში წასვლამდე აპში საყიდლების სია გახსენით და აღმოაჩინეთ, რომ სიაში 5 ცალი შოკოლადი წერია? დიახ, თქვენმა ბავშვმა უკვე დიდი ხანია ისწავლა, როგორ შეაღწიოს თქვენს ტელეფონში და რეალური სამყარო ციფრულში გადაიტანოს.'),
  ('709311bc-b001-46b6-bc4d-6ad222fa6ef4', 'მთლიანი ვაშლის დრამა 🍏', 'ვაშლი ნაჭრებად დაჭერით და ოთახში ერთი ამბავი ატყდა? „მე მთლიანი მინდოდა!“ — ამბობს და ტირის. ლოგიკას ნუ ეძებთ. ნაჭრები ერთმანეთს მიადეთ, უთხარით: „აი, ისევ გავამთლიანე“ და ამ უაზრო დრამას დიპლომატიურად დააღწიეთ თავი.'),
  ('8b61be71-cfc2-42cd-ad4f-a58585ff674e', 'მამის გამოგონილი გმირი 🦸‍♂️', 'ხმა აღარ გაქვთ და წიგნის წასაკითხად ძალაც არ გყოფნით? საქმე მამას გადააბარეთ. დაე, მამამ მოიგონოს აბსურდული და ალოგიკური ამბავი, რომლის მთავარი გმირიც თავად ბავშვი იქნება. თქვენ კი უბრალოდ დივანზე წამოწექით და ოთახიდან გამომავალი სიცილი მოისმინეთ.'),
  ('167cc8b8-5aaf-4f2a-8be0-934651da76be', 'უკუღმა ჩაცმული წინდის სიჯიუტე 🧦', 'წინდა ისე ჩაიცვა, რომ ქუსლი ტერფის ზემოთ მოექცა და გასწორების უფლებას არაფრით გაძლევთ? დატოვეთ, როგორც არის. მისი ამაყი გამომეტყველება — „მე ეს შევძელი!“ — მილიონჯერ უფრო ძვირფასია, ვიდრე სწორად ჩაცმული წინდა.'),
  ('4081d285-b739-4c34-a223-ae2922366de7', '„კიდევ ერთი ყლუპი წყლის“ საბაბი 💧', 'როგორც კი თითქმის დაიძინებს, უცებ წამოხტება საწოლიდან და ამბობს: „ძალიან მწყურია“? მიზანი წყალი კი არა, თქვენთან კიდევ ცოტა დროის გატარებაა. საწოლთან წინასწარ დაუდეთ წყლით სავსე, დაღვრისგან დაცული ბოთლი და ამ ცნობილ მანიპულაციას თავიდანვე გადაუღობეთ გზა.'),
  ('7b85f446-78f0-4be5-9cc1-c336a25ea658', 'დავიღალე, მაგრამ არ ვამბობ 📝', 'ვერავინ ამჩნევს, დღეს რამდენი ინერვიულეთ, ყველასთვის გაღიმება კი უკვე გახრჩობთ? გახსენით განწყობის დღიური. მთელი დაგროვილი ბრაზი და სიმწარე ეკრანზე გადმოიტანეთ. ემოციების ციფრულად ამონთხევა ფსიქოლოგზე სწრაფად მოგარჩენთ.'),
  ('4c512e27-6d0e-434b-b3b6-e7db7541662c', 'ასფალტზე გავლებული ხაზები კანონია 🛣️', 'ქუჩაში სიარულისას ქვებს შორის ხაზებზე ფეხის დასადგმელად უცნაურ მოძრაობებს აკეთებს? ამ დროს მსხვილი მოტორიკა და ყურადღება ერთდროულად მუშაობს. ნუ ააჩქარებთ, ხელი ჩაჰკიდეთ და თქვენც გადაახტით ამ ხაზებს.'),
  ('685cde5b-1133-4e8c-aa85-09d262ad4afb', 'წყლის ჩასადინებელი ხვრელის შიში 🛁', 'აბაზანიდან გამოსვლისას ეშინია ხვრელის, რომელშიც წყალი ჩაედინება? მისი წარმოსახვა ზოგჯერ საოცრად უჩვეულოდ მუშაობს. იქ სათამაშო პლასტმასის გემი დადეთ და უთხარით: შეხედე, ეს მცველია, არაფერს ჩაითრევს. შიშს მაშინვე თამაში ჩაანაცვლებს.'),
  ('e7c8a731-9f6f-40fe-bb36-efba9869846f', 'დილის 6 საათზე დაწყებული კონცერტი 🎤', 'თვალების გახელისთანავე მთელი ხმით თავის მოგონილ სიმღერას მღერის? ნუ ჩაახშობთ მის ამ გიჟურ ენერგიას სიტყვებით: ჩუმად, მეზობლებს გააღვიძებ. თქვენც აჰყევით. ბავშვი, რომელიც დილას სიმღერით იწყებს, მთელი დღის განმავლობაში ნაკლებად აგრესიულია.'),
  ('7dbcfeb4-6b0f-40e0-a421-e16781d15f4a', 'სიჩუმის 0-დეციბელიანი ცეკვა 🤫', 'როგორც იქნა, ოთახში ბნელა და ბავშვს სძინავს. სახლში ისეთი სიჩუმეა, რომ ყურებიც კი გეჭედებათ. აპში ხმის საზომი გახსენით. ეკრანზე 0 დეციბელამდე ჩამოსული მაჩვენებლის ყურება ხმაურისგან გადაღლილი თქვენი ტვინისთვის ნამდვილი ციფრული მასაჟია.'),
  ('80129e61-cd59-4c54-9d5e-e6507c3811da', 'ჩემი სათამაშო თქვენზე გაბრაზდა 🧸', 'მას შემდეგ, რაც დაუყვირეთ, მოვიდა და გითხრათ: ჩემი დათუნია თქვენზე გაბრაზდაო? საკუთარ გრძნობებს ნივთებს მიაწერს და ასე გადმოგცემთ. დათუნიას ძალიან სერიოზულად მოუბოდიშეთ და ჩაეხუტეთ. ნახავთ, როგორ დამშვიდდება ბავშვი.'),
  ('e7d3487a-45d4-44a3-bf97-c34082190904', 'ჩაიდან ორთქლი რატომ ამოდის? ☕', 'თქვენი ფინჯნიდან ამოსულ ორთქლს უყურებს, ახსნას გთხოვთ ან ეშინია? მეცნიერულად ახსნა გიჭირთ? Anacan AI-ს სთხოვეთ 4 წლის ბავშვისთვის გასაგები, ფილოსოფიური და საყვარელი ახსნა: ის მიფრინავს, რათა ღრუბლებს შეუერთდეს.'),
  ('1bdc66c1-4583-42f2-a981-0ba814be491d', 'ქურთუკის ომი 🧥', 'გარეთ მზეა, მაგრამ ბავშვს ქურთუკის ჩაცმა არ უნდა. ფანჯრიდან გახედვას ნუ ენდობით — აჩვენეთ ამინდისა და ჩაცმულობის ხელსაწყოში მითითებული რეალური ტემპერატურა და ფენებად ჩაცმული ბავშვის სურათი. ჩაიტვირთეთ ეს წესი ტელეფონში.'),
  ('8b4c98d1-27b9-49ae-b0a2-f93f650bdd45', 'ჩიტმა რატომ არ შემომხედა? 🐦', 'პარკში მტრედი გაფრინდა და ბავშვი ამის გამო გულამოსკვნით ატირდა? ამ სიტუაციაში ლოგიკას ნუ ეძებთ. მისთვის ეს მართლაც დიდი იმედგაცრუებაა. სიყვარულით აღიარეთ მისი გრძნობა და უთხარით: „მას ძალიან მოენატრები“.'),
  ('cbcac766-bab8-4183-80ab-82267106b24d', 'ზღაპარში ჩემი სახელი იყოს 🪄', 'კლასიკური წიგნების პერსონაჟები მობეზრდა? ჭკვიან ზღაპრებში მთავარი გმირის სახელი ბავშვის სახელით შეცვალეთ. როცა მოისმენს, თავად როგორ გაბედულად დაიძინა, ოთახში ყოველგვარი პროტესტის გარეშე მიეცემა ძილს.'),
  ('83683b1a-77a6-45bf-bf9e-6b7ae022a7e3', 'დღეს მე მანქანა ვარ 🚗', 'დილით გეუბნებათ: „მე ბავშვი კი არა, მანქანა ვარ“? წესების დაწესებას ნუ დაიწყებთ. უთხარით: „მაშინ მოდი, საწვავით — ფაფით — აგავსოთ, რომ სწრაფად ირბინო“. ასეთი სახალისო როლური თამაშები ყვირილზე ბევრად მარტივია.'),
  ('87824b1c-6e01-4ebd-84b1-4bb784a464e0', 'ქვიშისგან გამომცხვარი ტორტი 🏖️', 'პარკში წყალი და მიწა აურია, ტანსაცმელი ტალახით დაისვარა და თქვენთვის ტორტი მოამზადა? სისუფთავეზე ნუ იდარდებთ. ეს ნატიფ მოტორიკასა და შემოქმედებით უნარებს ავითარებს.'),
  ('bc3aaf13-535b-4b7d-bc70-b3e5a5a87b99', 'შეჯიბრი თვალის დაუხამხამებლად 👀', 'დაძინება არ უნდა და განზრახ თვალებგაფართოებული გიყურებთ? ითამაშეთ თამაში: „ვინც პირველი დახუჭავს თვალებს, წააგებს“. თვალები აუწყლიანდება, თავისთავად დაიღლება და 2 წუთში ავტომატურად დაეხუჭება. სცადეთ და თავად ნახავთ!'),
  ('20b06f39-a2df-4c97-aab5-39753c3a8a8f', 'საწოლში დამალული სათამაშოები 🧸', 'საწოლში ჩაწოლისას მის ქვეშ 3 მაგარი სათამაშო მანქანა იპოვეთ? მათ დარაჯად უდგას და ისე იძინებს. ნუ ინერვიულებთ — დაძინებიდან 10 წუთის შემდეგ ჩუმად გამოაცალეთ ეს მჩხვლეტავი ნივთები, რათა კომფორტულად ეძინოს.'),
  ('29e9913a-41eb-42ab-96c8-cc6c3af590fd', 'ჩუმი ნუგეში საზოგადოებაში 💬', 'ძალიან დაიღალეთ და ვინმესთვის გულის გადაშლაც კი არ გინდათ? შეუერთდით Anacan-ის საზოგადოებას და უბრალოდ მკითხველად დარჩით. იმის ნახვა, თუ როგორ უმკლავდებიან სხვა დედები ზუსტად ასეთივე აბსურდულ კრიზისებს, თქვენთვის ყველაზე ძლიერი, უხმო ნუგეში იქნება.'),
  ('bab27593-bee1-487c-a8d8-1d9f5c333dc2', 'არასწორი კოვზის კრიზისი 🥄', 'წვნიანი დიდი კოვზით მიეცით და კინაღამ რევოლუცია მოაწყო? დაახლოებით 4 წლის ასაკში, თუნდაც საჭმელი იგივე იყოს, ბავშვის ლოგიკით ჭურჭლის ფიზიკური ზომა მის გემოს ცვლის. ნუ შეეკამათებით — მაშინვე შეუცვალეთ კოვზი და ენერგია დაზოგეთ.'),
  ('6072f87e-09eb-4773-9647-75d90ac37029', 'დივანზე ჩუმად ჩამოჯდომა 🥂', 'ბავშვს ჩაეძინა, სახლი დალაგებულია. თქვენს პარტნიორთან ერთად დივანზე გვერდიგვერდ დაჯექით და ტელევიზორიც კი არ ჩართოთ. უბრალოდ ერთმანეთს ისეთი მზერა ესროლეთ, რომელიც ამბობს: „ესეც შევძელით, გადავრჩით“. დამიჯერეთ, მშობლობის ყველაზე რომანტიკული და ნამდვილი მომენტი სწორედ ეს არის.'),
  ('a980ec72-f146-48fe-a3b4-28ba8f8a9398', 'მწვანე ფერის სიყვარული 🥦', 'თეფშზე მხოლოდ მწვანე საკვებს ეძებს და სხვა ფერებს გვერდზე სწევს? გაეცანით ჯანსაღ რეცეპტებს და ისწავლეთ, როგორ მოამზადოთ მწვანილისგან საყვარელი ფორმის მწვანე ბოსტნეულის ბურთულები.'),
  ('e2f4da77-db67-4ed8-9acb-d0a907894c73', 'კარი თქვენ რატომ დახურეთ? 🚪', 'სახლიდან გასვლისას კარი თქვენ დახურეთ, ამიტომ ყვირილი ატეხა და ხელახლა გაგაღებინათ? კონტროლის განცდა მისთვის ერთ-ერთი ყველაზე მნიშვნელოვანი საჭიროებაა. სჯობს, ამისთვის 1 წუთი დაკარგოთ, მაგრამ ქუჩაში 30-წუთიანი ტირილის კრიზისი თავიდან აიცილოთ.'),
  ('2feec242-97b8-4207-9200-a80856e8121d', 'ვინ არის ის ბავშვი სარკეში? 🪞', 'სარკის წინ დგას, საკუთარ თავს წარბებს უჭმუხნის და გაბრაზებულ, უცნაურ მიმიკებს აკეთებს? ის აღმოაჩენს, როგორ აისახება ემოციები სახეზე. უხმოდ, გვერდიდან დააკვირდით და დატკბით ამ მინიატიურული თეატრის მსახიობის რეპეტიციით.'),
  ('70b38ef9-bf37-4439-be26-d9a4e96ca1a7', 'ჩააქრეთ შუქი და იპოვეთ ჩრდილი 🔦', 'სიბნელის ეშინია და დასაძინებლად არ მიდის? ოთახში შუქი მთლიანად ჩააქრეთ და პატარა ფანარი აანთეთ. ხელებით კედელზე ძაღლისა და ფრინველების ჩრდილები გამოსახეთ. საშიში სიბნელე მისთვის თეატრად აქციეთ და დაძინებაც გაუადვილდება.'),
  ('d5008830-7d32-4abc-8ae0-128b13041be3', 'კედელზე დახატული შედევრი 🖍️', 'რამდენიმეწამიანი სიჩუმის შემდეგ აღმოაჩინეთ, რომ ბავშვი კედელზე ფლომასტერით ხელოვნების ნიმუშს ქმნის? ღრმად ჩაისუნთქეთ. მისი ნატიფი მოტორიკა ვითარდება, კედელი კი მაინც გაიწმინდება. სანამ ამ შედევრს წაშლით, აუცილებლად გადაუღეთ ფოტო.'),
  ('56af6282-7207-49e4-b888-b735c8e4f791', 'მამას ზურგზე ცხენობანა 🐴', 'ენერგია ბოლომდე ვერ დახარჯა და დაძინებას ეწინააღმდეგება? მამას დახმარება სთხოვეთ. როცა მამა ბავშვს ზურგზე შეისვამს და ცხენივით დაატარებს, ოთახი სიცილით ივსება, დაგროვილი ფიზიკური დაძაბულობა კი ოფლის გამოყოფასთან ერთად წამებში ქრება.'),
  ('65ce993d-a029-4b05-8c87-ec0d7b807a64', 'ტუალეტში 5-წუთიანი გაქცევა 🚪', 'ხმაური ტვინს გიბურღავთ და გინდათ, ყველას უყვიროთ? ბავშვი უსაფრთხო ადგილას დატოვეთ, ტუალეტში შედით და კარი დაკეტეთ. უბრალოდ 5 წუთი უყურეთ კედელს და არაფერი აკეთოთ. ეს ხანმოკლე სიჩუმე კვლავ ნორმალურ ადამიანად გაქცევთ.'),
  ('a5a3dc3f-2634-4d40-9509-dbe4066d8a5a', 'ფაფა ზედმეტად მრგვალია 🥣', 'საჭმლის ფორმაზე გაბრაზდა და ჭამაზე უარს ამბობს? ლოგიკის ძიების გარეშე, უბრალოდ კოვზით მოურიეთ ფაფას და უთხარით: „აი, გავასწორე“. ილუზიის ხელოვნება დედობისას ყოველთვის გამოგადგებათ.'),
  ('9272ca67-0e34-4d81-b7cc-a00d43d2c52b', 'უმიზეზო ცრემლები 😭', 'პარკიდან დაბრუნებისას გზაზე ქვას ფეხი ვერ დაარტყა და ამის გამო ქვეყანა დაიქცა? აქ ლოგიკა არაფერ შუაშია — უბრალოდ დაიღალა. ნუ შეეკამათებით, ჩაეხუტეთ, აღიარეთ მისი გრძნობა და ყურადღება სხვა რამეზე გადაატანინეთ.'),
  ('bf4ef479-e79f-4536-adc8-2a33fe4bb476', 'ჩურჩულით მოყოლილი ზღაპრის საიდუმლოებები 🤫', 'საწოლიდან თავის დასაღწევად მიზეზებს იგონებს? ხმას ბოლომდე დაუწიეთ და მხოლოდ ჩურჩულით დაიწყეთ ლაპარაკი. თქვენს გასაგებად იძულებული იქნება, მთელი ყურადღება მოიკრიბოს, მისი გონება კი მალე ძილისთვის განეწყობა.'),
  ('dd593bef-61fd-4b06-ae2c-84f70da4ad5c', 'რატომ გამაჩუმე? 🎶', 'ფონად ჩართულ საბავშვო სიმღერას ღიღინით აჰყევით და მაშინვე დაგიყვირათ: „შენ არ იმღერო!“? ამ ოთახში ერთადერთი სოლისტი ისაა, თქვენი ვოკალური მცდელობები კი მის სცენას ავიწროებს. ნუ გეწყინებათ, სცენა ამ პატარა ეგოისტს დაუთმეთ.'),
  ('0e5c772e-ad3b-4b0c-99e1-704d879eb64e', 'ტანსაცმელს თავად ირჩევს 👗', 'წითელი შარვალი, სპორტული ფეხსაცმელი და ზამთრის ქუდი... თან დაჟინებით ამბობს, რომ პარკში ასე წავა. ნუ იდარდებთ იმაზე, რას იტყვის ხალხი. მიეცით საშუალება, თავისი არჩევანით გავიდეს — მისთვის ეს თავისუფლება ესთეტიკაზე მნიშვნელოვანია.'),
  ('1c02e319-6351-4dbf-93b0-072c9cbcabab', 'ძილის შეთანხმება ტაიმერით ⏱️', 'როგორც კი ძილის დრო დგება, მოულოდნელად სწყურდება ან კედელს ემშვიდობება? დააყენეთ ტაიმერი. შემოიღეთ წესი: როცა ზარი დარეკავს, ყველა იძინებს. გარედან დაწესებული წესის დამორჩილება ბავშვებს ყოველთვის უფრო უადვილდებათ.'),
  ('42320a1e-019f-4b03-8860-b2a7ebec874e', 'მთვარე ჯერ რატომ არ წასულა? 🌙', 'დილით ცაზე მთვარე დაინახა და გკითხათ: „მთვარეს რატომ არ დაუძინია?“ ნუ გადაუტვირთავთ გონებას სამეცნიერო ტერმინებით. გახსენით Anacan AI — ის ამ ასაკისთვის შესაფერის ტკბილ ასტრონომიულ ზღაპარს იპოვის. წაუკითხეთ და მისი ცნობისმოყვარეობა დააკმაყოფილეთ.'),
  ('37e1f058-26f3-4681-8381-3414a60ed5c9', 'პურის მხოლოდ კიდეებს ჭამს 🍞', 'პურის მხოლოდ ქერქს ჭამს და შუაგულს ტოვებს? საკვების ჭამის უცნაური წესები თქვენთვის ნაცნობია. ქერქთან ბრძოლას ნუ დაიწყებთ. კვების გეგმაში შეიტყვეთ, როგორ დაჭრათ პური ფორმებით და განსხვავებული კიდეები შეუქმნათ.'),
  ('d40bcca0-d355-4520-b51b-bece0b2b8663', 'სიბნელე მელატონინისთვის 🌌', 'იმისთვის, რომ ბავშვმა უფრო სწრაფად დაიძინოს, დაძინებამდე 1 საათით ადრე ოთახში ყველა ტელევიზორისა და ტელეფონის ეკრანი გამორთეთ. მელატონინი (ძილის ჰორმონი) სწრაფად მხოლოდ ბნელ გარემოში გამომუშავდება — ენდეთ ბუნებრივ პროცესს.'),
  ('eb8ec98b-d143-483a-b14c-964f86bd6a10', 'სათამაშოებს რატომ არ სძინავთ? 🧸', 'თავად არ იძინებს, მაგრამ ყველა სათამაშოს სათითაოდ აწვენს და საბანს აფარებს? სინამდვილეში, ეს როლური თამაში მას ნელ-ნელა, ფსიქოლოგიურად საკუთარი ძილისთვის ამზადებს — ხელს ნუ შეუშლით.'),
  ('22a3d2df-ec5e-47c6-9766-7dc689ce8423', 'უბრალოდ შეისუნთქეთ მისი სურნელი 🫂', 'დღეს მართლა გაგაგიჟათ და მთელი ენერგია გამოგაცალათ? მაგრამ საწოლში ისეთი უმანკო სახით სძინავს... ჩააქრეთ შუქი. გვერდით მიუწექით, ღრმად შეისუნთქეთ ბავშვის ეს სუფთა სურნელი და სიბნელეში სიყვარულით უჩურჩულეთ.'),
  ('48b463cd-d776-4db6-a471-4507d498dd54', 'სუპერმარკეტის შუაგულში ნუ გაშეშდებით 🛒', 'სუპერმარკეტში შეხვედით და დაგავიწყდათ, რისი ყიდვა გინდოდათ? თუ საყიდლების სიას ციფრულად არ შეინახავთ, ამ ქაოსში ყველაფერი დაგავიწყდებათ. ყოველთვის ენდეთ აპლიკაციაში არსებულ ციფრულ მეხსიერებას, რათა სახლში ხელცარიელი არ დაბრუნდეთ.'),
  ('9dc02f00-56a0-48da-87a7-8f742a42c374', 'შენ ჩემთან არ თამაშობ! 😤', 'სანამ კერძს ურევთ, მოდის, სახეს ხელებით თავისკენ გატრიალებინებთ და გეუბნებათ: მე შემომხედე!? მართალია. მას მხოლოდ თქვენი ფიზიკური ყოფნა კი არა, მთელი თქვენი ყურადღება სჭირდება. საქმე გვერდზე გადადეთ და მხოლოდ 2 წუთის განმავლობაში, თვალებში უყურეთ და ყურადღებით მოუსმინეთ.'),
  ('a00b84e6-561e-4101-8d5d-a0f8a705abed', 'წვიმის ხმებით სავსე ოთახი 🌧️', 'ხმა აღარ ამოგდით და ზღაპრის წასაკითხად ძალა არ გაქვთ? „ჭკვიან ზღაპრებში“ ფონად მხოლოდ წვიმისა და ტყის ხმები ჩართეთ. ბუნების ეს მონოტონური სიმშვიდე ზოგჯერ საუკეთესო ზღაპარზე სწრაფადაც კი აძინებს.'),
  ('a4fa9d13-3510-4b51-9dcb-583bfd5c19ad', 'მისივე მოფიქრებული სახელით მიმართვა 🦇', 'დილით გაიღვიძა, საკუთარ სახელზე უარი თქვა და მოგთხოვათ, „ბეტმენი დამიძახეო“? აჰყევით! 5 წუთის განმავლობაში უთხარით: „ინებე, ბეტმენ, ფაფა ჭამე“ — და ოთახში დაძაბულობა მაშინვე კომედიად გადაიქცევა.'),
  ('e5dd03b1-7179-4527-8c52-f0958fe208e9', 'Instagram-ის დედებით გამოწვეული დაღლილობა 📱', 'Instagram-ის გახსნისთანავე სხვების იდეალური ბავშვების დანახვამ გული არ დაგწყვიტოთ! დახურეთ ეს აპლიკაცია და Anacan-ის საზოგადოებაში შედით. როცა დაინახავთ, რომ სხვების სახლებშიც ისეთივე არეულობაა, როგორიც თქვენთან, ღრმად ჩაისუნთქავთ — მარტო არ ხართ.'),
  ('17e2ffec-fd31-4ab8-8917-684e3ceaaff9', 'წყლით მთელი სტრესის ჩამორეცხვა 🛀', 'ზოგჯერ არაფერი ჭრის და ბავშვი ყველაფერზე ტირის. ჩასვით თბილი წყლით სავსე აბაზანაში. წყლის ეს მისტიკური, დაძაბულობის მომხსნელი ეფექტი მთელ ოთახსა და მის ნერვულ სისტემას მაშინვე საოცარ სიმშვიდეს მოუტანს.'),
  ('d1311034-b416-403f-a981-34577f22c978', 'წადი, არ მინდიხარ 💔', 'იმის გამო, რომ სურვილი არ შეუსრულეთ, გითხრათ: „ცუდი დედა ხარ, წადი!“? გული გეტკინათ. მაგრამ მას ჯერ არ შეუძლია, ბრაზი სიტყვებით სწორად გამოხატოს — სინამდვილეში ამბობს: „იმედი გამიცრუვდა“. პირადად ნუ მიიღებთ, უბრალოდ სიყვარულით ჩაეხუტეთ.'),
  ('e3289711-a700-447f-9c8d-d0e1b469b80e', 'ჩაის დრო წარმოსახვით მეგობართან ერთად 🫖', 'ოთახის კუთხეში სიცარიელეს ჩაის უსხამს და იცინის? წარმოსახვითი მეგობრის პერიოდი დაიწყო!'),
  ('05726924-8563-423e-bd0f-f5be06f1d806', 'მამის არასწორად წაკითხული ზღაპარი 📖', 'ამ საღამოს ზღაპრების წიგნი მამას მიეცით. დაე, მან ამბავი განზრახ უკუღმა, სასაცილოდ და აბსურდულად მოჰყვეს. თქვენ კი გვერდიდან სიამოვნებით უყურეთ, როგორ ერთობა ბავშვი მის შესწორებაში და როგორ კისკისებს.'),
  ('1b87ed18-3cf6-4e93-88b1-58f24b42513f', 'დილის ადრიანი დაჭერობანა 🏃‍♂️', 'დილის 7 საათზე დივნებზე დარბის? ნუ დაუყვირებთ. საქმეები 2 წუთით გვერდზე გადადეთ და თქვენც ხტუნვით შეუერთდით. ბავშვის წარმოსახვით სამყაროში ჩართვა სინამდვილეში თქვენთვისაც სტრესის მოხსნის უჩვეულო საშუალებაა.'),
  ('9c4135ea-bc1e-4450-aea1-64dfec877859', 'უეცარი ენაბორძიკის პანიკა 🤖', 'ბავშვის უეცრად დაწყებულმა ენაბორძიკმა ინტერნეტში დაავადებების ძებნა დაგაწყებინათ? შეჩერდით! Anacan AI-ისგან შეიტყვეთ, რომ ეს 4 წლის ასაკის განვითარების ნახტომია, და პანიკა ჩააცხრეთ.'),
  ('15bb2b6b-7a84-4331-86dd-6aee2aba5539', 'სიჩუმე ეკრანზე ციფრებად 📉', 'როგორც იქნა, დაიძინა. სახლში ისეთი სიჩუმე ჩამოწვა, რომ ყურებში წუილი გესმით? აპში ხმის საზომი გახსენით. 0 desibel-ის მაჩვენებლის ყურება თქვენი დაღლილი და ხმაურისგან გადატვირთული ტვინისთვის მსოფლიოში საუკეთესო ვიზუალური მასაჟი იქნება.'),
  ('21cfa5ea-471d-459d-a626-6d4be6cf6e4c', 'ჩხუბი იმის გამო, რომ ბანანი თქვენ გაფცქვენით 🍌', 'ოთახში რევოლუცია დაიწყო, რადგან ბანანი თქვენ გაფცქვენით? ამ ასაკის ოქროს წესი ასეთია: ყველაფერი თავად უნდა გადაწყვიტოს. ბანანს ქერქს უკან ვეღარ მიაკრავთ, ამიტომ ახალი მიეცით და აცადეთ, თავად გაფცქვნას ისე, როგორც სურს, რათა დამოუკიდებლობის განცდა არ შეელახოს.'),
  ('e6cc1e43-997c-46d7-a69b-a71076271387', 'ბაგირზე მოსიარულე ტროტუარის კიდეზე 🧱', 'პარკში მიმავალი სწორ გზაზე კი არა, აუცილებლად ტროტუარის ყველაზე ვიწრო კიდეზე სიარულს ითხოვს? მკლავზე ხელი მოჰკიდეთ უსაფრთხოებისთვის და აცადეთ, ეს პატარა მწვერვალი დაიპყროს. ასე წონასწორობა და თავდაჯერებულობა ერთდროულად შესანიშნავად ვითარდება.'),
  ('6daea202-5e39-49bd-9344-4fdbc59064e5', 'საკუთარი თავისთვის დროის დათმობა დანაშაული არ არის 🥗', 'მის გამოსაკვებად მრავალფეროვანი მენიუები შეადგინეთ, მაგრამ თავად რა მიირთვით? ჯანსაღ რეცეპტებში დედებისთვის განკუთვნილი მარტივი, 5-წუთიანი სალათი მოამზადეთ და, ბოლოს და ბოლოს, საკუთარი ენერგიის აღდგენაც არ დაგავიწყდეთ.'),
  ('744c45ec-e43d-4be3-95b9-700cd56edef4', 'ერთმანეთისთვის ჩუმად თვალებში ყურება 🥂', 'ბავშვს ჩაეძინა. თქვენ და თქვენი პარტნიორი დივანზე სხედხართ და ჩუმად უყურებთ ერთმანეთს. არაფერს ამბობთ. სინამდვილეში ეს სიჩუმე ყველაზე რომანტიკული და გულწრფელი გზაა იმის სათქმელად, რომ ესეც შეძელით და შესანიშნავი გუნდი ხართ.'),
  ('9632825c-5c1a-41f6-900b-2b6b7e88d644', 'ქურთუკის ჩაცმაზე უარის თქმა 🧥', 'გარეთ მზეა და ამიტომ ზამთრის ქურთუკის ჩაცმა არ სურს? გახსენით ამინდისა და ტანსაცმლის განყოფილება და ტელეფონში ზამთრის ტანსაცმელში გამოწყობილი ბავშვის სიმბოლო აჩვენეთ. წესის ახსნა ციფრულ ეკრანს მიანდეთ და თავად განზე გადექით — ბავშვი მშვიდად ჩაიცვამს.'),
  ('6f53d579-a4b1-4e03-8f30-fcdd7a9084bf', 'სიბნელეში ჩურჩულით გულის გადაშლა 🌙', 'ოთახში სინათლე მთლიანად ჩააქრეთ. გვერდით მიუწექით და ძალიან ხმადაბლა, ყურში ჩასჩურჩულეთ დღის განმავლობაში მომხდარი ამბები ან ის, რაც მის ხასიათში ყველაზე მეტად მოგწონთ. ჩურჩული ტვინის ძილისთვის მომზადების ყველაზე მისტიკური მეთოდია.'),
  ('ba2db9df-7097-4890-b7eb-8938c592806f', 'ტყუილი — „ეს ჩემი ბრალი არ არის“ 🤥', 'წყალი განზრახ დაღვარა, შემდეგ კი სათამაშო მანქანისკენ გაიშვირა თითი და თქვა: „მან გადაასხა“? ეს ტყუილი კი არა, თავდაცვის მექანიზმია. უთხარით: „მოდი, ამ მანქანასაც ვასწავლოთ, როგორ უნდა დაასუფთაოს“ და მისი გონება ოსტატურად სხვა მიმართულებით გადართეთ.'),
  ('ce02bfea-edc6-42ad-80fd-37f3c322993b', 'სასრიალოს დიპლომატია 🤝', 'სასრიალოზე სხვა ბავშვს ხელი ჰკრა, რომ თავად ჩამოსრიალებულიყო? უხერხულობის გამო ბავშვს ნუ დაარტყამთ. ნაზი, მაგრამ მტკიცე ხმით შეახსენეთ წესი: „ახლა მისი ჯერია, შემდეგ — შენი“. სწორედ ასე ისწავლის სოციალურ წესებს.'),
  ('2128fd31-18d2-4020-9903-1e4bdb06a192', 'კვერცხმა არ იტიროს 🍳', 'კვერცხის გატეხვისას შეეცოდა და აღარ ჭამს? მის თანაგრძნობას საზღვარი არ აქვს. სიტუაცია მაშინვე გამოასწორეთ ისეთი საყვარელი გამონაგონით, როგორიცაა: „ახლა ის შენს კუნთებში იცხოვრებს და გაგაძლიერებს“.'),
  ('2fbf236d-dcf9-462e-911e-87f8e16831b1', 'ბალიშების განლაგების წესი 🛏️', 'ტირის, რადგან ბალიში მილიმეტრის სიზუსტით არ დევს? ძილთან დაკავშირებული აკვიატებული რიტუალები გაუჩნდა. მიჰყევით მის წესებს, ბალიში ისე გაასწორეთ, თითქოს სახაზავით გაზომეთ, შემდეგ კი შუქი მტკიცედ ჩააქრეთ და უსაფრთხოების განცდა შეუქმენით.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('3b18406f-7fbc-4193-88c1-aa910648f2b5'::uuid, 'გადაგდებული ნაგავი დამიბრუნე! 🗑️', 'მის მიერ შენახული ძველი შოკოლადის ქაღალდი ნაგავში გადააგდეთ და ამის გამო ქვეყანა დაიქცა? თქვენთვის ის ნაგავია, მისთვის კი — განძი. ყურადღება სხვა, კაშკაშა სათამაშოზე გადაატანინეთ.'),
  ('3d6e1c1c-6a73-4824-ae1e-d09852574023', 'სახლის დიქტატორი სუფრასთან 👑', 'საუზმის დროს მაგიდასთან ყველას განკარგავს და გეუბნებათ: „იქ კი არა, აქ დაჯექი“? მისი ნების უხეშად გატეხვის გარეშე უთხარით: „კარგი, იყოს ისე, როგორც შენ გინდა“ და პატარა ღიმილით შეინარჩუნეთ წონასწორობა და სიმშვიდე ოთახში.'),
  ('51ca75c5-97b8-4826-b323-ca25f125a567', 'არავისთან არაფრის ახსნა 📝', 'ვერავინ ხედავს, რამდენად იღლებით სახლში, და ეს მოთმინებას გაკარგვინებთ? გახსენით განწყობის დღიური. ყველაფერი, რამაც დღეს ჭკუიდან გადაგიყვანათ, იქ ჩაწერეთ. ემოციის მიღება და მისი წერილობით გამოხატვა უფრო მეტად დაგეხმარებათ.'),
  ('989e82d9-dbab-4ad4-8fb4-42a6025e0511', 'ჩუმად კითხვის საათი 📖', 'დღეს საღამოს კითხვა არ იქნება. გონიერი ზღაპრებიდან მშვიდი ფონური მუსიკა ჩართეთ და მხოლოდ სურათებს დააკვირდით ჩუმად. მისი ტვინი ვიზუალურად დაიღლება და ისე მიეცემა ძილს, რომ თქვენ ერთი სიტყვის თქმაც კი არ დაგჭირდებათ.'),
  ('6f490476-47fe-4d7a-adc6-bf02e33e53bc', 'გამოცდა მაღაზიის სალაროსთან 🛒', 'შოკოლადის გამო სწორედ სალაროს წინ ყვირის? უკან მდგომთა მზერის მიუხედავად, ნუ დანებდებით. გახსენით საყიდლების სია და უთხარით: „აქ არ წერია, სალარო ამას ვერ გაატარებს“. თუ მტკიცედ იდგებით თქვენს გადაწყვეტილებაზე, ისიც უკან დაიხევს.'),
  ('851d1060-8f2e-4d29-b181-eb135eec18ca', 'ჭამა ხელების გარეშე, პირით 🐶', 'თეფშიდან ხელების გარეშე, კატასავით ჭამა სურს? ნუ აუკრძალავთ. სამზარეულო მაინც დასვრება — აცადეთ, 5 წუთით კატა იყოს. ეს სახალისო როლური თამაში უმადობასთან გამკლავების ყველაზე მხიარული გზაა.'),
  ('9555c57b-eea5-4d41-a55f-827af2218674', 'მამისგან მხრების მასაჟი 💆‍♂️', 'დღეს დიდხანს იდექით ფეხზე, ბავშვის დევნითა და იატაკიდან სათამაშოების აკრეფით წელი გტკივათ. როგორც კი ბავშვი დაიძინებს, პარტნიორს სთხოვეთ, 10 წუთის განმავლობაში მხრები დაგიმასაჟოთ. თქვენ ოჯახის მამოძრავებელი ძალა ხართ და აუცილებლად უნდა აღიდგინოთ ენერგია.'),
  ('ac3ac13e-8fa6-42b2-ace2-92fa2336b5eb', 'ოთახში სრული სიბნელე 🌌', 'დერეფნიდან შემოსული სინათლის გამო ვერ იძინებს? სრულყოფილ პირობებს ეძებს. კარი მჭიდროდ დახურეთ და ოთახი მთლიანად დააბნელეთ, რათა მელატონინმა თავისი ბუნებრივი ფუნქცია შეასრულოს და ბავშვი სწრაფად დააძინოს.'),
  ('e268e86b-b622-447e-800e-69d444728521', 'კრიზისი „ეს ჩემია!“ 🧸', 'სახლის პულტს გულში იხუტებს და ამბობს: „ეს ჩემია!“? ის საკუთრების საზღვრებს ამოწმებს. ნუ უწოდებთ ეგოისტს. უთხარით: „მადლობა, რომ ჩემთვის იპოვე“, შემდეგ კი ყურადღება სხვა თამაშზე გადაატანინეთ და პულტი დაიბრუნეთ.'),
  ('e71d30e6-0cdb-4938-b907-fc93e194b4d5', 'დაუმთავრებელი წინადადებების მნიშვნელობა 🗣️', 'როდესაც სიტყვა ავიწყდება, ხელით მიგანიშნებთ და ელოდება, რომ გამოიცნობთ? მოთმინებით დაასრულეთ მისი წინადადება და დააკვირდით, როგორ მოეფინება სახეზე შვება. სწორედ თქვენი მხარდაჭერით ივითარებს ის ლექსიკურ მარაგსა და თავდაჯერებულობას.'),
  ('0a86e24e-bf60-4b61-ae36-925c5211691c', 'წყლის გაშრობის მოთხოვნა 💧', 'ჭიქაში წყლის დალევის ნაცვლად ყვირის: „ეს ძალიან სველია, გააშრე!“? ლოგიკის ძებნის გარეშე გადაასხით წყალი სხვა ფერის ჭიქაში და უთხარით: „მშრალი წყალი მოგიტანე“. ილუზიის ხელოვნება დედობისას თქვენი ყველაზე ძლიერი იარაღია.'),
  ('b27687ec-9619-4dbe-be9c-054706708b62', 'ბუნებაში გასვლა აუცილებელია ⛅', 'ოთხ კედელს შორის მისი ენერგია აგრესიად იქცევა და ყველა წინადადებას სიტყვით „არა“ იწყებს? ამინდისა და შესაფერისი ტანსაცმლის იმედად აუცილებლად გაიყვანეთ გარეთ. მიწასთან შეხება მის ნერვულ სისტემას მყისიერად განტვირთავს.'),
  ('eeca2adc-6712-4238-9603-30877865ed81', 'ზარის ხმაზე ავტომატურად დაძინება ⏱️', 'როგორც კი ძილის დრო მოდის, მოულოდნელად ტუალეტში წასვლა უნდა? დააყენეთ ტაიმერი. შემოიღეთ წესი: „როცა ზარი დარეკავს, ყველა შუქს აქრობს“ — ასე კამათის გარეშე დაასრულებთ ამ უსასრულო დამშვიდობებასა და ოსტატურ მანიპულაციას.'),
  ('4e140178-6301-4406-9f9f-fe623cbcfff7', 'დამალობანა კარს მიღმა 🙈', 'საბავშვო ბაღში გაგვიანდებათ, ის კი ფარდის უკან იმალება და გეუბნებათ: „მიპოვე!“? ყვირილი პროცესს მხოლოდ გაახანგრძლივებს. თქვით: „ნეტავ, სად არის ჩემი პატარა?“ — ჩაერთეთ 2-წუთიან თამაშში და იქიდან სიცილით გამოიყვანეთ.'),
  ('7964aed1-1770-40a2-a565-23bfdc9aea21', 'განსხვავებული ხმოვანი ეფექტები ჭკვიან ზღაპრებში 🪄', 'ჩართეთ ჭკვიანი ზღაპრები. ისტორიის კითხვისას კარის ჭრიალის, ქარისა და ჩურჩულის ხმები გამოსცეთ და ოთახში ხმოვანი თეატრი მოაწყვეთ. ეს უჩვეულო ხმები მის ყურადღებას მყისიერად გადაიტანს ზღაპრულ სამყაროში.'),
  ('c87486c1-f5de-473b-8cd5-b9e2e2bd31c1', 'ეკრანის გამო სინდისის ქენჯნა 📺', 'დღეს ბევრი საქმე გქონდათ და ბავშვმა ტელევიზორთან დიდი დრო გაატარა? სინდისის ქენჯნა გაწუხებთ? ყოველდღე სრულყოფილი ვერ იქნებით. ზოგჯერ ეკრანი ყველაზე უწყინარი ძიძაა, რომელიც დიდი ქაოსისგან გვიხსნის — დამშვიდდით.'),
  ('0c893825-691b-4509-9849-6369336b84d4', 'მხატვარი, რომელიც საკუთარ ნამუშევარს ხევს 🖍️', 'თავისი დახატული ხაზი არ მოეწონა, ამბობს, ცუდი გამოვიდაო, ქაღალდს ხევს და აგდებს? მას თვითკრიტიკისა და სრულყოფილებისკენ სწრაფვის გრძნობა უჩნდება! უთხარით: „მოდი, შემდეგ ჯერზე სხვა ფერი ვცადოთ“ და მისი იმედგაცრუება აღმოჩენის სურვილად აქციეთ.'),
  ('bcac5731-4815-4adc-beb4-861e3ff078b1', 'კატასავით მოფერება 🐾', 'ამ დილით ოთხზე დადის, ფეხებზე გეხახუნებათ და მხოლოდ „მიაუს“ ამბობს? იმის ნაცვლად, რომ წესების ახსნა დაუწყოთ, თქვენც გაუწოდეთ წარმოსახვითი რძის ჯამი. თამაში ყოველთვის უფრო მარტივი და სახალისოა, ვიდრე დატუქსვა.'),
  ('c6026760-e985-429a-b39f-d4d1786df630', 'მინი-ლაბორატორია აბაზანაში 🛀', 'წყალში სხვადასხვა ფერის საპნებს ურევს და ჯადოსნურ ელექსირს ამზადებს? დიახ, აბაზანაში ყველაფერი ირევა. სამაგიეროდ, ბავშვი ნივთიერებების გახსნასა და შერევას სწავლობს. ასეთი სამეცნიერო კვლევა საღამოს დაღლილობას გაფანტავს და ბავშვს მშვიდი ძილისთვის საუკეთესოდ მოამზადებს.'),
  ('40e041b4-2484-475f-93b5-25cda3ee362e', 'სპექტაკლი „ვინ ხართ?“ 🎭', 'ისე გიყურებთ, თითქოს უცხო იყოთ, და გეკითხებათ: „ვინ ხართ? დედა სად არის?“ ეს ახალი როლური თამაშია. უთხარით: „მე ექიმი დეიდა ვარ და თქვენი გულის მოსასმენად მოვედი“, შემდეგ კი მოუღიტინეთ. დაე, დილიდან მთელი ოთახი სიცილით აივსოს.'),
  ('417e0bcc-cf3b-4a96-95e9-58a2f51764f6', 'ტუალეტის ქაღალდის ხელოვნება 🧻', 'ოთახში შესვლისას დაინახეთ, რომ ტუალეტის ქაღალდი მთლიანად გაუშლია და მთელ სახლში მოუფენია? გაბრაზების ნაცვლად, ერთად შეაგროვეთ ქაღალდები და ბურთი გააკეთეთ. ქაოსი ყვირილით კი არა, შემოქმედებითობითა და სიცილით დაამარცხეთ.'),
  ('4a1de341-603c-4aae-ab4d-439d7bb05d7c', 'სიჩუმისგან მიღებული სიამოვნება 🤫', 'როგორც იქნა, დაიძინა. სახლში ისეთი სიჩუმე ჩამოწვა, რომ ყურებში ზუზუნი გესმით? აპში ხმის საზომი გახსენით. წარწერის „0 desibel“ ყურება თქვენი დაღლილი და ხმაურით გადატვირთული ტვინისთვის მსოფლიოში საუკეთესო ვიზუალური მასაჟი იქნება.'),
  ('3d9dcc3e-1698-4fca-951e-a58aed0724d2', 'ჭიქის ფერი არასწორია 🥤', 'ოთახში ალიაქოთი ატყდა, რადგან წყალი ყვითელ ჭიქაში მიეცით? გულთან ნუ მიიტანთ — ის უბრალოდ ამ დილით თქვენს საზღვრებს ამოწმებს. წყალი დაუყოვნებლივ ლურჯ ჭიქაში გადაასხით, ოთახში მშვიდობა აღადგინეთ და ენერგია დაზოგეთ.'),
  ('522145b2-4826-4821-80c0-e0e180045415', 'უბრალოდ გულში ჩაკვრა 🫂', 'დღეს მართლა გაგაგიჟათ და მთელი ენერგია გამოგაცალათ? მაგრამ საწოლში ისეთი უმანკო სახით სძინავს... ჩააქრეთ შუქი და ზღაპარს ნუ წაუკითხავთ. უბრალოდ გვერდით მიუწექით, ღრმად შეისუნთქეთ ბავშვის ეს სუფთა სურნელი და მადლიერი იყავით.'),
  ('792e3525-032e-4662-ba49-1276a3b3ef78', 'სხვა დედების ამბები 💬', 'ინსტაგრამის გახსნისთანავე სხვების იდეალური ბავშვების დანახვამ გული ნუ დაგწყვიტათ! დახურეთ ეს აპლიკაცია და Anacan-ის საზოგადოებაში შემოდით. როცა დაინახავთ, რომ სხვების სახლებშიც ისეთივე არეულობაა, როგორიც თქვენსაში, ღრმად ამოისუნთქეთ.'),
  ('3e4bbd84-ef8f-45a2-b630-5aeadd95390e', '„ხელი არ მომკიდო!“ — დამოუკიდებლობა 🚶‍♂️', 'გზაში ხელს გიშვებთ და დამოუკიდებლად სიარული სურს? თუ უსაფრთხო ადგილას ხართ, მიეცით საშუალება, საკუთარი დამოუკიდებლობა გამოსცადოს. თქვენ კი ორი ნაბიჯის მოშორებით მიჰყევით და ამ პატარა, თავისუფალ მეამბოხეს სიამაყით უყურეთ.'),
  ('6dda8fe5-3765-4d3c-bdfe-6519fcf2d0a0', 'სამზარეულოში დახმარების კატასტროფა 🧑‍🍳', 'ცომის გაბრტყელებისას სკამი მოაჩოჩა და დაჟინებით მოითხოვა, რომ ფქვილი თავად დაეყარა? თუ არ მისცემთ უფლებას, ატირდება. მიეცით პატარა პლასტმასის ჯამი და ცოტაოდენი ფქვილი. სამზარეულო აირევა, სამაგიეროდ მისი ეგო დაკმაყოფილდება.'),
  ('776040ef-af05-4430-a752-3b380b194dba', 'მთვარე წინ მიგვიძღვის 🌕', 'საღამოს მანქანით დაბრუნებისას ფანჯარაში იყურება და ამბობს, რომ მთვარე მოგვყვება? მას ჰგონია, რომ მთელი სამყარო მის გარშემო ტრიალებს. ნუ დაუნგრევთ ამ ფანტაზიას — ჰკითხეთ: „ნეტავ, სად მოგვყვება?“ და თამაშში აჰყევით.'),
  ('58e2fe84-f6c5-40ff-93ab-26ea06ad9f14', 'ჭუჭყიანი მაისურის სიყვარული 👕', 'უკვე 3 დღეა ერთი და იგივე მაისური აცვია და გარეცხვის უფლებას არ გაძლევთ? ამ ასაკში ზოგიერთი ნივთი ბავშვს უსაფრთხოების განცდას ანიჭებს. ნუ შეეკამათებით — მაისური ხელიდან პატარა გამოგონილი ამბით გამოართვით: „სარეცხ მანქანაში ჯადოსნურ თავგადასავალში გავუშვი, უფრო ძლიერი დაბრუნდება“. ამ ილუზიას დაიჯერებს.'),
  ('b740d6be-007b-4aa6-9c46-6ffbce8b157e', 'ჭიანჭველის გლოვის ცერემონია 🐜', 'პარკში მიწაზე ჭიანჭველა დაინახა, ადგილიდან აღარ იძვრის და ტირის, რადგან ფიქრობს, რომ ის დაიკარგა? მის თანაგრძნობას საზღვარი არ აქვს. უთხარით, რომ ახლა დედამისი მოვა და წაიყვანს.'),
  ('fcc60573-09e9-4a7c-8399-55df532828cd', 'თეთრი ხმაური ჭაობში 🌊', 'ოთახში დაძინების ნაცვლად აქეთ-იქით დახტის? ხმის საზომის ფონზე ჩაურთეთ ზღვის ძლიერი ტალღების ან თეთრი ხმაურის ხმა. ეს მონოტონური სიხშირე ტვინში მოჭარბებულ ენერგიას ჩააცხრობს და 10 წუთში თვალები დაეხუჭება.'),
  ('73abbd29-9b2f-4f48-8461-6482853b741f', 'ცოცხით დამღუპველი დახმარება 🧹', 'როცა სახლს ალაგებთ, მოდის, ამბობს, „მე გავაკეთებ“, და ნაგავს ოთახში კიდევ უფრო მეტად ფანტავს? თუ არ მისცემთ უფლებას, მთელი ამბავი ატყდება. მიეცით ნესტიანი ხელსახოცი და უთხარით: „თქვენ მხოლოდ მაგიდის ამ კუთხეზე ხართ პასუხისმგებელი“. ასე თქვენც გააკეთებთ თქვენს საქმეს და მისი ეგოც კმაყოფილი დარჩება.'),
  ('eacaec53-45d2-4b70-9f52-8b48878bd78c', 'ცარიელი კედლის ყურების დრო 🛋️', 'ოთახში დამოუკიდებლად თამაშობს? გთხოვთ, ამ ძვირფას დროს ჭურჭლის რეცხვაში ნუ დახარჯავთ! წამოწექით დივანზე, აიღეთ ჩაი და უბრალოდ კედელს უყურეთ. დიახ, არაფერზე იფიქროთ. განწყობის დღიურში 5-წუთიანი სიმშვიდე ჩაიწერეთ. ეს თქვენ გჭირდებათ.'),
  ('f172b5bc-02ec-44a8-9df7-fcc0cfb0c0e3', '„თმა მომტყდა!“ — დრამა 🪮', 'სავარცხლის დანახვისთანავე ამბობს, რომ თმა სტკივა, და გარბის? სენსორული მგრძნობელობა აშინებს. ყურადღება გადაატანინეთ. მიეცით სარკე და უთხარით: „ვნახოთ, ვინ გამოყოფს სარკეში ენას უფრო სასაცილოდ?“ სანამ გართულია, თმა სწრაფად დაუვარცხნეთ და საქმეც დასრულებულია.'),
  ('2127b5f4-7e9a-438e-9094-bd9d7f0d5237', 'საყიდლების სიის ხრიკი 🛒', 'სალაროსთან მოულოდნელად კანფეტი მოითხოვა? საერთოდ ნუ მიაქცევთ ყურადღებას გარშემომყოფების მზერას, თითქოს თქვენს დედობას აფასებენ. გახსენით საყიდლების სია, უთხარით: „სიაში არ არის, ამიტომ სალარო ამას ვერ მოგვყიდის“ და მტკიცედ იდექით თქვენს გადაწყვეტილებაზე.'),
  ('73af2e7a-1bb5-4576-8888-801050bfada3', 'საღებავებმა კედელზე გადაინაცვლა 🖍️', 'ოთახში შეხვედით და კედელზე ახალი ფრესკა დაგხვდათ? ღრმად ჩაისუნთქეთ. ბავშვმა უბრალოდ ფურცლის საზღვრებს გადააბიჯა და თავის მოტორულ უნარებს უფრო ფართო მასშტაბით ცდის. სანამ წაშლით, აუცილებლად გადაუღეთ ფოტო ამ შედევრს, რათა მომავალში აჩვენოთ და ერთად იცინოთ.'),
  ('f6ed5025-5dc3-4f4a-8ce2-d48478e2666f', 'სიჩუმის ეკრანული დასტური 📉', 'როგორც იქნა, დაიძინა. ყურებში ჯერ კიდევ ყვირილის ხმა გიწკრიალებთ? გახსენით ხმის საზომი. უყურეთ, როგორ ეშვება ოთახში ხმის მაჩვენებელი 0 დეციბელამდე — ეს თქვენი დაღლილი და გადატვირთული ტვინისთვის მსოფლიოში ყველაზე სასიამოვნო ვიზუალური მასაჟი იქნება.'),
  ('48318bc7-c4f3-4717-9848-18bd10967e29', 'მამის გამოგონილი ზღაპარი 🦸‍♂️', 'ხმა აღარ გაქვთ და წიგნის წაკითხვაც არ გინდათ? ზღაპარი მამას გადააბარეთ. მოუყვეს გამოგონილი და აბსურდული ამბავი, რომლის მთავარი გმირიც თავად ბავშვია. თქვენ კი კედელთან წამოწექით, დაისვენეთ და უყურეთ, როგორ კისკისებს ბავშვი მამის მონაყოლზე.'),
  ('4ac93f87-372d-4d1a-a449-a2da763a8227', 'ამ საჭმელს ცუდი ფორმა აქვს 🥒', 'თეფში გვერდზე გასწია, რადგან კიტრი მრგვლად კი არა, გრძელ ნაჭრებად დაჭერით? საკვების მიმართ მისი ესთეტიკური გემოვნება ახლა ყალიბდება. ისწავლეთ, როგორ შენიღბოთ იგივე ბოსტნეული სახალისო ფიგურებად. ამ დიზაინერულ თამაშში თქვენ გაიმარჯვებთ.'),
  ('61167ef0-dce7-4186-9b36-5aa8a00936ff', 'მარტოობისთვის აბაზანაში გაქცევა 🛀', 'მთელი დღე ფეხებზე გეკვრებათ და ამდენი შეხებისგან სხეული დაგიბუჟდათ? შეხებით გადაღლა რეალურია. დატოვეთ ბავშვი ოთახში, 5 წუთით შედით აბაზანაში, დაკეტეთ კარი და უბრალოდ ისუნთქეთ. ძალების აღდგენა გჭირდებათ.'),
  ('4c96a8e1-971d-4b98-9e5c-faff2c2726a9', 'ფილოსოფიის უეცარი შემოტევა 🤔', 'უცებ მეცნიერული კითხვა დაგისვათ: „რატომ არის ზღვის ფსკერი შავი?“ ნუ დაიბნევით! გახსენით Anacan AI, მიიღეთ მისი ასაკისთვის გასაგები, უსაყვარლესი, ზღაპრული პასუხი, რომელიც პედიატრისა და ფსიქოლოგის მიერაა მოწონებული, და წაუკითხეთ. თქვენ ხომ დედა ხართ, რომელმაც ყოველთვის ყველაფერი იცის!'),
  ('9f289ae7-fe30-4b1a-8ebd-63874521363d', 'დაჭერობანა ბნელ ოთახში 🔦', 'ძილის დროა, მაგრამ ენერგია ჯერ კიდევ არ ელევა? ოთახში ყველა შუქი ჩააქრეთ. აიღეთ პატარა ფანარი და ითამაშეთ თამაში: „ვნახოთ, კედელზე სინათლე ვის დაიჭერს“. სიბნელეში თამაში მელატონინის გამოყოფასაც დააჩქარებს და ბავშვსაც დაღლის.'),
  ('d28d5d46-d2a6-4daa-b454-adbdf6be3f63', 'უხილავი ჭრილობის ტკივილი 🩹', 'თითზე არაფერი აქვს, მაგრამ ტირის, ამბობს, გამეჭრაო, და პლასტირს ითხოვს? ეს ფიზიკური ტკივილი არ არის — მას თქვენი სითბო და თანაგრძნობა სჭირდება. დააკარით პლასტირი, აკოცეთ და უთხარით: „ჯადოსნური კოცნით მოგირჩინე“. ასე თქვენი დღეც გადარჩება.'),
  ('19ac1700-7f02-47aa-b9e8-f8064c7e18d0', 'დახურული კარი და პირადი სივრცე 🚪', 'თავის ოთახში შევიდა, კარი მოიხურა და გითხრათ, არ შემოხვიდეო? ნუ გეწყინებათ. მას უბრალოდ ხმაურისა და ქაოსისგან განმარტოება და დასვენება სურს. თუ უსაფრთხოების მხრივ ყველაფერი რიგზეა, მიეცით საშუალება, პირადი სივრცით დატკბეს. იზრდება!'),
  ('2cb51eab-cbdc-48ba-8569-e245d61ad27e', 'ღამის დაუსრულებელი საბაბები 🚰', 'თვალები ეხუჭება, მაგრამ უცებ წამოხტება და ამბობს: „ფეხი მექავება“, „წყალი მინდა“? ძილის გადადების პროფესორია. დააყენეთ ტაიმერი. როცა ტელეფონი დარეკავს, უთხარით, რომ ყველა საბაბმაც უნდა დაიძინოს. ავტორიტეტი ტელეფონს გადააბარეთ და თავად განზე გადექით.'),
  ('9240add5-52c7-45dc-8ae0-15dd7dadfa88', 'ეს ჩემი სახელი არ არის 📛', 'გეუბნებათ: „ჩემი სახელით ნუ მომმართავ, მე ადამიანი-ობობა ვარ“? ეს საკუთარი იდენტობის ძიებაა. აჰყევით! საუზმე მიართვით სიტყვებით: „ინებეთ, ბატონო ადამიანო-ობობავ“. თქვენს ხელშია, ოთახში დაძაბულობა წამებში კომედიად აქციოთ.'),
  ('a897741a-cd22-4371-a712-b1ae3911676e', 'მისივე მოგონილი სიმღერები 🎤', 'მზე ჯერ არც ამოსულა, ის კი დახტის და უაზრო სიტყვებით ხმამაღლა მღერის? ნუ დაუყვირებთ და ნუ გააჩუმებთ. ბავშვი, რომელიც დილას სიმღერით იწყებს, აგრესიისგან თავისუფლდება. თქვენც აჰყევით ამ გიჟურ ენერგიას 1 წუთით და ძილი მაშინვე გაგეფანტებათ.'),
  ('ad4460c3-33b8-4fdc-85b5-ca63eae32f6e', 'Instagram-ის უნაკლო დედები 📱', 'Instagram-ის გახსნისთანავე სხვების დალაგებულ სახლებსა და ჭკვიან ბავშვებს ხედავთ და გული გიტყდებათ? წაშალეთ ეს აპლიკაცია! შეუერთდით Anacan-ის საზოგადოებას. წაიკითხეთ თქვენნაირი ნამდვილი დედების ისტორიები, რომელთა სახლებიც არეულია, ბავშვები კი ჯიუტობენ, და დამშვიდდით.'),
  ('b2cba04d-e6f3-4afd-a54a-7b8bbbf1f6e4', 'ჩურჩულით მოსული ძილი 🤫', 'საწოლიდან გარბის და აქეთ-იქით დახტის? უეცრად ძალიან დაუწიეთ ხმას. დაიწყეთ ჩურჩულით, ძალიან ხმადაბლა საუბარი. თქვენი ნათქვამის გასაგებად ყურადღების მოკრება მოუწევს, მისი ტვინი კი 5 წუთში დაიღლება და ძილის რეჟიმზე გადაერთვება. სცადეთ!'),
  ('1dcf070f-1d18-4228-b248-9ed1c6174aff', 'მაცივარში ნაპოვნი სათამაშო 🧊', 'მაცივარი გააღეთ და შიგნით რეზინის მანქანა დაგხვდათ? ეს მეხსიერებისა და ნივთის უჩვეულო ადგილას გამოცდის თამაშია. ნუ გაბრაზდებით — ეს აბსურდული საქციელი მისი განვითარების ნაწილია.'),
  ('ba708130-cef9-4b08-8a17-7c16cb66de0a', 'სახლიდან გასვლა არ უნდა ⛅', 'სახლი თავდაყირაა, ის კი დივანზე ზის, ტირის და ამბობს, რომ არსად წამოვა? გახსენით ამინდის აპი, შეამოწმეთ გარეთ რეალურად რამდენი გრადუსია, შესაფერისად ჩააცვით და, თუნდაც დაძალება მოგიწიოთ, პარკში წაიყვანეთ. როგორც კი სუფთა ჰაერი სახეზე მოხვდება, მთელი აგრესია გაუქრება.'),
  ('c3fe5fd9-dde9-47f5-b95c-98d26881d393', 'როცა ზღაპრის გმირი თავადაა 🪄', 'გახსენით ჭკვიანი ზღაპრები. იქაური გმირის სახელი პირდაპირ თქვენი ბავშვის სახელით ჩაანაცვლეთ. კითხვისას ხაზი გაუსვით, როგორ მამაცურად და დამჯერად იძინებს ეს გმირი. როცა საკუთარ თავს ამ ამბავში ამოიცნობს, ყოველგვარი პროტესტის გარეშე დახუჭავს თვალებს.'),
  ('139226ae-9370-42b4-954a-012623528599', 'შუაღამის გაუგებარი ტირილი 😭', 'შუაღამისას თვალდახუჭული, ტირილით გაიღვიძა და თქვენი არ ესმის? გადაამოწმეთ ტირილის ანალიზით — დიდი ალბათობით, ეს ღამის ტერორია. ეცადეთ, არ გააღვიძოთ; უბრალოდ მის გვერდით იყავით და ხელი ჩასჭიდეთ. თავისით დამშვიდდება და ისევ დაიძინებს.'),
  ('a18289d8-27fc-49de-ad3f-5cb7e1e5a6a1', 'დედის შოკოლადის საიდუმლო დრო 🍫', 'კარადის უკან, მისგან მალულად შოკოლადს მიირთმევთ? გემრიელად მიირთვით! დაუსრულებელ „რატომებსა“ და ყვირილთან გასამკლავებლად და ენერგიის აღსადგენად ეს გლუკოზა თქვენი ბუნებრივი უფლებაა. ამის გამო თავს ნურასოდეს გაკიცხავთ.'),
  ('a4aa4ea2-4391-40e9-ab29-3d2dca2ff6fe', 'დაჭერობანა ჩრდილთან 🏃‍♂️', 'ქუჩაში სიარულისას მოულოდნელად გარბის და საკუთარი ჩრდილის დაჭერას ცდილობს? მისი წარმოსახვა ლოგიკას სჭარბობს. ნუ გააჩერებთ — თქვენც სცადეთ საკუთარი ჩრდილის დაჭერა და შუა ქუჩაში ამ გიჟურ და მხიარულ თამაშს შეუერთდით. ცხოვრება ზედმეტად სერიოზულად აღსაქმელად საკმარისად ხანგრძლივი არ არის.'),
  ('4d4b704f-57d5-4f72-9df3-13398bb1f2e3', 'უკუღმა ჩაცმული ფეხსაცმლის სინდრომი 👟', 'მარჯვენა ფეხსაცმელი მარცხენა ფეხზე ჩაიცვა, მარცხენა კი — მარჯვენაზე და გასწორების უფლებას არ გაძლევთ? დატოვეთ ასე! მისი სიამაყე — „მე თვითონ ჩავიცვი“ — და დამოუკიდებლობის განცდა ფეხსაცმლის სწორად ჩაცმაზე მილიონჯერ უფრო ძვირფასია.'),
  ('95ee8df4-a59a-42f4-b252-bf062304f70b', 'ჩემში დაგროვილი ბრაზის ციფრულად გადმოტანა 📝', 'ვერავინ ამჩნევს, დღეს რამდენად დაიღალეთ, ხოლო ღიმილის იძულება გახრჩობთ? გახსენით განწყობის დღიური. მთელი დაგროვილი სიმწარე და დაღლილობა ეკრანზე გადმოიტანეთ. სიტყვების „მე გამოვიფიტე“ დაწერა მოჩვენებით სრულყოფილებაზე გაცილებით სწრაფად დაგეხმარებათ გამოჯანმრთელებაში.'),
  ('ec907054-781c-4e3c-be06-6c97119a4864', 'მამის მხრების მასაჟი 💆‍♂️', 'დღეს დიდხანს იდექით ფეხზე — ბავშვის დევნისა და იატაკიდან სათამაშოების აკრეფისგან წელი გტკივათ. როგორც კი ბავშვი დაიძინებს, პარტნიორს მხრების 10-წუთიანი მასაჟი სთხოვეთ. თქვენ ამ სახლის ძრავა ხართ, ძრავას კი აუცილებლად სჭირდება დასვენება და ძალების აღდგენა.'),
  ('486ad622-5eff-484f-8ea8-ea64a245ed91', 'ბანანი რატომ თქვენ გააცალეთ?! 🍌', 'იმიტომ, რომ ბანანი თქვენ გააცალეთ, ოთახში რევოლუცია დაიწყო? ამ ასაკის ოქროს წესი ასეთია: ყველაფერი თავად უნდა გადაწყვიტოს. ბანანის ქერქს უკან ვეღარ მიაკრავთ, ამიტომ დაუყოვნებლივ მიეცით ახალი ბანანი და აცადეთ, თავად გააცალოს ისე, როგორც სურს. გაჯიუტებით მხოლოდ დროს დაკარგავთ.'),
  ('b59a06d3-66eb-4eef-8c37-b58f8b3331ca', 'წყვილის სიჩუმე 🥂', 'ბავშვმა დაიძინა, სახლიც დალაგებულია. მეუღლესთან ერთად დივანზე გვერდიგვერდ დასხედით და ტელევიზორიც კი არ ჩართოთ. უბრალოდ ერთმანეთს შეხედეთ მზერით, რომელიც ამბობს: „ესეც შევძელით, გადავრჩით“. სწორედ ეს არის მშობლობის ყველაზე რომანტიკული და ნამდვილი გუნდური მომენტი.'),
  ('c8f0d464-17b3-4dc7-a4f5-c03c96c8a18b', 'პატარა სახლი მაგიდის ქვეშ ⛺', 'სასადილო მაგიდის ქვეშ შეძვრა, იქ სახლი მოიწყო და სადილობაც იქ სურს? ცოტა შეარბილეთ წესები. წვნიანი იმ ბნელ სივრცეში მიაწოდეთ. გარემოს შეცვლას ყველაზე უმადური ბავშვიც კი შეუძლია თავგადასავლის განცდით დააპუროს.'),
  ('1f9be131-7868-4433-adc0-efe09d70723d', 'თქვენ ჩემთან არ თამაშობთ! 😠', 'როცა ტელეფონს უყურებდით, მოვიდა, სახე ხელებით თავისკენ მოგაბრუნებინათ და გითხრათ: „მე შემომხედეთ!“ მართალია. მას თქვენი მხოლოდ ფიზიკური სიახლოვე კი არა, მთელი ყურადღება სჭირდება. ტელეფონი გვერდზე გადადეთ და 3 წუთის განმავლობაში თვალებში უყურეთ — მაშინვე დამშვიდდება.'),
  ('86f2c2e9-f758-416c-a78d-b431eb3db53a', 'ბაგირზე მოსიარულე ტროტუარის კიდეზე 🧱', 'პარკისკენ მიმავალს სწორ გზაზე კი არა, აუცილებლად ტროტუარის ყველაზე ვიწრო კიდეზე სიარული სურს? ხელით დაიჭირეთ უსაფრთხოებისთვის და აცადეთ, ეს პატარა მწვერვალი დაიპყროს. ასე ერთდროულად შესანიშნავად ვითარდება წონასწორობის უნარი და თავდაჯერებულობა — ხელს ნუ შეუშლით.'),
  ('963db29c-a2ad-4233-bbc2-364a68692feb', 'ხმოვანი ეფექტები ოთახში 🪄', 'ამ საღამოს კითხვით დაიღალეთ? ჩართეთ ჭკვიანი ზღაპრები. სანამ ზღაპარი იკითხება, გამოსცით კარის ჭრიალის, ქარისა და ჩურჩულის ხმები და ოთახში ხმოვანი თეატრი მოაწყვეთ. ეს უჩვეულო ხმები მის ყურადღებას მყისიერად ზღაპრის სამყაროში გადაიტანს.'),
  ('2d56a8b7-4b19-4fb3-95e9-798ee0cfa5d6', 'პარკიდან წამოსვლის შეჯიბრების ტაქტიკა 🌳', 'პარკიდან წამოსვლის დროა და ტირილის ისტერიკა დაიწყო. ძალით წამოყვანა არ გაჭრის. უთხარით: „ვნახოთ, მანქანამდე ვინ უფრო სწრაფად იხტუნავებს კურდღელივით?“ — და მისი ყურადღება მაშინვე სახალისო შეჯიბრებაზე გადაიტანეთ. ის აუცილებლად აგყვებათ თამაშში.'),
  ('42b47472-82e3-49e8-bb91-8de4938efbde', 'უბრალოდ შეისუნთქეთ მისი სურნელი 🫂', 'დღეს მართლა ჭკუიდან გადაგიყვანათ და მთელი ენერგია გამოგაცალათ? მაგრამ საწოლში ისეთი უმანკო სახით სძინავს... ჩააქრეთ შუქი. გვერდით მიუწექით, ღრმად შეისუნთქეთ ბავშვის ეს სუფთა სურნელი და ჩასჩურჩულეთ, რამდენად ძვირფასია თქვენთვის.'),
  ('67931668-7ad8-456d-8077-31b1756abd2c', 'წყალი სხვა ჭიქით მიეცით! 🥤', 'ოთახში ამბავი ატყდა, რადგან წყალი ყვითელი ჭიქით მიეცით? „მე ლურჯი მინდოდა!“ — ამბობს ბავშვი. ზედმეტად ნუ ჩაუღრმავდებით, ის უბრალოდ თქვენს საზღვრებს ამოწმებს. წყალი მაშინვე ლურჯ ჭიქაში გადაასხით, ოთახში მშვიდობა აღადგინეთ და ენერგია დაზოგეთ.'),
  ('047715fd-ae66-4d00-8341-50e230c2b688', 'დინოზავრები ფაფას არ ჭამენ! 🦖', 'დილით არცერთ კითხვას არ პასუხობს და მხოლოდ ღრიალებს? დღეს ის ტირანოზავრია. ჰკითხეთ: „ტირანოზავრები საუზმობენ?“ — მოერგეთ მის მიერ გამოგონილ პერსონაჟს და მშვიდად, ცრემლების გარეშე დასვით მაგიდასთან.'),
  ('2da52e9b-b72c-461f-8480-276d6d5e47df', 'მაღაზიის შუაგულში ნუ დაიბნევით 🛒', 'მაღაზიაში შეხვედით და დაგავიწყდათ, რა უნდა გეყიდათ? დედის გონება მართლაც ძალიან გადატვირთულია. გახსენით აპში „საყიდლების სია“ და მიენდეთ ამ ციფრულ მეხსიერებას — ის ყოველთვის გიხსნით სახლში ხელცარიელი დაბრუნებისგან.'),
  ('020f5f2c-bba3-4441-b9a0-518ce0263ac5', 'ნაგავი კი არა, ხელოვნების ნიმუშია 🎨', 'ოთახის შუაგულში მშრალი მაკარონისა და ქაღალდის ნაგლეჯებისგან დიდი ხელოვნების ნიმუში შექმნა? სისუფთავისადმი ზედმეტი მოთხოვნილება გვერდზე გადადეთ. ეს მსხვილი მოტორიკის ისეთი შესანიშნავი სავარჯიშოა, რომ განვითარების მონიტორინგში აღნიშვნას იმსახურებს. სახლი მუზეუმი არ არის.'),
  ('7231bd75-47cb-4255-ae64-144dcd8d314f', 'სიჩუმე ციფრებში 📉', 'როგორც იქნა, დაიძინა. სახლში ისეთი სიჩუმეა, რომ ყურებში წუილი გესმით? აპში ხმის საზომი გახსენით. ეკრანზე 0 დეციბელის დანახვა თქვენი ხმაურით გადაღლილი და გადატვირთული ტვინისთვის მსოფლიოში საუკეთესო ვიზუალური მასაჟი იქნება.'),
  ('d3223299-be6e-4dfc-bfb7-c168e33bb866', 'დაუსრულეთ წინადადებები 🗣️', 'როცა სიტყვა ავიწყდება, ხელებით განიშნებთ და ელოდება, რომ გამოიცნობთ? მისი ლექსიკური მარაგი იზრდება, მაგრამ ტვინი ენაზე სწრაფად მუშაობს. მოთმინებით დაუსრულეთ წინადადება და დააკვირდით, როგორ გამოეხატება სახეზე შვება: „ჰო, ზუსტად ამის თქმა მინდოდა“.'),
  ('3f9c24cf-68b9-4b5b-9e40-a3652b7d443e', 'მამასთან დივანზე ჭიდაობა 🤼‍♂️', 'დაძინებას რომ თავი აარიდოს, გაიქცა და დაიმალა? ახლა მამას გადააბარეთ. დივანზე გასართობად იჭიდაონ. ეს ხმაურიანი, ოფლის მომგვრელი თამაში მამასთან ერთად ბავშვს დარჩენილ ჯიუტ ენერგიასაც დაახარჯვინებს და ძილს ადვილად დანებდება.'),
  ('4d053e9f-b091-45c7-9c6a-66e7f1ab590e', 'ბოსტნეულის დამალვის ხელოვნება 🥦', 'წვნიანში სტაფილოს ერთადერთი ნაჭერი იპოვა და თქვა: „ამას არ შევჭამ“? ბოსტნეული პიურედ აქციეთ და სოუსებში შეურიეთ — ვნახოთ, ახლა როგორ იპოვის! ოსტატურად აჯობეთ მის კულინარიულ გამჭრიახობას.'),
  ('db42b564-536c-485c-afff-dce099e8c451', 'ფრენა მინდა! 🕊️', 'დივნიდან ხტება, ხელებს აფარფატებს და თქვენზე ბრაზდება, რადგან ვერ დაფრინავს? ფიზიკის კანონების სწავლება ჯერ ადრეა. უთხარით: „ვერ დაფრინავ, რადგან ფრთები ჯერ კიდევ გეზრდება“ და მისი ყურადღება რბილ ზედაპირზე ხტომისკენ მიმართეთ.'),
  ('76fc525d-97d8-486f-adde-6d0bdc417bbe', '„ეს ჩემია!“ ამბოხი 🧸', 'დისტანციურ პულტს გულში იხუტებს და ამბობს: „ეს ჩემია!“? ის საკუთრების საზღვრებს ამოწმებს. ნუ უწოდებთ ეგოისტს. უთხარით: „გმადლობ, რომ მიპოვე“, ყურადღება სხვა თამაშზე გადაატანინეთ და პულტი მშვიდად გამოართვით.'),
  ('ca5fc44a-790c-4b6a-b1b9-dcd31a3b298b', 'ზარის დარეკვისას ვიძინებთ ⏱️', 'დაძინების დრო სულ უფრო იწელება. წყალი, ტუალეტი, კედელთან დამშვიდობება... ტელეფონზე ტაიმერი დააყენეთ. შემოიღეთ წესი: როგორც კი ზარი დაირეკება, ყველა შუქს აქრობს. ბავშვებს გარე ავტორიტეტისადმი დამორჩილება ყოველთვის უფრო უადვილდებათ.'),
  ('f24ccc35-5845-4b4b-803c-db7a68218026', 'არავის წინაშე ხართ ანგარიშვალდებული 🛑', 'დღეს მოთმინება დაკარგეთ და ხმას აუწიეთ? თავს ნუ დასჯით. განწყობის დღიურში ჩაწერეთ: „მე კარგი დედა ვარ, უბრალოდ დღეს ძალიან დავიღალე“. საკუთარ თავს თანაგრძნობით მოეპყარით — თქვენგან სრულყოფილებას არავინ მოელის.'),
  ('3fdd99bb-9e81-4b54-a9b9-28997c15bd09', 'დედის ენერგეტიკული ბარი 🥗', 'ბავშვის გამოსაკვებად სხვადასხვა მენიუ მოამზადეთ, მაგრამ თავად რა მიირთვით? ჯანსაღ რეცეპტებში მოძებნეთ და მოამზადეთ დედებისთვის განკუთვნილი მარტივი 5-წუთიანი სალათი.'),
  ('8e09c446-7bb4-4213-903b-ca0d9d539235', 'ცხელი ჩაი სიჩუმეში ☕', 'ბავშვმა როგორც იქნა დაიძინა. შეხედეთ ოთახის შუაგულში მიმოფანტულ სათამაშოებს და ღრმად ჩაისუნთქეთ. ახლა ნუ აალაგებთ! დაისხით ცხელი ჩაი, მოკალათდით დივანზე და უბრალოდ დატკბით სიმშვიდით, რომელსაც ეს სიჩუმე გჩუქნით.'),
  ('b85f6433-c512-4f2e-a5d4-b9023f0eb544', 'ხანგრძლივი საუბრები უსულო საგნებთან 🗣️', 'პარკში ქვას ან სახლში სკამს სრულიად სერიოზულად ესაუბრება? თამაშის საშუალებით ის წესებს სწავლობს და სამყაროს შეიცნობს.'),
  ('294ce10a-4fac-4bfb-8007-e2e3fea714ad', 'საკუთარი ნახატის კრიტიკა 🖍️', 'თავისი გავლებული ხაზი არ მოეწონა, თქვა „ცუდად გამომივიდა“ და ფურცელი დახია და გადააგდო? მას თვითკრიტიკისა და სრულყოფილებისკენ სწრაფვის განცდა უჩნდება! უთხარით: „მოდი, შემდეგ ჯერზე სხვა ფერი ვცადოთ“ და მისი იმედგაცრუება მხარდამჭერ აღმოჩენად აქციეთ.'),
  ('76df67fe-b947-400d-8825-c8fd1637478f', 'ჩუმი ნუგეში საზოგადოებაში 💬', 'ძალიან დაიღალეთ და ვინმესთან გულის გადაშლაც კი არ გსურთ? შედით Anacan-ის საზოგადოებაში და უბრალოდ მკითხველად დარჩით. იმის ნახვა, თუ როგორ უმკლავდებიან სხვა დედები ზუსტად ასეთივე აბსურდულ კრიზისებს, თქვენთვის ყველაზე ძლიერი უხმო ნუგეში გახდება.'),
  ('882a14e7-4dd7-4a8b-8fa7-7bd5afe17ad2', 'ოკეანის ქარიშხალი აბაზანაში 🌊', 'ბანაობა მხოლოდ საბაბია და სინამდვილეში აბაზანაში ოკეანე მოაწყო და ტალღებით თამაშობს? აცადეთ თამაში. წყლის ხმაური და შხეფები მასში დაგროვილ ამოუწურავ, ჯიუტ ენერგიას თან გაიყოლებს. საღამოს ყოველგვარი წინააღმდეგობის გარეშე ჩაწვება საწოლში.'),
  ('3e4c8054-2b97-4968-a10f-267dccb5b8c0', 'მოულოდნელი დილის ფილოსოფია 🤔', 'მოულოდნელად მეცნიერული კითხვა დაგისვათ: „რატომ არ ჩანს ქარი?“ ნუ დაიბნევით! გახსენით Anacan AI, მიიღეთ ამ ასაკისთვის გასაგები, ყველაზე საყვარელი, ზღაპრული პასუხი, რომელიც პედიატრისა და ფსიქოლოგის მიერაა მოწონებული, და წაუკითხეთ. თქვენ ყოველთვის ყველაფრის მცოდნე დედა ხართ!'),
  ('b7b7faa9-f807-43f1-bf54-6d7f963c5e32', 'უბრალოდ მშვიდად წამოწოლა 🛋️', 'ის თავისით აწყობს ფაზლს და სახლში მოულოდნელად სიჩუმეა? გთხოვთ, ეს წამები სახლის დაგვას არ მოახმაროთ! დივანზე წამოწექით. თქვენი ბატარეაც უნდა დაიმუხტოს, რომ საღამომდე ამ ტემპს გაუძლოთ. აუცილებლად დაისვენეთ.'),
  ('ccae9470-c321-4925-94c0-7408317b4c14', 'ჯიბიდან ამოღებული განძი 🪨', 'შარვლის რეცხვისას ჯიბეში გამხმარი ფოთოლი ან ქვა იპოვეთ? ეს სიხარბე კი არა, ბავშვური კვლევა-ძიებაა. სერიოზული სახით გადააგდეთ ნაგავში, მაგრამ გულში გაუღიმეთ ამ პატარა შემგროვებელს — ის სამყაროს აღმოაჩენს.'),
  ('039b7451-67d0-43b6-9ed0-d4ec9bf47752', 'ქურთუკზე უარის თქმა 🧥', 'გარეთ მზეა და ამიტომ ზამთრის ქურთუკის ჩაცმა არ სურს? ფანჯრიდან დანახულმა სურათმა არ მოგატყუოთ. გახსენით „ამინდი და ჩაცმულობა“ და ტელეფონში ზამთრის ტანსაცმელში გამოწყობილი ბავშვის სიმბოლო აჩვენეთ. წესის ახსნა ციფრულ ეკრანს მიანდეთ და თავად განზე გადექით.'),
  ('1d2e4dc8-5a7a-4aed-ab26-9b7c8dd5179c', 'დამალობანა საწოლის ქვეშ 🛏️', 'საწოლში კი არა, აუცილებლად საწოლის ქვეშ დაძინება სურს? ასეთი პატარა, დახურული სივრცეები მას ისეთივე დაცულობის განცდას უქმნის, როგორსაც დედის საშვილოსნოში გრძნობდა. ნება მიეცით, იქ დაიძინოს, ჩაძინების შემდეგ კი ფრთხილად გადააწვინეთ საწოლზე — გაუფრთხილდით თქვენს ენერგიას.'),
  ('73a43849-8300-493d-9040-f05eaf01e5b6', 'ყინულივით ცივი ალოგიკურობა 🥶', 'იმის ნაცვლად, რომ ცხელ ჩაის შეუბეროს, აუცილებლად ყინულის ჩაგდებას გთხოვთ? ის სიცხისა და სიცივის ურთიერთსაპირისპირო ბუნებას სწავლობს. მიეცით ყინული და დააკვირდეს, როგორ დნება. საუზმე რომც დაგვიანდეს, სამაგიეროდ, საკუთარ სამეცნიერო აღმოჩენას გააკეთებს.'),
  ('1171703b-c644-4ad0-8298-a24063264467', 'ზღაპრების ოთახი წვიმის ხმით 🌧️', 'ხმა აღარ გაქვთ და არც ზღაპრის წაკითხვის ძალა შეგრჩათ? „ჭკვიან ზღაპრებში“ ფონად მხოლოდ წვიმისა და ტყის ხმები ჩართეთ. ბუნების ამ მონოტონურ სიმშვიდეს ზოგჯერ ყველაზე კარგ და ამაღელვებელ ისტორიაზე სწრაფად შეუძლია ბავშვის მოჯადოება და დაძინება.'),
  ('43e7fbfe-64bc-4627-85d6-4ddae59c6985', 'სარკეში საკუთარ თავზე ბრაზდება 🪞', 'სარკის წინ დგება, სხვადასხვა ხმას გამოსცემს და სახეებს იღებს? ეს თვითშეგნების გაძლიერების ნიშანია. ის საკუთარ სხეულსა და იმას აკვირდება, როგორ გამოიყურება მისი ემოციები გარედან. ჩუმად დააკვირდით გვერდიდან.'),
  ('5b1cbac6-ecf8-4886-b2f1-c0e88c8559b5', 'შეხების რევოლუცია 🔋', 'მთელი დღე ფეხზე გეკვრებათ და ჩახუტებას ითხოვს? ფიზიკურად გამოიფიტეთ. შეხებით გადაღლას განიცდით. დატოვეთ ბავშვი ოთახში თავის სათამაშოებთან, 5 წუთით სააბაზანოში შეიყუჟეთ და კარი დახურეთ. უბრალოდ შეიგრძენით განმარტოება.'),
  ('14317db1-b6eb-40d2-8404-59bcea4acdf7', 'მამის ძილის მომგვრელი ზღაპარი 📖', 'ხმა დაგეღალათ და ზღაპრის წასაკითხად ძალა აღარ გაქვთ? ახლა მამას გადააბარეთ. მამის განსხვავებული, ბოხი ხმა და მის მიერ მოფიქრებული აბსურდული დეტალები ბავშვს თქვენს ნაცნობ ხმაზე უფრო სწრაფად მოადუნებს და დააძინებს.'),
  ('5d28c236-3ed8-4900-b875-c6d0d9b2aa20', 'სპექტაკლი „ვინ ხარ?“ 🎭', 'დილით ისე შემოგხედათ, თითქოს უცხო იყავით და გკითხათ: „ვინ ხარ? დედაჩემი სად არის?“ ეს ახალი როლური თამაშია. უთხარით: „მე მეზობელი დეიდა ვარ, დედაშენი მალე მოვა“. დაე, დილიდან ოთახი სიცილით აივსოს — ეს გაჯიუტებასთან შედარებით ბევრად ნაკლებ ენერგიას წაგართმევთ.'),
  ('8758179c-cc13-42d7-b2c1-4900aea35e3a', 'თავის საჭმელს არ გაგინაწილებთ 🍳', 'თავისი თეფშიდან არაფერს გაძლევთ, მაგრამ დაჟინებით ითხოვს თქვენი თეფშიდან ჭამას? ბავშვები მშობლების არჩევანს ყოველთვის ბოლომდე ენდობიან. ნუ შეეწინააღმდეგებით — ლუკმა სიყვარულით გაუწოდეთ და ამ სასაცილო ეგოიზმზე უბრალოდ გაიღიმეთ.'),
  ('12a06ab8-bcee-4772-8e2b-6f509250a594', 'ფრენა მინდა! 🕊️', 'დივნიდან ხტება, ხელებს იქნევს და გიბრაზდებათ, რადგან ვერ დაფრინავს? ფიზიკის კანონების ასახსნელად ჯერ ადრეა. უთხარით: „ვერ დაფრინავ, რადგან ფრთები ჯერ კიდევ გეზრდება“ და მისი ყურადღება რბილ ზედაპირზე ხტომისკენ მიმართეთ.'),
  ('e80a8c85-c67a-45b2-8209-90553a33fb5f', 'ტელეფონის ქურდი 📱', 'ჩაის დასხმისას აღმოაჩინეთ, რომ ტელეფონი გაქრა, ის კი დივნის უკან იმალება და თქვენ გბაძავთ: „ალო“? ის თქვენს ციფრულ ჩვევებს იმეორებს. მოწყობილობის გამორთმევისას უთხარით: „ჩემს ტელეფონსაც მოუნდა შენთან საუბარი“ და სიცილით გამოართვით.'),
  ('ebb45c07-d4c6-4504-ac39-3e83655d3e00', 'წყვილივით, სიჩუმეში 🥂', 'ბავშვმა დაიძინა, სახლი დალაგებულია. მეუღლესთან ერთად დივანზე გვერდიგვერდ დაჯექით და ტელევიზორიც კი არ ჩართოთ. უბრალოდ ერთმანეთს შეხედეთ მზერით, რომელიც ამბობს: „ესეც შევძელით, გადავრჩით“. დამიჯერეთ, გადაღლილი მშობლებისთვის გუნდურობის ყველაზე ნამდვილი მომენტი სწორედ ეს არის.'),
  ('2a662eb4-1c17-46f1-ad5d-c566286402e8', 'დავა პარკში 🤝', 'სასრიალოზე სხვა ბავშვს ხელი ჰკრა, რომ თვითონ ჩამოსრიალებულიყო? ყველა თქვენ გიყურებთ. უხერხულობის გამო ბავშვს ნუ დაარტყამთ. მშვიდი, მაგრამ მტკიცე ხმით შეახსენეთ წესი: „ახლა მისი ჯერია, შემდეგ კი ჩვენ ჩამოვსრიალდებით“. ეს ასე მუშაობს.'),
  ('c0dcbfbe-b91a-462c-890d-a8770be19cf3', 'დილაუთენია სირბილობანა 🏃‍♂️', 'დილის 7 საათზე დივნებზე დარბის? ნუ უყვირებთ. საქმე 2 წუთით გადადეთ და თქვენც ხტუნვით შეუერთდით. ბავშვის წარმოსახვით სამყაროში ჩართვა შეიძლება უცნაურად მოგეჩვენოთ, თუმცა ეს თქვენთვისაც სტრესის მოხსნის ძალიან ეფექტური საშუალებაა.'),
  ('e41be904-7cb3-4dd6-8966-ea3b375783f6', 'ღამის შიშის მეცნიერული გამოსავალი 🔦', 'საძინებელში ჩრდილების ეშინია? ოთახს სრულად ნუ დააბნელებთ — დადგით თბილი ფერის პატარა ღამის სანათი. ის მელატონინის გამომუშავებას ხელს არ უშლის, ბავშვს კი უსაფრთხოების განცდას უქმნის და შიშის დაძლევაში ეხმარება.'),
  ('b5588608-ef71-4787-b05e-09f4f4f2492a', 'მოულოდნელი „მიყვარხარ“ 💖', 'ოთახის შუაგულში თამაშისას მოულოდნელად შემოგხედავთ, სირბილით მოვა და კისერზე შემოგეხვევათ. ამად ღირს ყველა უძილო ღამე და დაღლილობა! შეიგრძენით ამ წამით მოტანილი ღრმა და განუმეორებელი სიმშვიდე და ცოტა ხნით დაივიწყეთ მთელი ქაოსი.'),
  ('e2ac4132-1e14-42d5-a828-9c40ffb00179', 'ჩურჩულის მისტიკური ძალა 🤫', 'საწოლიდან გარბის და აქეთ-იქით დახტის? მოულოდნელად ძალიან დაუწიეთ ხმას. დაიწყეთ ძალიან ჩუმად, ჩურჩულით საუბარი. თქვენს გასაგონად ყურადღების მოკრება მოუწევს, 5 წუთში კი მისი ტვინი დაიღლება და ძილის რეჟიმზე გადაერთვება. სცადეთ!'),
  ('f5be8b0c-0a17-4790-b9b1-73d205d64a76', 'Instagram-დედების ილუზია 📱', 'Instagram-ის გახსნისთანავე სხვების დალაგებულ სახლებსა და ჭკვიან ბავშვებს ხედავთ და გული გიტყდებათ? წაშალეთ ეს აპლიკაცია! შეუერთდით Anacan-ის საზოგადოებას. წაიკითხეთ იმ ნამდვილი დედების ისტორიები, რომელთა სახლიც თქვენსავით არეულია, ბავშვი კი — ჯიუტი.'),
  ('add15a56-d6d1-4819-af57-b57688cec0f4', 'ზღაპრის წაკითხვის გარეშე დაძინება 🪄', 'ამ საღამოს ზღაპრის წასაკითხად ძალა აღარ გაქვთ? ჩართეთ ჭკვიანი ზღაპრები. ფონად მხოლოდ ჩურჩულით სავსე ტყისა და ქარის ხმები დატოვეთ. სიბნელეში ბუნების ამ ხმებს მოუსმინეთ და ორივემ დაისვენეთ ხმაურისგან. ვიზუალური დაღლილობა მაშინვე გაქრება.'),
  ('b000be1e-116f-4403-b926-fe4428d04231', 'ჩემში დაგროვილი ბრაზის დაწერა 📝', 'ვერავინ ხედავს, სახლში რამდენად იღლებით და ეს მოთმინებას გაკარგვინებთ? გახსენით განწყობის დღიური. ყველაფერი, რამაც დღეს ჭკუიდან გადაგიყვანათ, იქ დაწერეთ. ყალბი ღიმილის ნაცვლად, ემოციის მიღება და მისი დაწერა ბევრად მეტად დაგეხმარებათ.'),
  ('f9e06d3b-098b-4aa8-b407-0f31bbbcfcf8', 'მე ვიცი, თქვენც გასწავლით ☝️', 'მოდის და იმას, რაც უკვე იცით, ძალიან სერიოზული და ჭკვიანური გამომეტყველებით გიხსნით? ასე საკუთარ გონიერებას ამოწმებს. სიცილი რომ შეიკავოთ, ტუჩზე იკბინეთ, მაგრამ ძალიან სერიოზულად მოუსმინეთ და უთხარით: მართლა? დიდი მადლობა. ცოტათი თავდაჯერებაც აუმაღლეთ.'),
  ('5b3e259a-f085-41f9-b9ba-e7ff8789e89c', 'წყალდიდობა აბაზანაში 🌊', 'ბანაობა მხოლოდ საბაბია, სინამდვილეში კი აბაზანაში ოკეანე მოაწყო და ტალღებით თამაშობს? აცადეთ თამაში. წყლის ხმაური და შხეფები მასში დაგროვილ უსასრულო, ჯიუტ ენერგიას თან გაიყოლებს. საღამოს ყოველგვარი წინააღმდეგობის გარეშე დაწვება დასაძინებლად.'),
  ('7c552cb2-0d81-4027-8eba-e235f8359b1d', 'სამზარეულოში გეხმარებათ 🧑‍🍳', 'ცომს რომ აბრტყელებდით, მოვიდა, სკამი მოიდგა და დაჟინებით მოითხოვა, ფქვილი თავად მოეყარა? თუ არ მისცემთ უფლებას, ატირდება. მიეცით პატარა პლასტმასის ჯამი და ცოტაოდენი ფქვილი. სამზარეულო აირევა, მაგრამ მისი სერიოზული მზარეულის გამომეტყველება ამ დალაგებად ნამდვილად ღირს.'),
  ('86e3829d-08da-4b37-867c-0faf0ab2fa1c', 'მაღაზიის შუაგულში გაშეშება 🛒', 'მაღაზიის შუაგულში გაჩერებულხართ და გიფიქრიათ: რის საყიდლად მოვედი? დედის გონება მართლაც ძალიან გადატვირთულია. აპლიკაციაში საყიდლების სია გახსენით და ამ ციფრულ მეხსიერებას მიენდეთ — ის ამ ქაოსიდან ყოველთვის გიხსნით.'),
  ('202773be-9378-4cfa-915c-7cbc9e98cdc2', 'მაისურის იარლიყი ჩხვლეტს! 🏷️', 'არ იცვამს, რადგან ზურგზე პატარა იარლიყი ნემსივით ჩხვლეტს? ამ ასაკში სენსორულმა მგრძნობელობამ შეიძლება ჭკუიდან გადაგიყვანოთ. ნუ შეეკამათებით — აიღეთ მაკრატელი, ძირში მოაჭერით და ეს პატარა კრიზისი წამებში დაასრულეთ.'),
  ('65b5e1a3-f9ad-4e00-a2af-7ae096f9121d', 'იდეალური სიჩუმის წამები 🛋️', 'ისე გატაცებით აწყობს ფაზლებს, რომ სახლში მოულოდნელად სიჩუმე ჩამოვარდა? ეჭვებს ნუ აჰყვებით, მაშინვე დაისხით ყავა. ეს იშვიათი და ოქროს წუთები დალაგებას ან სარეცხს კი არა, დასვენებასა და ჭერის ყურებას დაუთმეთ. თქვენ რობოტი არ ხართ.'),
  ('a86a31ee-9e29-4f41-aa7c-1edc94992d88', 'შუაღამის უეცარი ყვირილი 😭', 'ღამით თვალდახუჭული, ტირილით გაიღვიძა და თქვენი არ ესმის? ტირილის ხასიათს დააკვირდით — ეს ღამის შიშია. ეცადეთ, არ გააღვიძოთ; უბრალოდ მის გვერდით დარჩით, ხელი ჩაჰკიდეთ და მოეფერეთ. თავისით დამშვიდდება და კვლავ ღრმა ძილს მიეცემა.'),
  ('5430bad3-c2db-4b2e-bb46-e51168e8dd91', 'Anacan-ისგან წერილი გაქვთ 💌', 'ჯანსაღ კერძებში დამალული ბოსტნეული, განწყობის დღიურში ჩაღვრილი ცრემლები და გამოფიტვის წუთები... ამ 4 წელიწადში თქვენ მსოფლიოში ყველაზე რთულ პროფესიას დაეუფლეთ. ახლა უკვე გმირი ხართ, რომელსაც არცერთი აპი აღარ სჭირდება და ქაოსს საკუთარი ინტუიციით მართავს. ჩვენ მხოლოდ ფონზე მყოფი მეგზური ვიყავით — მთავარი საქმე თქვენ გააკეთეთ!'),
  ('7c7b74a0-c6ab-409c-babd-0085e345da09', '1460-ე დღე: ჩვენ ეს შევძელით! 🚀', 'დილით იღვიძებთ და უყურებთ... ის უკვე ზუსტად 4 წლისაა! უკვე 1460 დღეა, რაც უძილობას, კრიზისებსა და სიჯიუტეს უმკლავდებით და ამ პატარა ადამიანს ზრდით. ამ წლების განმავლობაში თქვენ არა მხოლოდ ბავშვი გაზარდეთ, არამედ საკუთარ თავში ძლიერი, დაუმარცხებელი ახალი დედაც შექმენით. დღეს არავითარი წესი არ არსებობს — უბრალოდ ჩაეხუტეთ და სიამაყით შეხედეთ თქვენს მიერ შექმნილ ამ სასწაულს.'),
  ('e37bc161-dfcf-4941-bac0-6c7cfe6f4ba2', 'ბოლო შეტყობინება, ბოლო სიჩუმე 🌌', 'მას ჩაეძინა. ჩააქრეთ შუქი. ეს აპიდან თქვენთვის გამოგზავნილი ბოლო შეტყობინებაა. 1460 დღის განმავლობაში, როცა იღლებოდით, ტიროდით და თავს კუთხეში მომწყვდეულად გრძნობდით, ვცდილობდით, გაგვეგო თქვენი და ჩუმად ვყოფილიყავით თქვენ გვერდით. ახლა ტელეფონი გვერდზე გადადეთ. თქვენ სრულყოფილი ხართ, თქვენ საკმარისი ხართ. ამიერიდან ამ შესანიშნავ ისტორიას თავად, დამოუკიდებლად დაწერთ. თქვენთან ერთად ამ გზის გავლა ჩვენთვის დიდი პატივი იყო. შეხვედრამდე, დედიკო! ❤️'),
  ('a57ba6d4-a9da-4163-8ddf-e60b3ee296c5', 'დედების საიდუმლო ჯგუფი 💬', 'რთული გადაწყვეტილება გაქვთ მისაღები? (მაგალითად, საბავშვო ბაღის არჩევა). Anacan-ის საზოგადოებაში გამოცდილი დედების რჩევები ყველაზე რეალური, პრაქტიკაში გამოცდილი გამოსავალია, რომლის შესახებაც ვერცერთ წიგნში ვერ წაიკითხავთ.'),
  ('2e1371fa-bf2b-4fc1-b3c0-c7f4619346f4', 'გამორთეთ შუქები, რომ ძილი მოვიდეს 🌙', 'დაძინების დასაჩქარებლად, ძილის წინ 1 საათით ადრე ოთახში გამორთეთ ტელევიზორისა და ტელეფონის ყველა ეკრანი. სიბნელეში მელატონინი სწრაფად გამოიყოფა — მიეცით ბუნებრივ პროცესს საშუალება, თქვენ ნაცვლად იმუშაოს.'),
  ('be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e', 'სიჩუმის ციფრული საზომი 🤫', 'მას ბოლოს და ბოლოს ჩაეძინა! ვერ იჯერებთ, რომ სახლში ასეთი სიჩუმე ჩამოწვა. ჩართეთ ხმის საზომი და ეკრანზე გამოსახულ 0-10 დეციბელის მაჩვენებელს უყურეთ — ასე თვალნათლივ იგრძნობთ, როგორ მშვიდდება და ნელ-ნელა ძალებს იკრებს თქვენი გონება.')
) AS v(id, t, b)
WHERE x.id = v.id;

-- Yoxlama: hər ikisi ~0 olmalıdır (boş-mənbə sətirləri istisna olmaqla)
SELECT
  (SELECT count(*) FROM public.pregnancy_day_notifications WHERE title_ka IS NULL) AS preg_ka_bos,
  (SELECT count(*) FROM public.mommy_day_notifications WHERE title_ka IS NULL) AS mommy_ka_bos;
